  @@unique([discussionboard_comment_id, discussionboard_member_id, discussionboard_report_type_id])
  @@index([created_at])
  @@index([reason(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-07-moderation.prisma:
/// Discussion Board Report Record - Implements the reporting and escalation flow described in the requirements (see 'Business Rules & Workflows,' 'Moderation & Escalation Workflows').
///
/// Business Purpose: Captures member-initiated reports on inappropriate content or suspicious users, forming the starting point for moderation review. Maintains 3NF compliance by separating report metadata from other business entities. For example, a member reporting a post or comment for spam or abuse will be registered as a discussionboard_reports entry referencing the reported item and the reporting member.
///
/// Key relationships: Connects to report type, target object (via foreign key to posts, comments, or users), and the reporting actor (from already created discussionboard_members table).
/// Special behaviors: Supports audit trail, links to downstream moderation actions, and enforces one report per object/member per unique incident.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_reports {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for the report record.
  id String @id @db.Uuid

  /// Associated report type {@link discussionboard_report_types.id} identifying the reason for report (e.g., spam, abuse, misinformation).
  discussionboard_report_type_id String @db.Uuid

  /// The reporting member's {@link discussionboard_members.id} who filed the report.
  reporting_member_id String @db.Uuid

  /// Target business object being reported (post, comment, or user, as per assignment). The true type is determined by context on review. Implements the polymorphic target pattern in a fully normalized way (all references are UUIDs only).
  target_object_id String @db.Uuid

  /// Type of object being reported. Implements requirement to generalize reporting (e.g., 'post', 'comment', 'member'). Used by moderation workflows to route and describe moderation procedures.
  target_object_type String

  /// Reporter supporting detail or description. Implements requirement for explanation or supporting evidence. Maintains normalization: only the specific explanation for this incident.
  report_description String?

  /// Timestamp of report creation. Implements audit trail and supports compliance/SLA tracking as required by moderation workflow.
  reported_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_discussionboard_reports_report_type discussionboard_report_types @relation(fields: [discussionboard_report_type_id], references: [id], onDelete: Cascade)
  fk_discussionboard_reports_reporting_member discussionboard_members @relation(fields: [reporting_member_id], references: [id], onDelete: Cascade)

  discussionboard_moderation_actions discussionboard_moderation_actions[]
  discussionboard_bans discussionboard_bans[]
  discussionboard_warnings discussionboard_warnings[]

  @@index([discussionboard_report_type_id])
  @@index([reporting_member_id])

  @@unique([target_object_id, target_object_type, reporting_member_id])
  @@index([reported_at])
}

/// Report Type Registry - Implements the classification of reportable incident subjects (see Business Requirements, Content Quality Assurance, and Moderation documentation).
///
/// Business Purpose: Provides an extensible classification system for report reasons (e.g., spam, abuse, misinformation) as required for moderation triage. Maintains 3NF compliance by separating report type code/label definitions from actual reports.
///
/// Key relationships: Referenced by discussionboard_reports entries.
/// Special behaviors: Codes must be unique. Used by the frontend to present selectable reasons for reporting content.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_report_types {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Short, unique report type code (e.g., 'spam', 'abuse'). Used for frontend and backend logic to reference the report type.
  code String

  /// User-visible name of the report type for UI display.
  display_name String

  /// Long-form description for mods/admins. Clarifies what constitutes this report type. Aids in moderation process training.
  description String?

  /// Whether this report type is currently selectable (e.g., deprecated types are marked inactive, for regulatory or policy changes).
  active Boolean

  /// Timestamp when this type was created (registry audit trail, required for governance and compliance tracking).
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussionboard_post_reports discussionboard_post_reports[]
  discussionboard_comment_reports discussionboard_comment_reports[]
  discussionboard_reports discussionboard_reports[]

  @@unique([code])
  @@index([active])
  @@index([display_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Moderation Action Record - Implements the 'Action Workflow' and audit requirements specified for both moderators and admins (see Workflows section, Requirement 3: "Moderation & Reporting").
///
/// Business Purpose: Tracks every moderation intervention taken in response to reports: edits, deletions, warnings, bans, pin/unpin, locks.
///
/// Maintains normalization by linking to the originating report (if any), the acting moderator/admin, and the target object. No pre-calculated summaries or denormalization.
///
/// Key relationships: Connects to discussionboard_reports; references acting moderator/admin (otherComponents); links to object of action (via polymorphic pattern).
/// Special behaviors: Each action includes rationale, timestamps, and type.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_moderation_actions {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each moderation action.
  id String @id @db.Uuid

  /// Associated report {@link discussionboard_reports.id} if this action originates from a user report (nullable for proactive/patrol actions).
  report_id String? @db.Uuid

  /// Acting moderator or admin {@link discussionboard_moderators.id or discussionboard_admins.id} who performed the action.
  acting_moderator_id String @db.Uuid

  /// Target business object being moderated (post, comment, member, etc.). Same pattern as reports for generalized reference.
  target_object_id String @db.Uuid

  /// Type of object being moderated ('post', 'comment', 'member', 'board', etc.). Maintains the normalized reference per domain context.
  target_object_type String

  /// Type of moderation action taken (e.g., 'warn', 'edit', 'delete', 'ban', 'lock', 'pin', etc.). Enables analytics integration for action type filtering.
  action_type String

  /// Explanation and notes justifying the action. Fulfills requirement for rationale documentation and behavioral transparency. Maintains 3NF (no cross-table references stored here).
  rationale String

  /// Timestamp when the action was performed. Used for audit log, SLA tracking, and analytics.
  actioned_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_moderation_actions_report discussionboard_reports? @relation(fields: [report_id], references: [id], onDelete: Cascade)
  fk_moderation_actions_moderator discussionboard_moderators @relation(fields: [acting_moderator_id], references: [id], onDelete: Cascade)

  @@index([report_id])
  @@index([acting_moderator_id])

  @@index([actioned_at])
  @@index([rationale(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Ban/Suspension Record - Implements member bans and suspensions per Moderation business rules and workflows (see escalation section, warnings > temp ban > perm ban).
///
/// Business Purpose: Captures formal restrictions on members' system access/abilities after infractions are verified. Retains 3NF by referencing the subject (member id), the moderator/admin, and the originating report or rationale (if present).
///
/// Key relationships: Links to ban subject (member), acting moderator/admin, and referenced report.
/// Special behaviors: Multiple bans per member possible if for separate incidents. Each ban is atomic and historical for audit/compliance. Dates track duration and compliance requirements.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_bans {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// The banned member's {@link discussionboard_members.id} subject to ban action.
  banned_member_id String @db.Uuid

  /// Moderator/admin {@link discussionboard_moderators.id or discussionboard_admins.id} who enacted the ban (compliance/audit).
  acting_moderator_id String @db.Uuid

  /// Originating {@link discussionboard_reports.id} if the ban was triggered by a specific report (nullable for proactive major bans).
  report_id String? @db.Uuid

  /// Ban reason (human-meaningful summary for compliance/audit, visible in appeals workflows).
  reason String

  /// Type: 'temporary' or 'permanent' as per business rules (see moderation escalation workflows).
  ban_type String

  /// Start datetime of the ban (when enforced).
  banned_at DateTime @db.Timestamptz

  /// When ban ends (nullable for permanent bans). Maintains normalized structure for expiry logic.
  expires_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_bans_banned_member discussionboard_members @relation(fields: [banned_member_id], references: [id], onDelete: Cascade)
  fk_bans_acting_moderator discussionboard_moderators @relation(fields: [acting_moderator_id], references: [id], onDelete: Cascade)
  fk_bans_report discussionboard_reports? @relation(fields: [report_id], references: [id], onDelete: Cascade)

  @@index([acting_moderator_id])
  @@index([report_id])

  @@index([banned_member_id])
  @@index([banned_at])
}

/// Warning Issuance Record - Implements the warning step in the moderation escalation pipeline (see Business Rules, "Members receive warnings for policy violations; repeated offenses escalate").
///
/// Business Purpose: Records the issuance of official warnings to members, described as the first step in the escalating penalty process. 3NF compliance is maintained by linking each warning to the subject member and the moderator/admin, as well as any originating report. Warnings are atomic events, not aggregated (no counts or derived statuses are stored here).
///
/// Key relationships: Related to members (warned_member_id), linked to moderator/admin, and can reference a report.
/// Special behaviors: Multiple warnings per member are possible; each is an independent event for audit trail and escalation automation.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_warnings {
  //----
  // COLUMNS
  //----
  /// Primary Key for each warning record.
  id String @id @db.Uuid

  /// Member who receives the warning {@link discussionboard_members.id}.
  warned_member_id String @db.Uuid

  /// Moderator/admin issuing the warning {@link discussionboard_moderators.id or discussionboard_admins.id}.
  acting_moderator_id String @db.Uuid

  /// Report that caused the warning (nullable if warning is preemptive or for off-platform evidence).
  report_id String? @db.Uuid

  /// Warning reason, descriptive text stating the violation or risk observed. Implements need for clarity and behavioral documentation.
  reason String

  /// Timestamp when warning was applied. Maintains full audit traceability.
  warned_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_warnings_warned_member discussionboard_members @relation(fields: [warned_member_id], references: [id], onDelete: Cascade)
  fk_warnings_acting_moderator discussionboard_moderators @relation(fields: [acting_moderator_id], references: [id], onDelete: Cascade)
  fk_warnings_report discussionboard_reports? @relation(fields: [report_id], references: [id], onDelete: Cascade)

  @@index([acting_moderator_id])
  @@index([report_id])

  @@index([warned_member_id])
  @@index([warned_at])
}

schemas.schema-08-analytics.prisma:
/// Tracks post, comment, and voting engagement across users, threads, boards, and time windows. Implements business requirements from analytics use cases (see doc 01 and 02), providing the basis for DAU/WAU charts, cohort analysis, board-level tracking, and moderation metrics. Maintains 3NF by atomically tracking metrics by entity and period, with all pre-calculated/aggregated fields in materialized views only. For example, storing counts of posts, comments, reactions (upvotes/downvotes) per entity per period (e.g., daily). Referenced by analytics dashboards; connects to members, boards, and time periods for detailed engagement breakdowns. Special behaviors: Ensures only raw, non-pre-aggregated, normalized metrics for further processing; NO denormalized fields here.
///
/// @namespace Analytics
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_engagement_metrics {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each engagement metric record.
  id String @id @db.Uuid

  /// The member whose engagement is being recorded. Points to {@link discussionboard_members.id} in Actors domain. Supports analytics per user metric.
  discussionboard_member_id String? @db.Uuid

  /// The board where engagement occurs. Points to {@link discussionboard_boards.id} in Boards domain. Enables board-level metric analysis.
  discussionboard_board_id String? @db.Uuid

  /// Date for the measured engagement activity. Used for time-bucketed DAU/WAU analysis. Normalization: atomic date, not derived.
  engagement_date DateTime @db.Timestamptz

  /// Number of posts created by the referenced member on the board for the day. Implements requirement for tracking post volume. Not pre-aggregated; count is atomic per user/board/date.
  posts_created_count Int @db.Integer

  /// Number of comments created. Supports moderation and content quality metrics.
  comments_created_count Int @db.Integer

  /// Number of voting actions (upvotes/downvotes) performed by the user on the board in the period. Fulfills analysis requirement for voting engagement.
  votes_cast_count Int @db.Integer

  //----
  // RELATIONS
  //----
  fk_engagemetric_member discussionboard_members? @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)
  fk_engagemetric_board discussionboard_boards? @relation(fields: [discussionboard_board_id], references: [id], onDelete: Cascade)

  @@unique([discussionboard_member_id, discussionboard_board_id, engagement_date])
  @@index([engagement_date])
  @@index([discussionboard_member_id, engagement_date])
  @@index([discussionboard_board_id, engagement_date])
}

/// Stores a normalized, queryable log of analytic events related to member activity across the platform, as required by doc 02 User Journeys and Analytics Use Cases. Implements raw event stream/log for tracking time series activity (e.g., logins, post creations, comment edits, account changes, board visits) for audit and analytics. Maintains 3NF: each row records precisely one event; all aggregation occurs in materialized views. Connected to member, optional thread, board, post, or comment. Used for audit, anomaly detection, rare journey tracking, and engagement heatmaps (e.g., heatmap visualizations of peak platform activity). Special: Enforces normalized, atomic event records (not summary counts).
///
/// @namespace Analytics
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_activity_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each activity log record.
  id String @id @db.Uuid

  /// Member acting in the event (nullable for system/non-member events). References {@link discussionboard_members.id}.
  discussionboard_member_id String? @db.Uuid

  /// Board related to the activity (nullable when not board-specific). References {@link discussionboard_boards.id}.
  discussionboard_board_id String? @db.Uuid

  /// Thread related to the event. Nullable if event is not thread-specific. References {@link discussionboard_threads.id}.
  discussionboard_thread_id String? @db.Uuid

  /// Post involved in the event. Nullable unless directly post-related. References {@link discussionboard_posts.id}.
  discussionboard_post_id String? @db.Uuid

  /// Comment involved in the event. Nullable unless directly comment-related. References {@link discussionboard_comments.id}.
  discussionboard_comment_id String? @db.Uuid

  /// Timestamp of the event/action for precise time series and audit. Implements analytics requirements for time-based user activity tracking.
  event_timestamp DateTime @db.Timestamptz

  /// Type of activity (e.g., 'login', 'logout', 'post_create', 'post_edit', 'post_delete', 'comment_create', 'comment_edit', 'comment_delete', 'vote', 'visit_board', 'ban', 'role_change', 'notification_viewed', etc.) Implements analytics, moderation, and auditing requirements.
  event_type String

  /// Free-form JSON, stringified, with additional event context (device, IP, old/new values, change details, etc.). Implements rare journeys analysis and audit trails.
  event_metadata String?

  //----
  // RELATIONS
  //----
  fk_activitylog_member discussionboard_members? @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)
  fk_activitylog_board discussionboard_boards? @relation(fields: [discussionboard_board_id], references: [id], onDelete: Cascade)
  fk_activitylog_thread discussionboard_threads? @relation(fields: [discussionboard_thread_id], references: [id], onDelete: Cascade)
  fk_activitylog_post discussionboard_posts? @relation(fields: [discussionboard_post_id], references: [id], onDelete: Cascade)
  fk_activitylog_comment discussionboard_comments? @relation(fields: [discussionboard_comment_id], references: [id], onDelete: Cascade)

  @@index([discussionboard_thread_id])
  @@index([discussionboard_post_id])
  @@index([discussionboard_comment_id])

  @@index([discussionboard_member_id, event_timestamp])
  @@index([event_type, event_timestamp])
  @@index([discussionboard_board_id, event_timestamp])
}

/// Tracks active/trending topics (thread/post/title combos) for the trending panel and analytics dashboards. Implements analytics requirements for highlighting trending discussions, detecting viral posts, and displaying platform trends by period. Maintains 3NF: one row per topic per period, with rankings and trend markers computed externally or in mv_ tables (no denormalized fields here). Example: records trending score of a thread in a given day, referenced for homepage highlights. Connected to threads, board; enables detection of surging topics to alert moderation or trigger notifications. Special behaviors: Atomic data only, NO pre-aggregated lists or computed fields.
///
/// @namespace Analytics
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_trending_topics {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each trending topic record.
  id String @id @db.Uuid

  /// Thread considered as trending. References {@link discussionboard_threads.id}.
  discussionboard_thread_id String @db.Uuid

  /// Board under which the trending thread is tracked. References {@link discussionboard_boards.id}.
  discussionboard_board_id String @db.Uuid

  /// Date for which the trending status/ranking is recorded. Implements period-based (e.g., daily) tracking of trending status per topic.
  ranking_period_date DateTime @db.Timestamptz

  /// Quantitative score for the topic's trending calculation—not precomputed, but source score as calculated by external analytics engine or background job. Implements requirement for ordering trending panels. (e.g., engagement-weighted activity score)
  trending_score Float @db.DoublePrecision

  //----
  // RELATIONS
  //----
  fk_trending_topic_thread discussionboard_threads @relation(fields: [discussionboard_thread_id], references: [id], onDelete: Cascade)
  fk_trending_topic_board discussionboard_boards @relation(fields: [discussionboard_board_id], references: [id], onDelete: Cascade)

  @@unique([discussionboard_thread_id, ranking_period_date])
  @@index([ranking_period_date])
  @@index([discussionboard_board_id, ranking_period_date])
}

schemas.schema-09-notifications.prisma:
/// Notification Template Entity - This implements the requirement for system-triggered notifications from the requirements document (Business Requirements: 6. Notifications & Updates, 9. Data Privacy & Protection). 
///
/// Business explanation: Enables the platform to manage, organize, and version all message templates used for member notifications (email, in-app, browser). Maintains 3NF normalization by splitting templates from notification triggers and user preferences, thus providing single-source for reusable content. For example, a template defines the body for 'Thread Reply', which can then be used by various notification jobs/services. 
///
/// Key relationships: No direct foreign keys. Templates are referenced by notification delivery engines and preference settings elsewhere in the system. 
/// Special behaviors: Supports audit trails, mutable content with unique code per template, version history if needed.
///
/// @namespace Notifications
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_notification_templates {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each notification template.
  id String @id @db.Uuid

  /// Template Code - Implements template identification and enforcement. Business meaning: Unique short string used to reference this template (e.g., 'reply_notification'). Separates template logic from notification event logic, enables auditability by code, and prevents duplicates. Example: Used by notification jobs to fetch rendered content for email or in-app use. Constraint: Must be unique across all templates.
  code String

  /// Template Name - Implements template user-friendly reference. Business meaning: Human-readable title for each notification template. Ensures normalization by preventing use of business data in multiple places. Example: Shown to admins when configuring notification settings. Constraint: Must not be null.
  name String

  /// Template Description - Provides extended context for admins. Business meaning: A sentence or two that describes the intent or use-case of the template. Ensures normalization by allowing proper documentation in one place. Example: 'Sent when a user receives a reply to their thread.' Nullable for brevity in simple templates.
  description String?

  /// Template Subject - Implements message subject customization. Business meaning: Used for email or notification headers. Ensures clear communication and organization. Example: '[DiscussionBoard] New reply to your thread'. Constraint: Not nullable for communication clarity.
  subject String

  /// Template Body - The main message content, possibly with placeholders. Ensures normalization by centralizing source message text for all notification jobs/services. Example: 'Hello {{username}}, your post received a reply...'. May use parameter placeholders for personalization. Not nullable to ensure every template is usable.
  body String

  /// Active Status Flag - Indicates if this template is available for use. Implements enable/disable without deletion for audit trails and error prevention. Example: Deactivating a deprecated or seasonal template. Not nullable.
  is_active Boolean

  /// Creation Timestamp - Implements audit trail requirement (Business Rules: Section 6). Business meaning: When was the template created. 3NF compliance by storing as atomic value. Not nullable.
  created_at DateTime @db.Timestamptz

  /// Update Timestamp - Implements last-modified tracking. Records when the template was last edited. Normalized per audit/compliance guidance. Not nullable.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([code])
  @@index([is_active])
  @@index([created_at])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([subject(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Notification Preferences Entity - Implements user-specific notification customization per Business Requirement 6 (Notifications & Updates) and 3 (User Journey & Use Cases). 
///
/// Business explanation: Stores each member’s notification channel preferences for different template types (e.g., email, SMS, in-app). Supports compliance with data privacy laws by honoring user opt-in/out settings. Enforces normalization by decoupling per-user/channel rules from system triggers and message templates. Example: User sets 'email' notifications only for mentions, but not for thread replies. 
///
/// Key relationships: Links to discussionboard_members via foreign key. References notification template codes for channel granularity. 
/// Special behaviors: Each (member_id, code) pair must be unique. Allows for per-template and per-channel enable/disable granularity. Audit fields included for compliance.
///
/// @namespace Notifications
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_notification_preferences {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each notification preference row.
  id String @id @db.Uuid

  /// Belonged member’s {@link discussionboard_members.id}. Links notification preference to user account.
  discussionboard_member_id String @db.Uuid

  /// Notification Template Code - Implements per-template preference setting. Business meaning: Which notification type this preference applies to. Ensures normalization by not embedding template details; only links by code. Not nullable.
  code String

  /// Enable for Email - Indicates if the member wants email notifications for this code. Implements granular opt-in control (required for privacy regulations). Not nullable.
  email_enabled Boolean

  /// Enable for In-App - Indicates if in-app/bell notifications are enabled. Business meaning: Supports per-channel enable/disable. Not nullable.
  inapp_enabled Boolean

  /// Enable for Browser Push - Channel preference for browser push notifications. Ensures each user can control channel specificity. Not nullable.
  browser_enabled Boolean

  /// Creation Timestamp - For audit and compliance tracking. Not nullable.
  created_at DateTime @db.Timestamptz

  /// Update Timestamp - Last modified tracking. Ensures temporal auditability. Not nullable.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_discussionboard_notification_preferences_member discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)

  @@unique([discussionboard_member_id, code])
  @@index([discussionboard_member_id])
  @@index([code])
  @@index([email_enabled])
}

schemas.schema-10-privacy.prisma:
/// Privacy Policy – This model implements the explicit business requirement for transparent privacy and data protection policies outlined in the platform requirements. Each record stores a distinct, time-versioned policy for audit, legal compliance, and user access. Policies are never overwritten, ensuring a full historical audit trail and 3NF normalization. Example: When a new version of the privacy policy is adopted, a new record is inserted; users can access the version effective when they joined.
///
/// @namespace Privacy
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_privacy_policies {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique policy version identifier. Ensures entity singularity for audit/history.
  id String @id @db.Uuid

  /// Policy Version – Structured textual identifier (e.g., 'v2024.06') referenced in logs or member consent records. Uniquely identifies each record. Normalized, atomic.
  version String

  /// Policy Effective Date – When this version of the policy became active. Used for temporal access control and audits. Fully atomic (3NF).
  effective_date DateTime @db.Timestamptz

  /// Policy Title – Short heading for the policy. Enables user recognition and log referencing. Allows multi-language by separate records.
  title String

  /// Policy Content – The authoritative text for legal compliance and user review. Only non-calculated, non-redundant full text allowed.
  content String

  /// Created At – Timestamp when this policy version was created in the system. For audit/compliance.
  created_at DateTime @db.Timestamptz

  /// Updated At – Last updated timestamp. For change tracking, audit.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([version])
  @@index([effective_date])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Data Erasure Request – Implements the business need for user-initiated account/data deletion and administrator compliance tracking (GDPR/CCPA/etc.). Records each member erasure request, its status, processing timestamps, and rationale. All data is fully normalized (3NF); status/history are atomic, with no pre-calculated aggregates. Key for regulatory audit and platform trust. Example: Members submit erasure requests independently, admins can query and process them, with all changes independently logged. Links to discussionboard_members in Actors by foreign key for referential integrity.
///
/// @namespace Privacy
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_data_erasure_requests {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each erasure request. Enables audit and traceability.
  id String @id @db.Uuid

  /// Belonged member's {@link discussionboard_members.id}. FK to Actors component for requestor identity. Fully normalized, ensures direct link to user identity for audit.
  discussionboard_member_id String @db.Uuid

  /// Request Status: Current disposition of the erasure request (ex: 'pending', 'approved', 'denied', 'completed', etc.). Only the instantaneous status (not calculated) is stored; maintains atomicity for 3NF. Admins or the process flow must update the value as the request advances.
  status String

  /// Requested At – When the erasure request was created (for auditing, compliance, and metrics). Atomic.
  requested_at DateTime @db.Timestamptz

  /// Reviewed At – When an admin/moderator reviewed the request. Nullable; if never reviewed, stays null. Keeps precise process timestamps normalized.
  reviewed_at DateTime? @db.Timestamptz

  /// Completed At – When erasure or rejection was completed. Nullable, only present on completion. Strictly atomic for audit and query needs.
  completed_at DateTime? @db.Timestamptz

  /// Admin Remark – Optional explanatory note for audit/logging (e.g., why approved/denied). Nullable (optional field). Ensures 3NF by separating from status/timestamps.
  admin_remark String?

  //----
  // RELATIONS
  //----
  fk_data_erasure_request_member discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)

  @@index([status])
  @@index([discussionboard_member_id])
}

