/**
 * E2E test for updating a discussion board thread's title and body.
 *
 * This function tests:
 * 1. Successful update of a thread by its author with valid new title and body.
 * 2. Attempted updates with invalid data (empty title, empty body) and expects validation errors.
 * 3. Attempted update of a thread that has been soft-deleted. The system should reject update with an error.
 *
 * Steps:
 * 1. Create a thread as the base resource for all update tests.
 * 2. Update the thread with valid new title and body, and check that the result is correct.
 * 3. Attempt to update with invalid data (empty title and empty body) and verify error is thrown.
 * 4. Soft-delete the thread using erase API.
 * 5. Attempt to update soft-deleted thread and verify error is thrown.
 */
export async function test_api_discussionboard_test_update_thread_title_and_body_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Create a new thread for the update scenarios
  const boardId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const authorId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const originalTitle: string = RandomGenerator.paragraph()(1);
  const originalBody: string = RandomGenerator.content()()();

  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: boardId,
      author_member_id: authorId,
      title: originalTitle,
      body: originalBody,
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(thread);

  // 2. Update the thread's title and body with valid new values
  const newTitle: string = RandomGenerator.paragraph()(1);
  const newBody: string = RandomGenerator.content()()();
  const updatedThread = await api.functional.discussionboard.threads.update(connection, {
    id: thread.id,
    body: {
      title: newTitle,
      body: newBody,
    } satisfies IDiscussionboardThreads.IUpdate,
  });
  typia.assert(updatedThread);
  TestValidator.equals("updated title")(updatedThread.title)(newTitle);
  TestValidator.equals("updated body")(updatedThread.body)(newBody);

  // 3. Attempt to update with invalid data: empty title
  await TestValidator.error("thread update should fail for empty title")(async () => {
    await api.functional.discussionboard.threads.update(connection, {
      id: thread.id,
      body: {
        title: "",
      } satisfies IDiscussionboardThreads.IUpdate,
    });
  });

  // 3-2. Attempt to update with invalid data: empty body
  await TestValidator.error("thread update should fail for empty body")(async () => {
    await api.functional.discussionboard.threads.update(connection, {
      id: thread.id,
      body: {
        body: "",
      } satisfies IDiscussionboardThreads.IUpdate,
    });
  });

  // 4. Soft-delete the thread
  const eraseResult = await api.functional.discussionboard.threads.erase(connection, {
    id: thread.id,
  });
  typia.assert(eraseResult);
  TestValidator.equals("thread soft-deleted")(eraseResult.success)(true);

  // 5. Try updating a soft-deleted thread: should fail
  await TestValidator.error("cannot update a soft-deleted thread")(async () => {
    await api.functional.discussionboard.threads.update(connection, {
      id: thread.id,
      body: {
        title: RandomGenerator.paragraph()(1),
      } satisfies IDiscussionboardThreads.IUpdate,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
