 * Business context:
 * Moderators and admins need to update warning records for audit or appeal corrections, but may only modify allowed fields. The system must enforce this, prohibiting any extra/non-schema properties.
 *
 * Steps:
 * 1. Issue a warning via POST /discussionboard/warnings.
 * 2. Update the warning via PUT /discussionboard/warnings/{id}, modifying the reason and warned_at fields.
 * 3. Validate that the update was successful, changes are reflected, and the fields not included are unchanged.
 * 4. (Edge) Attempt to set null values for nullable fields and verify system behavior.
 */
export async function test_api_discussionboard_test_update_warning_fields_successfully(
  connection: api.IConnection,
) {
  // 1. Issue a warning
  const createInput: IDiscussionboardWarning.ICreate = {
    warned_member_id: typia.random<string & tags.Format<"uuid">>(),
    acting_moderator_id: typia.random<string & tags.Format<"uuid">>(),
    report_id: typia.random<string & tags.Format<"uuid">>(),
