import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { Idiscussionboard_boards } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_boards";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IDiscussionboardEngagementMetric } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardEngagementMetric";
import type { IPageIDiscussionboardEngagementMetric } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardEngagementMetric";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing engagement metrics using various filters and pagination.
 *
 * This test simulates diverse activity patterns among multiple members across multiple boards on different dates, ensuring engagement metrics endpoint correctly filters and paginates results.
 *
 * Step-by-step test process:
 * 1. Create three members (with distinct emails, usernames, roles).
 * 2. Create two boards (with different category and section UUIDs, names, codes).
 * 3. Simulate posts in both boards by different members on at least two different dates. Spread usage so some members post to multiple boards, and on different days. Use typia.random for unique thread and post IDs, set created_at/updated_at to different date values.
 * 4. (Optional) Simulate variations in post content and metadata to test metric counting.
 * 5. Query the engagement metrics API using combinations of discussionboard_member_id, discussionboard_board_id, and time windows for date filtering.
 * 6. Assert that returned metric rows match the applied filters. For example: filtering by a member only returns their rows; filtering by board excludes activity in other boards, and date filters yield only the expected time bucket(s).
 * 7. Check that pagination metadata is populated and reflects actual row counts (current, limit, records, pages).
 */
export async function test_api_discussionboard_test_list_engagement_metrics_with_various_filters(
  connection: api.IConnection,
) {
  // 1. Create multiple members
  const members = await Promise.all(ArrayUtil.repeat(3)(async () => {
    const email = typia.random<string & tags.Format<"email">>();
    const member = await api.functional.discussionboard.members.create(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        email,
        hashed_password: RandomGenerator.alphaNumeric(16),
        role: RandomGenerator.pick(["member", "moderator", "admin"]),
        is_active: true,
      }
    });
    typia.assert(member);
    return member;
  }));

  // 2. Create multiple boards (categories and sections are random UUIDs for isolation)
  const boards = await Promise.all(ArrayUtil.repeat(2)(async () => {
    const board = await api.functional.discussionboard.boards.create(connection, {
      body: {
        discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
        name: RandomGenerator.paragraph()(1),
        code: RandomGenerator.alphaNumeric(6),
        description: RandomGenerator.paragraph()(1),
        is_active: true,
        is_visible: true,
      }
    });
    typia.assert(board);
    return board;
  }));

  // 3. Simulate posts in both boards, by different members, on two different days
  const day1 = new Date();
  const day2 = new Date(Date.now() - 86400000); // 1 day ago
  const threadIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];
  const posts: IDiscussionboardPost[] = [];
  for (const member of members) {
    for (const [i, board] of boards.entries()) {
      // Every member posts in both boards, on both days
      for (const date of [day1, day2]) {
        const post = await api.functional.discussionboard.posts.create(connection, {
          body: {
            discussionboard_thread_id: threadIds[i],
            discussionboard_member_id: member.id,
            discussionboard_board_id: board.id,
            title: RandomGenerator.paragraph()(1),
            body: RandomGenerator.content()()(),
            is_deleted: false,
            created_at: date.toISOString(),
            updated_at: date.toISOString(),
          }
        });
        typia.assert(post);
        posts.push(post);
      }
    }
  }

  // 4. Query engagement metrics filtered by member
  for (const member of members) {
    const resp = await api.functional.discussionboard.engagementMetrics.index(connection, {
      body: {
        discussionboard_member_id: member.id,
      }
    });
    typia.assert(resp);
    for (const row of resp.data) {
      if (row.discussionboard_member_id !== null)
        TestValidator.equals("member_id matches filter")(row.discussionboard_member_id)(member.id);
    }
    TestValidator.predicate("pagination present")(!!resp.pagination);
    TestValidator.predicate("pagination count matches records")(resp.pagination.records >= resp.data.length);
  }

  // 5. Query engagement metrics filtered by board
  for (const board of boards) {
    const resp = await api.functional.discussionboard.engagementMetrics.index(connection, {
      body: {
        discussionboard_board_id: board.id,
      }
    });
    typia.assert(resp);
    for (const row of resp.data) {
      if (row.discussionboard_board_id !== null)
        TestValidator.equals("board_id matches filter")(row.discussionboard_board_id)(board.id);
    }
    TestValidator.predicate("pagination present")(!!resp.pagination);
    TestValidator.predicate("pagination count matches records")(resp.pagination.records >= resp.data.length);
  }

  // 6. Query with engagement_date window  (only day1, only day2)
  for (const date of [day1, day2]) {
    const iso = date.toISOString();
    const resp = await api.functional.discussionboard.engagementMetrics.index(connection, {
      body: {
        engagement_date_from: iso,
        engagement_date_to: iso,
      }
    });
    typia.assert(resp);
    for (const row of resp.data) {
      TestValidator.equals("engagement_date matches filter")(row.engagement_date.substring(0,10))(iso.substring(0,10));
    }
    TestValidator.predicate("pagination present")(!!resp.pagination);
    TestValidator.predicate("pagination count matches records")(resp.pagination.records >= resp.data.length);
  }
  // 7. Query with all filters combined (member+board+date)
  const member = RandomGenerator.pick(members);
  const board = RandomGenerator.pick(boards);
  const iso = day1.toISOString();
  const combined = await api.functional.discussionboard.engagementMetrics.index(connection, {
    body: {
      discussionboard_member_id: member.id,
      discussionboard_board_id: board.id,
      engagement_date_from: iso,
      engagement_date_to: iso,
    }
  });
  typia.assert(combined);
  for (const row of combined.data) {
    if(row.discussionboard_member_id!==null)
      TestValidator.equals("member_id matches filter")(row.discussionboard_member_id)(member.id);
    if(row.discussionboard_board_id!==null)
      TestValidator.equals("board_id matches filter")(row.discussionboard_board_id)(board.id);
    TestValidator.equals("engagement_date matches filter")(row.engagement_date.substring(0,10))(iso.substring(0,10));
  }
  TestValidator.predicate("pagination present")(!!combined.pagination);
  TestValidator.predicate("pagination count matches records")(combined.pagination.records >= combined.data.length);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardChannel";
import type { IDiscussionboardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSection";
import type { IPageIDiscussionboardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardSection";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates retrieval of discussion board sections filtered by channel and active status.
 *
 * This test ensures that the /discussionboard/sections PATCH endpoint properly supports complex filtering and pagination based on channel and section 'active' status. It asserts correctness for both success and empty results, as well as for pagination controls.
 *
 * Step-by-step process:
 * 1. Create one parent channel (required for FK on section).
 * 2. Create several section entities under this channel, varying properties including 'active'.
 * 3. Retrieve all sections for this channel to verify full insertion.
 * 4. Retrieve only active sections (active=true) for the channel, confirm correct filtering.
 * 5. Retrieve only inactive sections (active=false) for the channel, confirm correct filtering.
 * 6. Retrieve sections with pagination (limit=2), check returned data and meta.
 * 7. Attempt retrieval from a non-existent channel, expect empty result.
 * 8. Attempt filter combination that gives no results (e.g., active=true on a channel with only inactive sections).
 */
export async function test_api_discussionboard_sections_test_list_sections_with_filter_by_channel_and_active_status(
  connection: api.IConnection,
) {
  // 1. Create a channel (parent)
  const channel = await api.functional.discussionboard.channels.create(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(6),
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.paragraph()(1),
      position: typia.random<number & tags.Type<"int32">>(),
      active: true,
    },
  });
  typia.assert(channel);

  // 2. Create sections under the channel (some active, some inactive)
  const sections: IDiscussionboardSection[] = [];
  for (const [i, active] of [true, false, true].entries()) {
    const section = await api.functional.discussionboard.sections.create(connection, {
      body: {
        discussionboard_channel_id: channel.id,
        code: RandomGenerator.alphaNumeric(5) + i,
        name: RandomGenerator.paragraph()(1) + i,
        description: RandomGenerator.paragraph()(1),
        position: i,
        active,
      },
    });
    typia.assert(section);
    sections.push(section);
  }

  // 3. Retrieve all sections for this channel
  const pageAll = await api.functional.discussionboard.sections.index(connection, {
    body: {
      discussionboard_channel_id: channel.id,
    },
  });
  typia.assert(pageAll);
  TestValidator.equals("all section count")(pageAll.data.length)(sections.length);
  for (const sec of sections) {
    TestValidator.predicate(`section id present: ${sec.id}`)(pageAll.data.some((s) => s.id === sec.id));
  }

  // 4. Retrieve only active sections
  const pageActive = await api.functional.discussionboard.sections.index(connection, {
    body: {
      discussionboard_channel_id: channel.id,
      active: true,
    },
  });
  typia.assert(pageActive);
  const actives = sections.filter((s) => s.active);
  TestValidator.equals("active count")(pageActive.data.length)(actives.length);
  for (const sec of actives) {
    TestValidator.predicate(`active section present: ${sec.id}`)(pageActive.data.some((s) => s.id === sec.id));
    TestValidator.equals("section is active")(sec.active)(true);
  }

  // 5. Retrieve only inactive sections
  const pageInactive = await api.functional.discussionboard.sections.index(connection, {
    body: {
      discussionboard_channel_id: channel.id,
      active: false,
    },
  });
  typia.assert(pageInactive);
  const inactives = sections.filter((s) => !s.active);
  TestValidator.equals("inactive count")(pageInactive.data.length)(inactives.length);
  for (const sec of inactives) {
    TestValidator.predicate(`inactive section present: ${sec.id}`)(pageInactive.data.some((s) => s.id === sec.id));
    TestValidator.equals("section is inactive")(sec.active)(false);
  }

  // 6. Pagination test (limit=2)
  const pageLimited = await api.functional.discussionboard.sections.index(connection, {
    body: {
      discussionboard_channel_id: channel.id,
      limit: 2,
    },
  });
  typia.assert(pageLimited);
  TestValidator.equals("paged limit")(pageLimited.pagination.limit)(2);
  TestValidator.equals("page data length")(pageLimited.data.length)(Math.min(2, sections.length));

  // 7. Filter with a non-existent channel ID (should yield empty)
  const pageEmptyChannel = await api.functional.discussionboard.sections.index(connection, {
    body: {
      discussionboard_channel_id: typia.random<string & tags.Format<"uuid">>(),
    },
  });
  typia.assert(pageEmptyChannel);
  TestValidator.equals("empty channel result")(pageEmptyChannel.data.length)(0);

  // 8. Filter by active=true on a channel where all are inactive
  const channel2 = await api.functional.discussionboard.channels.create(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(7),
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.paragraph()(1),
      position: typia.random<number & tags.Type<"int32">>(),
      active: true,
    },
  });
  typia.assert(channel2);
  const sectionInactive = await api.functional.discussionboard.sections.create(connection, {
    body: {
      discussionboard_channel_id: channel2.id,
      code: RandomGenerator.alphaNumeric(7),
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.paragraph()(1),
      position: 0,
      active: false,
    },
  });
  typia.assert(sectionInactive);
  const pageNoMatch = await api.functional.discussionboard.sections.index(connection, {
    body: {
      discussionboard_channel_id: channel2.id,
      active: true,
    },
  });
  typia.assert(pageNoMatch);
  TestValidator.equals("no match returned")(pageNoMatch.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
