import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerator";
import type { IPageIDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test advanced filtering and search functionality for moderator assignments on the discussion board.
 *
 * This test covers:
 * - Creation of sample members (to serve as potential moderators and assigning admins)
 * - Assignment of various moderator records using different assigned_by_admin_id, assigned_at, expires_at, and revoked_at values
 * - Advanced search/filter operations via the PATCH /discussionboard/moderators endpoint by filtering on member_id, assigned_by_admin_id, assigned_at, and revoked_at combinations
 * - Validation that filtered results strictly match query conditions, pagination works as expected, and that no extra/query fields outside schema are accepted
 * - Error validation for illegal filters (e.g., unsupported fields)
 *
 * Test steps:
 * 1. Create three discussion board members: two as moderator candidates, one as admin (using appropriate role field)
 * 2. Assign moderator roles to both candidates but with different assigned_by_admin_id and timing/expire/revoke metadata
 * 3. Search moderator assignments filtered by member_id, by assigned_by_admin_id, by assigned_at value, and by revoked_at (null and non-null)
 * 4. For each search, verify only correct assignments are returned and pagination info is correct
 * 5. Attempt a search using an unsupported query field and expect a validation error
 */
export async function test_api_discussionboard_test_search_moderator_assignments_with_various_filters(
  connection: api.IConnection,
) {
  // Step 1: Create an admin and two member accounts
  const admin = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(20),
      role: "admin",
      is_active: true,
    },
  });
  typia.assert(admin);
  const mod1 = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(20),
      role: "moderator",
      is_active: true,
    },
  });
  typia.assert(mod1);
  const mod2 = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(20),
      role: "moderator",
      is_active: true,
    },
  });
  typia.assert(mod2);

  // Step 2: Assign moderator roles with varying assignment and revoke metadata
  const now = new Date();
  const yesterday = new Date(now.getTime() - 24 * 60 * 60 * 1000);
  const tomorrow = new Date(now.getTime() + 24 * 60 * 60 * 1000);

  // mod1: assigned by admin now, active
  const assignment1 = await api.functional.discussionboard.moderators.create(connection, {
    body: {
      member_id: mod1.id,
      assigned_by_admin_id: admin.id,
      assigned_at: now.toISOString(),
      expires_at: null,
      revoked_at: null,
    },
  });
  typia.assert(assignment1);
  // mod2: assigned by admin yesterday, expired and revoked today
  const assignment2 = await api.functional.discussionboard.moderators.create(connection, {
    body: {
      member_id: mod2.id,
      assigned_by_admin_id: admin.id,
      assigned_at: yesterday.toISOString(),
      expires_at: now.toISOString(),
      revoked_at: now.toISOString(),
    },
  });
  typia.assert(assignment2);

  // Step 3: Filter by member_id (mod1) and verify only assignment1 is returned
  let result = await api.functional.discussionboard.moderators.index(connection, {
    body: { member_id: mod1.id },
  });
  typia.assert(result);
  TestValidator.predicate("only assignment1 returned")(result.data.length === 1 && result.data[0].id === assignment1.id);

  // Step 4: Filter by revoked_at=null (only active moderators)
  result = await api.functional.discussionboard.moderators.index(connection, {
    body: { revoked_at: null },
  });
  typia.assert(result);
  TestValidator.predicate("only assignment1 is active")(result.data.every(a => a.revoked_at === null));

  // Step 5: Filter by revoked_at=now (should only get assignment2)
  result = await api.functional.discussionboard.moderators.index(connection, {
    body: { revoked_at: now.toISOString() },
  });
  typia.assert(result);
  TestValidator.predicate("only assignment2 matches revoked_at")(result.data.some(a => a.id === assignment2.id));

  // Step 6: Paging test: set up more assignments, page results
  const moreMods: IDiscussionboardMember[] = [];
  for (let i = 0; i < 3; ++i) {
    moreMods.push(await api.functional.discussionboard.members.create(connection, {
      body: {
        username: RandomGenerator.alphabets(8),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphaNumeric(20),
        role: "moderator",
        is_active: true,
      },
    }));
    await api.functional.discussionboard.moderators.create(connection, {
      body: {
        member_id: moreMods[i].id,
        assigned_by_admin_id: admin.id,
        assigned_at: tomorrow.toISOString(),
        expires_at: null,
        revoked_at: null,
      },
    });
  }

  result = await api.functional.discussionboard.moderators.index(connection, {
    body: {}, // no filter: should return all assignments
  });
  typia.assert(result);
  TestValidator.predicate("paging works")(result.data.length >= 5); // total created assignments
  typia.assert(result.pagination);

  // Step 7: Error on unsupported filter/query
  await TestValidator.error("unsupported query field error")(async () => {
    await api.functional.discussionboard.moderators.index(connection, {
      body: { not_a_field: "illegal" } as any,
    });
  });
}

