import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerator";

/**
 * Test updating a moderator assignment record by ID.
 *
 * This test covers both valid update flows and expected failure/error scenarios:
 *
 * - Setup: Create admin and regular member accounts. Have admin assign moderator to a member.
 * - Success scenario: Admin updates moderator assignment -
 *   1. Extends expiry (`expires_at`) for a moderator assignment and checks updated value is reflected
 *   2. Revokes moderator assignment by setting `revoked_at` and checks updated state
 * - Error scenarios:
 *   3. Attempt to update with a non-existent assignment id (should error)
 *   4. Attempt with insufficient permissions (e.g. try as member, should error)
 *   5. Attempt to set invalid date (bad format) in update, should error
 *
 * Steps:
 * 1. Create admin and member users
 * 2. Create moderator assignment as admin
 * 3. Update assignment expires_at as admin (should succeed)
 * 4. Update assignment revoked_at as admin (should succeed)
 * 5. Attempt update with random invalid id (should fail)
 * 6. Attempt update as member (expect permission error)
 * 7. Attempt update with badly formatted date (expect error)
 */
export async function test_api_discussionboard_moderators_test_update_moderator_assignment_valid_and_invalid_cases(
  connection: api.IConnection,
) {
  // 1. Create admin user
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: adminEmail,
      hashed_password: RandomGenerator.alphaNumeric(18),
      role: "admin",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(admin);

  // 2. Create regular member (to be assigned moderator)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: memberEmail,
      hashed_password: RandomGenerator.alphaNumeric(18),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 3. Assign member as moderator (as admin)
  const assignTime = new Date().toISOString();
  const moderatorAssignment: IDiscussionboardModerator = await api.functional.discussionboard.moderators.create(connection, {
    body: {
      member_id: member.id,
      assigned_by_admin_id: admin.id,
      assigned_at: assignTime,
      expires_at: null,
      revoked_at: null,
    } satisfies IDiscussionboardModerator.ICreate,
  });
  typia.assert(moderatorAssignment);

  // 4. Update expires_at (extend)
  const extendedExpiry = new Date(Date.now() + 15 * 24 * 60 * 60 * 1000).toISOString();
  const updatedExpiry: IDiscussionboardModerator = await api.functional.discussionboard.moderators.update(connection, {
    id: moderatorAssignment.id,
    body: {
      expires_at: extendedExpiry,
    } satisfies IDiscussionboardModerator.IUpdate,
  });
  typia.assert(updatedExpiry);
  TestValidator.equals("expires extended")(updatedExpiry.expires_at)(extendedExpiry);

  // 5. Update revoked_at (revoke privileges)
  const revokeTime = new Date().toISOString();
  const updatedRevoked: IDiscussionboardModerator = await api.functional.discussionboard.moderators.update(connection, {
    id: moderatorAssignment.id,
    body: {
      revoked_at: revokeTime,
    } satisfies IDiscussionboardModerator.IUpdate,
  });
  typia.assert(updatedRevoked);
  TestValidator.equals("revoked_at set")(updatedRevoked.revoked_at)(revokeTime);

  // 6. Update with non-existent assignment ID (should error)
  await TestValidator.error("nonexistent id should error")(async () => {
    await api.functional.discussionboard.moderators.update(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        expires_at: new Date(Date.now() + 10000).toISOString(),
      } satisfies IDiscussionboardModerator.IUpdate,
    });
  });

  // 7. Attempt update as member (not admin, insufficient permission)
  // Switch to member context
  // In absence of login, simulate as best possible
  // (If token/role context needed, this step may not be possible. If API keys override, skip)
  // Here we just call with a new member (simulate failure)
  const unauthorizedMemberEmail = typia.random<string & tags.Format<"email">>();
  const unauthorizedMember: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: unauthorizedMemberEmail,
      hashed_password: RandomGenerator.alphaNumeric(18),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(unauthorizedMember);
  // Try as this member (note: without authentication switching, just document intent)
  await TestValidator.error("insufficient permission")(async () => {
    await api.functional.discussionboard.moderators.update(connection, {
      id: moderatorAssignment.id,
      body: {
        expires_at: new Date(Date.now() + 10000).toISOString(),
      } satisfies IDiscussionboardModerator.IUpdate,
    });
  });

  // 8. Attempt invalid date format
  await TestValidator.error("invalid date format")(async () => {
    await api.functional.discussionboard.moderators.update(connection, {
      id: moderatorAssignment.id,
      body: {
        expires_at: "not-a-date",
      } satisfies IDiscussionboardModerator.IUpdate,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerator";

/**
 * Test soft revocation of moderator assignment and error cases.
 *
 * This test verifies the revocation of a moderator role assignment via the erase endpoint. It covers proper setting of revoked_at, idempotency behavior, error handling for non-existent assignments, and ensures that related member accounts are unaffected.
 *
 * Steps:
 * 1. Create an admin member and a regular member.
 * 2. Assign the moderator role to the member as the admin.
 * 3. Revoke the moderator assignment (should set revoked_at and leave record for audit).
 * 4. Confirm revoked_at is set and assignment data is correct.
 * 5. Call revoke on same assignment again to test idempotency—should return same record and not error.
 * 6. Attempt to revoke a non-existent assignment—should throw error.
 * 7. Note: There is no direct API to read a member, so cannot further check member state beyond creation output. If/when member read/check endpoint exists, it should be validated that the member's profile (outside of role assignment) is unchanged by moderator revoke operation.
 */
export async function test_api_discussionboard_test_soft_revoke_moderator_assignment_and_error_cases(
  connection: api.IConnection,
) {
  // 1. Create admin and member accounts
  const adminInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    role: "admin",
    is_active: true,
  };
  const admin = await api.functional.discussionboard.members.create(connection, {
    body: adminInput,
  });
  typia.assert(admin);

  const memberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    role: "member",
    is_active: true,
  };
  const member = await api.functional.discussionboard.members.create(connection, {
    body: memberInput,
  });
  typia.assert(member);

  // 2. Assign moderator role
  const assignedAt = new Date().toISOString();
  const modAssignInput: IDiscussionboardModerator.ICreate = {
    member_id: member.id,
    assigned_by_admin_id: admin.id,
    assigned_at: assignedAt,
    expires_at: null,
    revoked_at: null,
  };
  const moderator = await api.functional.discussionboard.moderators.create(connection, {
    body: modAssignInput,
  });
  typia.assert(moderator);

  // 3. Revoke moderator assignment
  const revoked = await api.functional.discussionboard.moderators.erase(connection, { id: moderator.id });
  typia.assert(revoked);

  // 4. Validate that revoked_at is set (not null), data is correct, audit record remains
  TestValidator.predicate("revoked_at is set")(!!revoked.revoked_at && typeof revoked.revoked_at === "string");
  TestValidator.equals("member_id remains match")(revoked.member_id)(member.id);
  TestValidator.equals("assigned_by_admin_id remains match")(revoked.assigned_by_admin_id)(admin.id);
  TestValidator.equals("assigned_at remains match")(revoked.assigned_at)(assignedAt);

  // 5. Attempt to revoke again (idempotency: should not error, returns same revoked record)
  const revokedAgain = await api.functional.discussionboard.moderators.erase(connection, { id: moderator.id });
  typia.assert(revokedAgain);
  TestValidator.equals("revoked_at field stable")(revokedAgain.revoked_at)(revoked.revoked_at);

  // 6. Try to revoke non-existent moderator assignment (should error)
  await TestValidator.error("revoke non-existent assignment fails")(() =>
    api.functional.discussionboard.moderators.erase(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    }),
  );

  // 7. Member profile remains unaffected: No direct member read endpoint is available. If/when one exists, should verify member info unchanged except for mod assignments.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAdmin";

/**
 * Test admin assignment creation in the discussion board system, including success, unique constraint, and invalid data paths.
 *
 * This test covers:
 * 1. Register two valid members. One will be assigned admin privileges; the other acts as the assigning admin.
 * 2. Assign admin status to the target member, using the other admin's discussionboard_admins.id for `assigned_by_admin_id`. Verify all fields in the returned discussionboard_admin entity.
 * 3. Attempt to create a duplicate admin assignment for the same member and assert a unique constraint (1:1 mapping) error is thrown.
 * 4. Test edge cases: (a) try to assign admin for a non-existent member_id; (b) omit required fields (e.g., missing member_id), asserting validation/foreign key errors on all invalid requests.
 * 5. Validate that the member records themselves (role, is_active, etc.) remain unchanged by admin assignment—only the admin-assignment table is affected.
 */
export async function test_api_discussionboard_test_create_admin_assignment_with_unique_constraint_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Register two valid members
  const member1_input = {
    username: RandomGenerator.alphabets(12),
    email: `${RandomGenerator.alphabets(8)}1@sample.com`,
    hashed_password: RandomGenerator.alphabets(24),
    role: "member",
    is_active: true,
  } satisfies IDiscussionboardMember.ICreate;
  const member2_input = {
    username: RandomGenerator.alphabets(12),
    email: `${RandomGenerator.alphabets(8)}2@sample.com`,
    hashed_password: RandomGenerator.alphabets(24),
    role: "admin",
    is_active: true,
  } satisfies IDiscussionboardMember.ICreate;

  const member1 = await api.functional.discussionboard.members.create(connection, { body: member1_input });
  typia.assert(member1);
  TestValidator.equals("member1.username")(member1.username)(member1_input.username);
  TestValidator.equals("member1.email")(member1.email)(member1_input.email);

  const member2 = await api.functional.discussionboard.members.create(connection, { body: member2_input });
  typia.assert(member2);
  TestValidator.equals("member2.username")(member2.username)(member2_input.username);
  TestValidator.equals("member2.email")(member2.email)(member2_input.email);

  // 2. Assign admin status to member1, using member2 as the assigning admin
  // First, bootstrap: Allow self-appointment for member2's initial admin assignment
  const admin2_input = {
    member_id: member2.id,
    assigned_by_admin_id: member2.id, // Allow bootstrap: self-assignment
    assigned_at: new Date().toISOString(),
    revoked_at: null,
  } satisfies IDiscussionboardAdmin.ICreate;
  const admin2 = await api.functional.discussionboard.admins.create(connection, { body: admin2_input });
  typia.assert(admin2);
  TestValidator.equals("admin2.member_id")(admin2.member_id)(member2.id);
  TestValidator.equals("admin2.assigned_by_admin_id")(admin2.assigned_by_admin_id)(member2.id);
  TestValidator.equals("admin2.revoked_at")(admin2.revoked_at)(null);

  // Now, assign member1 as admin, with member2 as assigner
  const admin1_input = {
    member_id: member1.id,
    assigned_by_admin_id: admin2.id, // Use the created admin id
    assigned_at: new Date().toISOString(),
    revoked_at: null,
  } satisfies IDiscussionboardAdmin.ICreate;
  const admin1 = await api.functional.discussionboard.admins.create(connection, { body: admin1_input });
  typia.assert(admin1);
  TestValidator.equals("admin1.member_id")(admin1.member_id)(member1.id);
  TestValidator.equals("admin1.assigned_by_admin_id")(admin1.assigned_by_admin_id)(admin2.id);
  TestValidator.equals("admin1.revoked_at")(admin1.revoked_at)(null);

  // 3. Attempt to create a duplicate admin assignment for member1 (should fail unique constraint)
  TestValidator.error("duplicate admin assignment fails")(async () => {
    await api.functional.discussionboard.admins.create(connection, { body: admin1_input });
  });

  // 4a. Attempt to assign admin to a non-existent member
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  const bad_admin_input = {
    member_id: nonExistentId,
    assigned_by_admin_id: admin2.id,
    assigned_at: new Date().toISOString(),
    revoked_at: null,
  } satisfies IDiscussionboardAdmin.ICreate;
  TestValidator.error("assign admin to non-existent member fails")(async () => {
    await api.functional.discussionboard.admins.create(connection, { body: bad_admin_input });
  });

  // 4b. Omit required fields (missing member_id)
  const incomplete_admin_input = {
    // member_id missing
    assigned_by_admin_id: admin2.id,
    assigned_at: new Date().toISOString(),
    revoked_at: null,
  } as any; // purposely invalid to simulate missing required field
  TestValidator.error("missing required member_id fails")(async () => {
    await api.functional.discussionboard.admins.create(connection, { body: incomplete_admin_input });
  });

  // 5. Ensure member records are unchanged after admin assignment
  const member1_after = await api.functional.discussionboard.members.create(connection, { body: { ...member1_input, username: member1.username+"_new", email: `${RandomGenerator.alphabets(7)}_new@sample.com` } });
  typia.assert(member1_after);

  TestValidator.equals("original member role unchanged")(member1.role)(member1_input.role);
  TestValidator.equals("original member is_active unchanged")(member1.is_active)(member1_input.is_active);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { Idiscussionboard_boards } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_boards";
import type { IDiscussionboardBoardSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoardSetting";
import type { IPageIDiscussionboardBoardSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardBoardSetting";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing and filtering of board settings with various filters and pagination.
 *
 * This e2e test simulates an admin performing board configuration management in a forum system. It follows a realistic, stepwise admin scenario:
 * 1. Create several discussion boards with distinct category/section ids, names, and codes.
 * 2. For each board, create a unique board settings record with varied settings for is_locked, require_approval_for_posting, allow_anonymous_viewing, allow_file_uploads, and max_posts_per_hour.
 * 3. List board settings filtered by a specific board id and verify only that board's setting is returned.
 * 4. List board settings filtered by is_locked=true and verify all returned settings have is_locked=true.
 * 5. List board settings filtered by allow_anonymous_viewing=false and verify all returned settings have allow_anonymous_viewing=false.
 * 6. List board settings with pagination parameters (limit=2, page=1/2) and verify pagination correctness and paging behavior.
 *
 * Each step asserts that filtering and pagination behave as expected. All API responses are type-checked with typia.assert, and business logic is verified with TestValidator.
 */
export async function test_api_discussionboard_test_list_board_settings_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create several boards
  const categoryIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>()
  ];
  const sectionIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>()
  ];
  const boards = await Promise.all(categoryIds.map((category, idx) =>
    api.functional.discussionboard.boards.create(connection, {
      body: {
        discussionboard_board_category_id: category,
        discussionboard_section_id: sectionIds[idx],
        name: `Board ${idx+1} - ${RandomGenerator.name()}`,
        code: `code_${RandomGenerator.alphaNumeric(6)}_${idx}`,
        description: RandomGenerator.paragraph()(),
        is_active: true,
        is_visible: true
      } satisfies Idiscussionboard_boards.ICreate
    })
  ));
  boards.forEach((board, idx) => {
    typia.assert(board);
    TestValidator.equals(`board id nonempty`)(typeof board.id === "string" && !!board.id)(true);
    TestValidator.equals(`board category matches`)(board.discussionboard_board_category_id)(categoryIds[idx]);
    TestValidator.equals(`board section matches`)(board.discussionboard_section_id)(sectionIds[idx]);
  });

  // 2. Create unique board settings for each board
  const settingsVariants = [
    { is_locked: false, require_approval_for_posting: false, allow_anonymous_viewing: true, allow_file_uploads: true, max_posts_per_hour: 10 },
    { is_locked: true, require_approval_for_posting: true, allow_anonymous_viewing: false, allow_file_uploads: false, max_posts_per_hour: 5 },
    { is_locked: false, require_approval_for_posting: true, allow_anonymous_viewing: false, allow_file_uploads: true, max_posts_per_hour: 3 }
  ];
  const settings = await Promise.all(boards.map((board, idx) =>
    api.functional.discussionboard.boardSettings.create(connection, {
      body: {
        discussionboard_board_id: board.id,
        ...settingsVariants[idx]
      } satisfies IDiscussionboardBoardSetting.ICreate
    })
  ));
  settings.forEach((setting, idx) => {
    typia.assert(setting);
    TestValidator.equals(`settings id nonempty`)(typeof setting.id === "string" && !!setting.id)(true);
    TestValidator.equals(`settings board id matches`)(setting.discussionboard_board_id)(boards[idx].id);
    TestValidator.equals(`is_locked matches`)(setting.is_locked)(settingsVariants[idx].is_locked);
    TestValidator.equals(`require_approval_for_posting matches`)(setting.require_approval_for_posting)(settingsVariants[idx].require_approval_for_posting);
    TestValidator.equals(`allow_anonymous_viewing matches`)(setting.allow_anonymous_viewing)(settingsVariants[idx].allow_anonymous_viewing);
    TestValidator.equals(`allow_file_uploads matches`)(setting.allow_file_uploads)(settingsVariants[idx].allow_file_uploads);
    TestValidator.equals(`max_posts_per_hour matches`)(setting.max_posts_per_hour)(settingsVariants[idx].max_posts_per_hour);
  });

  // 3. Filter: by specific board
  const targetIdx = 1;
  const filterByBoard = await api.functional.discussionboard.boardSettings.index(connection, {
    body: { discussionboard_board_id: boards[targetIdx].id } satisfies IDiscussionboardBoardSetting.IRequest
  });
  typia.assert(filterByBoard);
  TestValidator.equals("single board setting returned")(filterByBoard.data.length)(1);
  TestValidator.equals("correct setting board id")(filterByBoard.data[0].discussionboard_board_id)(boards[targetIdx].id);

  // 4. Filter: is_locked = true
  const lockedRes = await api.functional.discussionboard.boardSettings.index(connection, {
    body: { is_locked: true } satisfies IDiscussionboardBoardSetting.IRequest
  });
  typia.assert(lockedRes);
  TestValidator.predicate("all is_locked true")(
    lockedRes.data.length > 0 && lockedRes.data.every(s => s.is_locked === true)
  );

  // 5. Filter: allow_anonymous_viewing = false
  const anonRes = await api.functional.discussionboard.boardSettings.index(connection, {
    body: { allow_anonymous_viewing: false } satisfies IDiscussionboardBoardSetting.IRequest
  });
  typia.assert(anonRes);
  TestValidator.predicate("none allow anonymous viewing")(
    anonRes.data.every(s => s.allow_anonymous_viewing === false)
  );

  // 6a. Pagination: limit=2, page=1
  const page1 = await api.functional.discussionboard.boardSettings.index(connection, {
    body: { page: 1, limit: 2 } satisfies IDiscussionboardBoardSetting.IRequest
  });
  typia.assert(page1);
  TestValidator.equals("pagination page one")(page1.pagination.current)(1);
  TestValidator.equals("pagination limit two")(page1.pagination.limit)(2);
  TestValidator.predicate("max 2 records for page 1")(page1.data.length <= 2);

  // 6b. Pagination: limit=2, page=2
  const page2 = await api.functional.discussionboard.boardSettings.index(connection, {
    body: { page: 2, limit: 2 } satisfies IDiscussionboardBoardSetting.IRequest
  });
  typia.assert(page2);
  TestValidator.equals("pagination page two")(page2.pagination.current)(2);
  TestValidator.equals("pagination limit two")(page2.pagination.limit)(2);
  // Ensure no overlap in ids between page 1 and page 2
  const page1Ids = page1.data.map(d => d.id);
