/**
 * Test listing of discussion board categories with various invalid filter values.
 *
 * This test validates the robustness of the board category listing API against invalid filter criteria:
 *   1. Rejects extra/unknown fields in the filter body that are not defined in the schema.
 *   2. Rejects negative numbers for integer fields (position).
 *   3. Handles nonsensical or inappropriate string values for defined string fields.
 *   4. Ensures the API continues to function correctly with valid data after handling errors.
 *
 * Steps:
 *   a. Attempt to list with a filter that includes an unknown property (should error or be rejected by schema validation).
 *   b. Attempt to list with a negative 'position' field (should be rejected by validation).
 *   c. Attempt to list with a ridiculous string in the 'name' property (should be rejected as invalid or cause a controlled error).
 *   d. Sanity check: List categories with a fully valid filter (should succeed and return correct data).
 */
export async function test_api_discussionboard_test_list_board_categories_with_invalid_filter_values(
  connection: api.IConnection,
) {
  // a. Attempt with extra unknown field (should fail schema validation)
  await TestValidator.error("Schema rejects unknown property")(
    async () => {
      // Purposefully inject a property not in the schema to test rejection.
      // TypeScript won't allow a type-safe call, so we use 'as any'.
      await api.functional.discussionboard.boardCategories.index(connection, {
        body: {
          name: "General",
          unknownField: "shouldCauseError"
        } as any,
      });
    },
  );

  // b. Attempt with negative position value
  await TestValidator.error("position should not accept negative value")(
    async () => {
      await api.functional.discussionboard.boardCategories.index(connection, {
