        body: {
          name: "!@#$$%^&*(_)+~`|<>?:\"{}[];'.,/".repeat(10),
        },
      });
    },
  );

  // d. Control: use valid filter criteria to ensure positive case still works
  const validResult = await api.functional.discussionboard.boardCategories.index(connection, {
    body: {
      name: "General",
      code: "general",
      description: "General posts",
      position: 1,
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(validResult);
}

