import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { Idiscussionboard_boards } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_boards";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardThreadSnapshots } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreadSnapshots";
import type { IPageIDiscussionboardThreadSnapshots } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardThreadSnapshots";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate the retrieval of thread snapshots with filtering and pagination on the discussion board.
 *
 * This test simulates the following business workflow:
 * 1. Create a member who will be used as a thread author and as a possible actor for snapshots.
 * 2. Create a board with random but valid category/section uuid values (as category/section tables are not present; use random for test isolation).
 * 3. Create a discussion thread in the board, authored by the member.
 * 4. Create multiple thread snapshots for the thread, varying actors (the member, system/null), bodies, and reasons (use deterministic substrings for filtering verification).
 * 5. List thread snapshots, filtering by thread_id to ensure only those snapshots are returned (happy path).
 * 6. List thread snapshots filtered by actor_id to validate only those snapshots created by the member appear.
 * 7. List thread snapshots using a partial reason substring to check filtering on text fields (if supported, otherwise only test with full strings).
 * 8. Test pagination by requesting a limited number of snapshots per page and validating that total records/pages are consistent with inserted count and that distinct records are returned per page.
 * 9. Validate that only schema-defined fields are present in all responses.
 *
 * Throughout, assert correct filtering and shape of results, and that the endpoint supports pagination and filtering options.
 */
export async function test_api_discussionboard_test_list_thread_snapshots_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create a member
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create a board
  const board = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
      name: RandomGenerator.alphabets(8),
      code: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(),
      is_active: true,
      is_visible: true,
    } satisfies Idiscussionboard_boards.ICreate,
  });
  typia.assert(board);

  // 3. Create a thread in this board
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: board.id,
      author_member_id: member.id,
      title: "Snapshot Test Thread",
      body: "Initial body for thread snapshot tests.",
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(thread);

  // 4. Create multiple snapshots for the thread with varying actors/bodies/reasons
  const reasons = ["edit:typo", "edit:clarify", "mod:cleanup", "rollback:dispute", "bulk update"];
  const createdSnapshots: IDiscussionboardThreadSnapshots[] = [];
  for (let i = 0; i < 7; ++i) {
    const actorId = i % 2 === 0 ? member.id : null;
    const reasonStr = reasons[i % reasons.length] + ` #${i}`;
    const snap = await api.functional.discussionboard.threadSnapshots.create(connection, {
      body: {
        thread_id: thread.id,
        actor_id: actorId,
        title: `Snapshot ${i}`,
        body: `Thread body at version ${i}`,
        reason: reasonStr,
      } satisfies IDiscussionboardThreadSnapshots.ICreate,
    });
    typia.assert(snap);
    createdSnapshots.push(snap);
  }

  // 5. List by thread_id (happy path, all snapshots for this thread)
  const allByThread = await api.functional.discussionboard.threadSnapshots.index(connection, {
    body: {
      thread_id: thread.id,
      page: 1,
      limit: 10,
    } satisfies IDiscussionboardThreadSnapshots.IRequest,
  });
  typia.assert(allByThread);
  TestValidator.equals("snapshots for thread_id")(allByThread.pagination.records)(createdSnapshots.length);
  for (const record of allByThread.data) {
    TestValidator.equals("thread_id matches")(record.thread_id)(thread.id);
  }

  // 6. List by actor_id (should return only those with actor = member.id)
  const byActor = await api.functional.discussionboard.threadSnapshots.index(connection, {
    body: {
      actor_id: member.id,
      thread_id: thread.id,
      page: 1,
      limit: 10,
    } satisfies IDiscussionboardThreadSnapshots.IRequest,
  });
  typia.assert(byActor);
  for (const s of byActor.data) {
    TestValidator.equals("actor_id matches")(s.actor_id)(member.id);
  }
  const expectedByActor = createdSnapshots.filter(s => s.actor_id === member.id).length;
  TestValidator.equals("count by actor")(byActor.pagination.records)(expectedByActor);

  // 7. List by partial reason substring (if supported filter in real API), otherwise strict match only
  // Since API schema only provides 'reason' property, test for presence using exact match
  const reasonToFind = reasons[2] + " #4"; // deterministic: should be at index 4
  const byReason = await api.functional.discussionboard.threadSnapshots.index(connection, {
    body: {
      thread_id: thread.id,
      page: 1,
      limit: 10,
    } satisfies IDiscussionboardThreadSnapshots.IRequest,
  });
  typia.assert(byReason);
  const matched = byReason.data.find(s => s.reason === reasonToFind);
  TestValidator.predicate("should contain expected reason snapshot")(!!matched);
  if (matched) TestValidator.equals("reason matches")(matched.reason)(reasonToFind);

  // 8. Test pagination logic
  const pageLimit = 3;
  const page1 = await api.functional.discussionboard.threadSnapshots.index(connection, {
    body: {
      thread_id: thread.id,
      page: 1,
      limit: pageLimit,
    } satisfies IDiscussionboardThreadSnapshots.IRequest,
  });
  typia.assert(page1);
  TestValidator.equals("limit respected")(page1.data.length)(pageLimit);
  TestValidator.equals("pagination records")(page1.pagination.records)(createdSnapshots.length);
  TestValidator.equals("page current")(page1.pagination.current)(1);
  // Fetch second page if available
  if (createdSnapshots.length > pageLimit) {
    const page2 = await api.functional.discussionboard.threadSnapshots.index(connection, {
      body: {
        thread_id: thread.id,
        page: 2,
        limit: pageLimit,
      } satisfies IDiscussionboardThreadSnapshots.IRequest,
    });
    typia.assert(page2);
    TestValidator.equals("page2 limit respected")(page2.data.length)(Math.min(pageLimit, createdSnapshots.length - pageLimit));
    TestValidator.equals("page2 current")(page2.pagination.current)(2);
    // Check for non-overlapping snapshot ids if at least 2 pages
    if (page2.data.length) {
      const idsPage1 = page1.data.map(s => s.id).sort();
      const idsPage2 = page2.data.map(s => s.id).sort();
      for (const id of idsPage2) TestValidator.predicate("snapshots should not repeat across pages")(!idsPage1.includes(id));
    }
  }

  // 9. Validate schema fields only for all returned items
  for (const snapResult of [...allByThread.data, ...byActor.data, ...byReason.data]) {
    // The following are valid keys as per IDiscussionboardThreadSnapshots
    const allowedKeys = ["id","thread_id","actor_id","title","body","reason","created_at"];
    for (const k of Object.keys(snapResult)) TestValidator.predicate(`no extra field '${k}'`)(allowedKeys.includes(k));
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
