 *   - Not found: When attempting to update a snapshot with an invalid/non-existent id, the API should return a not found error (404).
 *   - Validation & field restriction: When updating a valid snapshot, only permitted fields (body, reason) should be changeable. Attempts to update immutable/non-schema fields should be ignored or rejected, and a schema validation error must occur.
 *
 * The following steps are covered:
 * 1. Member is created for authorship context (precondition)
 * 2. Board is created to host thread (precondition)
 * 3. Thread is created (precondition)
 * 4. Valid thread snapshot is created (target for update)
 * 5. Attempt update with non-existent id → expect not found error
 * 6. Attempt valid update (body/reason fields) → expect success
 * 7. Attempt update with unknown/immutable fields (should not be possible in request schema, but API should ignore/reject extra fields)
 */
export async function test_api_discussionboard_test_update_thread_snapshot_with_invalid_id_or_immutable_fields(connection: api.IConnection) {
  // 1. Create member
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
