      code: RandomGenerator.alphaNumeric(6),
      description: "Discussion board for tests",
      is_active: true,
      is_visible: true,
    },
  });
  typia.assert(board);

  // 3. Create thread
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: board.id,
      author_member_id: member.id,
      title: "Snapshot E2E Test Thread",
      body: "Baseline content for thread snapshot test",
    },
  });
  typia.assert(thread);

  // 4. Create valid snapshot
  const snapshot = await api.functional.discussionboard.threadSnapshots.create(connection, {
    body: {
      thread_id: thread.id,
      actor_id: member.id,
      title: thread.title,
      body: thread.body,
      reason: "Initial creation",
    },
  });
