  // 5. Attempt update with non-existent id
  await TestValidator.error("updating non-existent snapshot id should fail")(
    async () => {
      await api.functional.discussionboard.threadSnapshots.update(connection, {
        id: typia.random<string & tags.Format<"uuid">>(), // very likely to be unused id
        body: {
