/**
 * Validate creation of thread tag assignment with successful, duplicate, and invalid data scenarios.
 *
 * This test ensures that assigning a tag to a thread works as expected, duplicate constraint prevents multiple identical assignments, and that missing required fields fail with validation error. It also checks assigning a tag that is immediately removed (removed_at set).
 *
 * Test Steps:
 * 1. Create a member (for thread ownership).
 * 2. Create a board (all required fields).
 * 3. Create a thread on the board (by member).
 * 4. Assign a tag to the thread (minimum required fields, assigned_at = now, no removed_at).
 * 5. Assert response shape is valid (typia.assert), values match input.
 * 6. Attempt to assign the same tag again—should produce constraint violation or error.
 * 7. Attempt to assign a tag omitting required field(s) (e.g. no thread_id)—should produce validation error.
 * 8. Assign a tag to the thread with removed_at = assigned_at (simulate immediate removal), check response field(s).
 */
export async function test_api_discussionboard_test_create_thread_tag_assignment_with_valid_and_duplicate_data(
  connection: api.IConnection,
) {
  // 1. Create a member (thread author)
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create a board
  const board = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
      name: RandomGenerator.alphaNumeric(12),
      code: RandomGenerator.alphaNumeric(8),
      description: null,
      is_active: true,
      is_visible: true,
    } satisfies Idiscussionboard_boards.ICreate,
  });
  typia.assert(board);

  // 3. Create a thread on the board
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: board.id,
      author_member_id: member.id,
      title: RandomGenerator.alphaNumeric(18),
      body: RandomGenerator.content()()(25),
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(thread);

  // 4. Assign a tag to the thread
  const assignedAt = new Date().toISOString();
  const tagAssignBody: IDiscussionboardThreadTag.ICreate = {
    thread_id: thread.id,
    assigned_at: assignedAt,
  };
  const tagAssign = await api.functional.discussionboard.threadTags.create(connection, {
    body: tagAssignBody,
  });
  typia.assert(tagAssign);
  TestValidator.equals("assigned thread_id")(tagAssign.thread_id)(thread.id);
  TestValidator.equals("assigned_at matches")(tagAssign.assigned_at)(assignedAt);
  TestValidator.equals("removed_at null")(tagAssign.removed_at)(null);

  // 5. Attempt to assign the same tag again (should error)
  await TestValidator.error("duplicate tag assignment should error")(
    async () => {
      await api.functional.discussionboard.threadTags.create(connection, {
        body: tagAssignBody,
      });
    },
  );

  // 6. Attempt to assign a tag omitting required field (thread_id missing)
  await TestValidator.error("missing required thread_id should error")(
    async () => {
      await api.functional.discussionboard.threadTags.create(connection, {
        body: {
          assigned_at: assignedAt,
        } as any, // purposeful type-violation for runtime error only
      });
    },
  );

  // 7. Assign a tag with immediate removal (removed_at set)
  const removedAt = assignedAt;
  const tagAssignRemoved: IDiscussionboardThreadTag.ICreate = {
    thread_id: thread.id,
    assigned_at: assignedAt,
    removed_at: removedAt,
  };
  const tagRemoved = await api.functional.discussionboard.threadTags.create(connection, {
    body: tagAssignRemoved,
  });
  typia.assert(tagRemoved);
  TestValidator.equals("removed_at matches")(tagRemoved.removed_at)(removedAt);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IPostReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostReport";
import type { IPageIPostReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPostReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test advanced search and pagination for post reports by moderators.
 *
 * Purpose: Verify the filtering logic and pagination of PATCH /discussionboard/postReports, ensuring correct result sets when filtering by post id, reporter id, report type, and created_at. Also validate pagination metadata and edge conditions (no results, out-of-range filters, small/large page sizes).
 *
 * Steps:
 * 1. Create several discussion posts (for use as report targets)
 * 2. Generate several distinct reporter_member_id and report_type_id values (UUIDs)
 * 3. Create a batch of post reports with various (post, reporter, report type, created_at) combinations
 * 4. For each filter type (by post_id, reporter_member_id, report_type_id, created_at, multi-filter, and non-existent/out-of-range edge cases):
 *    - PATCH /discussionboard/postReports with filter(s)
 *    - Verify only matching records are returned
 *    - Validate pagination fields (current/limit/records/pages)
 *    - Check edge behaviors (empty result, big page size, etc)
 */
export async function test_api_discussionboard_test_search_post_reports_with_multiple_filters_and_pagination(
  connection: api.IConnection,
) {
  // --- Test Setup ---
  // 1. Generate several posts
  const postCount = 4;
  const posts: IDiscussionboardPost[] = [];
  for (let i = 0; i < postCount; ++i) {
    const post = await api.functional.discussionboard.posts.create(connection, {
      body: {
        discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
        title: `Test post ${i+1}`,
        body: `Some content for post ${i+1}`,
        is_deleted: false,
        created_at: new Date(Date.now() - (1000*60*60*24)*i).toISOString(),
        updated_at: new Date(Date.now() - (1000*60*60*24)*i).toISOString(),
      } satisfies IDiscussionboardPost.ICreate
    });
    typia.assert(post);
    posts.push(post);
  }

  // 2. Generate mock reporters and report types (UUIDs)
  const reporterIds: (string & tags.Format<"uuid">)[] = [typia.random<string & tags.Format<"uuid">>(), typia.random<string & tags.Format<"uuid">>()];
  const reportTypeIds: (string & tags.Format<"uuid">)[] = [typia.random<string & tags.Format<"uuid">>(), typia.random<string & tags.Format<"uuid">>()];

  // 3. Create a batch of post reports (mixing posts, reporters, report types, and different created_at)
  const reports: IPostReport[] = [];
  let report_created_ats: string[] = [];
  for (let i = 0; i < 6; ++i) {
    const post = posts[i % postCount];
    const reporterId = reporterIds[i % reporterIds.length];
    const reportTypeId = reportTypeIds[(i+1) % reportTypeIds.length];
    // Stagger created_at so we can test timestamps as filters
    const createdAt = new Date(Date.now() - (1000*60*60*12)*i).toISOString();
    report_created_ats.push(createdAt);
    const report = await api.functional.discussionboard.postReports.create(connection, {
      body: {
        discussionboard_post_id: post.id,
        reporter_member_id: reporterId,
        report_type_id: reportTypeId,
        description: `Report ${i+1} for testing`,
        created_at: createdAt,
      } satisfies IPostReport.ICreate,
    });
    typia.assert(report);
    reports.push(report);
  }

  // --- Tests ---
  // 4a. Filter by post id
  const targetPost = posts[0];
  const filterByPost = await api.functional.discussionboard.postReports.index(connection, {
    body: {
      discussionboard_post_id: targetPost.id,
    } satisfies IPostReport.IRequest,
  });
  typia.assert(filterByPost);
  TestValidator.predicate("all reports belong to filtered post")(
    filterByPost.data.every(r => r.discussionboard_post_id === targetPost.id)
  );

  // 4b. Filter by reporter_member_id
  const targetReporterId = reporterIds[0];
  const filterByReporter = await api.functional.discussionboard.postReports.index(connection, {
    body: {
      reporter_member_id: targetReporterId,
    } satisfies IPostReport.IRequest,
  });
  typia.assert(filterByReporter);
  TestValidator.predicate("all reports belong to filtered reporter")(
    filterByReporter.data.every(r => r.reporter_member_id === targetReporterId)
  );

  // 4c. Filter by report_type_id
  const targetReportTypeId = reportTypeIds[1];
  const filterByType = await api.functional.discussionboard.postReports.index(connection, {
    body: {
      report_type_id: targetReportTypeId,
    } satisfies IPostReport.IRequest,
  });
  typia.assert(filterByType);
  TestValidator.predicate("all reports have filtered report_type")(
    filterByType.data.every(r => r.report_type_id === targetReportTypeId)
  );

  // 4d. Filter by created_at (exact match for one that exists)
  const exactCreatedAt = report_created_ats[2];
  const filterByCreatedAt = await api.functional.discussionboard.postReports.index(connection, {
    body: {
      created_at: exactCreatedAt,
    } satisfies IPostReport.IRequest,
  });
  typia.assert(filterByCreatedAt);
  TestValidator.predicate("all reports for exact created_at")(
    filterByCreatedAt.data.every(r => r.created_at === exactCreatedAt)
  );

  // 4e. Filter by multiple fields (post id + reporter_member_id)
  const comboReport = reports.find(r => r.discussionboard_post_id === targetPost.id && r.reporter_member_id === targetReporterId);
  if (comboReport) {
    const comboFilter = await api.functional.discussionboard.postReports.index(connection, {
      body: {
        discussionboard_post_id: targetPost.id,
        reporter_member_id: targetReporterId,
      } satisfies IPostReport.IRequest,
    });
    typia.assert(comboFilter);
    TestValidator.predicate("all reports match combined filter")(
      comboFilter.data.every(r => r.discussionboard_post_id === targetPost.id && r.reporter_member_id === targetReporterId)
    );
  }

  // 4f. Non-existent values (should be empty)
  const fakeUUID = typia.random<string & tags.Format<"uuid">>();
  const emptyResults = await api.functional.discussionboard.postReports.index(connection, {
    body: {
      discussionboard_post_id: fakeUUID,
    } satisfies IPostReport.IRequest,
  });
  typia.assert(emptyResults);
  TestValidator.equals("results should be empty")(emptyResults.data.length)(0);

  // 4g. Out-of-range created_at (should return empty)
  const oldDate = new Date("2000-01-01T00:00:00.000Z").toISOString();
  const emptyByOldDate = await api.functional.discussionboard.postReports.index(connection, {
    body: {
      created_at: oldDate,
    } satisfies IPostReport.IRequest,
  });
  typia.assert(emptyByOldDate);
  TestValidator.equals("results for old created_at should be empty")(emptyByOldDate.data.length)(0);

  // 4h. Page size (not explicitly supported in IRequest but test multiple records still returned)
