/**
 * Test creating post references with various combinations of required and optional fields
 * for cross-referencing posts/threads in the discussion board.
 *
 * This test covers:
 * - Successful creation with required fields (source post ID + reference type)
 * - Creation including optional fields target_post_id and target_thread_id, including all permutations
 * - Foreign key constraints/failures (attempt reference to non-existent target post/thread)
 * - Validation errors for missing required fields
 *
 * 1. Create valid discussion thread and associated post entities (as needed for references)
 * 2. Create post reference with only required fields (link to self, e.g. source_post_id, reference_type)
 * 3. Create reference with target_post_id, referencing another valid post
 * 4. Create reference with target_thread_id, referencing another thread
 * 5. Try referencing non-existent post/thread (should error)
 * 6. Try to create reference with missing required fields (should error)
 */
export async function test_api_discussionboard_test_create_post_reference_with_required_and_optional_fields(
  connection: api.IConnection,
) {
  // 1. Setup: create two threads and two posts, each post in a different thread with shared author/member/board
  const board_id = typia.random<string & tags.Format<"uuid">>();
  const author_member_id = typia.random<string & tags.Format<"uuid">>();
  const thread1 = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id,
      author_member_id,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(thread1);
  const thread2 = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id,
      author_member_id,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(thread2);

  // Posts for each thread
  const now = new Date().toISOString();
  const post1 = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: thread1.id,
      discussionboard_member_id: author_member_id,
      discussionboard_board_id: board_id,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
      is_deleted: false,
      created_at: now,
      updated_at: now,
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post1);
  const post2 = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: thread2.id,
      discussionboard_member_id: author_member_id,
      discussionboard_board_id: board_id,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
      is_deleted: false,
      created_at: now,
      updated_at: now,
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post2);

  // 2. Create post reference with only required fields (no target_post_id/thread_id)
  const ref1 = await api.functional.discussionboard.postReferences.create(connection, {
    body: {
      source_post_id: post1.id,
      reference_type: "mention",
    } satisfies IPostReference.ICreate,
  });
  typia.assert(ref1);
  TestValidator.equals("source_post_id matches")(ref1.source_post_id)(post1.id);
  TestValidator.equals("ref type")(ref1.reference_type)("mention");
  TestValidator.equals("target_post_id unset")(ref1.target_post_id)(null);
  TestValidator.equals("target_thread_id unset")(ref1.target_thread_id)(null);

  // 3. Create reference with target_post_id
  const ref2 = await api.functional.discussionboard.postReferences.create(connection, {
    body: {
      source_post_id: post1.id,
      reference_type: "post",
      target_post_id: post2.id,
    } satisfies IPostReference.ICreate,
  });
  typia.assert(ref2);
  TestValidator.equals("target_post_id matches")(ref2.target_post_id)(post2.id);
  TestValidator.equals("target_thread_id unset")(ref2.target_thread_id)(null);

  // 4. Create reference with target_thread_id
  const ref3 = await api.functional.discussionboard.postReferences.create(connection, {
    body: {
      source_post_id: post1.id,
      reference_type: "thread",
      target_thread_id: thread2.id,
    } satisfies IPostReference.ICreate,
  });
  typia.assert(ref3);
  TestValidator.equals("target_thread_id matches")(ref3.target_thread_id)(thread2.id);
  TestValidator.equals("target_post_id unset")(ref3.target_post_id)(null);

  // 5. Attempt reference to non-existent post/thread (should error)
  const fake_uuid = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("non-existent target_post_id should fail")(() =>
    api.functional.discussionboard.postReferences.create(connection, {
      body: {
        source_post_id: post1.id,
        reference_type: "post",
        target_post_id: fake_uuid,
      } as any,
    })
  );
  await TestValidator.error("non-existent target_thread_id should fail")(() =>
    api.functional.discussionboard.postReferences.create(connection, {
      body: {
        source_post_id: post1.id,
        reference_type: "thread",
        target_thread_id: fake_uuid,
      } as any,
    })
  );

  // 6. Missing required fields (should error)
  await TestValidator.error("missing source_post_id should fail")(() =>
    api.functional.discussionboard.postReferences.create(connection, {
      body: {
        // source_post_id omitted intentionally
        reference_type: "mention",
      } as any,
    })
  );
  await TestValidator.error("missing reference_type should fail")(() =>
    api.functional.discussionboard.postReferences.create(connection, {
      body: {
        source_post_id: post1.id,
        // reference_type omitted intentionally
      } as any,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
