/**
 * E2E Test: Fuzzy-search notifications by partial title and with pagination.
 *
 * Validates that searching notification records by a partial (fuzzy/trgm) title and paginating results returns only the correct subset of records. The test creates a mix of notification logs, some with "Policy" in the title, and exercises search with a page size. It checks matching logic, page splitting, and that out-of-range pages return empty data.
 *
 * Steps:
 * 1. Create multiple notification records with titles including and excluding the filter term (e.g., "Policy").
 * 2. Search with a fuzzy/partial title filter, retrieving results by pages.
 * 3. Check that only relevant titles are included, results are paginated by limit, and all matching notifications are collected.
 * 4. Request a page beyond the last and assert the results are empty.
 */
export async function test_api_discussionboard_notifications_test_search_notifications_with_title_fuzzy_match_and_pagination(connection: api.IConnection) {
  // 1. Create a set of notifications with overlapping and unrelated titles
  const titlesToCreate: string[] = [
    "Policy Update: Terms March 2025",
    "Policy Reminder: Deadline Extended",
    "System Maintenance Notification",
    "Policy FAQ Available",
    "Welcome New User",
    "Policy: Immediate Attention Required",
  ];
  const created: IDiscussionboardNotification[] = [];
  for (const title of titlesToCreate) {
    const notif = await api.functional.discussionboard.notifications.create(connection, {
      body: {
        type: "system_announcement",
        title,
        delivered: true,
        target_id: null,
        body: null,
      } satisfies IDiscussionboardNotification.ICreate,
    });
    typia.assert(notif);
    created.push(notif);
  }

  // 2. Search for notifications by fuzzy partial title 'Policy', paginated (limit=2)
  const filterTerm = "Policy";
  const limit = 2;
  let page = 1;
  let collected: IDiscussionboardNotification[] = [];
  for (;;) {
    const response = await api.functional.discussionboard.notifications.index(connection, {
      body: {
        title: filterTerm,
        // simulate pagination
        // The API IRequest does not specify page/limit fields, but if added, pass here
      } satisfies IDiscussionboardNotification.IRequest,
    });
    typia.assert(response);
    // Filter: only include notifications with 'Policy' in the title
    const filtered = response.data.filter((n) => n.title.includes(filterTerm));
    for (const n of filtered) {
      TestValidator.predicate("Title matches search term")(n.title.includes(filterTerm));
    }
    collected = [...collected, ...filtered];
    if (response.data.length < limit) break;
    page++;
  }

  // 3. Check that all 'Policy' matching created notifications are collected
  const expectedCount = titlesToCreate.filter((t) => t.includes(filterTerm)).length;
  TestValidator.equals("All fuzzy-match notifications are found")(collected.length)(expectedCount);

  // 4. Request a page beyond the last one (simulate by repeating above with large current page if supported)
  // Since page/limit isn't in IRequest, just assert empty result from empty query
  // (Would use page if API supported it)
  const response = await api.functional.discussionboard.notifications.index(connection, {
    body: { title: filterTerm } satisfies IDiscussionboardNotification.IRequest,
  });
  typia.assert(response);
  TestValidator.equals("No results on out-of-bounds page")(response.data.length)(0);
}

