import type { IDiscussionboardBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoardCategory";

/**
 * Test deleting a board by id, including normal, double, and error cases.
 *
 * This test validates the full lifecycle of deleting a discussion board:
 * 1. Set up required board category and section (as admin).
 * 2. Create a new board entity for deletion.
 * 3. Delete the created board by its id (happy path).
 * 4. Attempt to delete the same id again, expect proper error handling.
 * 5. Attempt to delete with a non-existent (random) uuid, expect error.
 * 6. Attempt to delete with an invalid uuid string, expect error.
 *
 * Referential integrity and FK behavior is implicitly checked with delete error outcomes.
 */
export async function test_api_discussionboard_test_delete_board_with_existing_and_nonexistent_id(
  connection: api.IConnection,
) {
  // 1. Create a board category
  const category = await api.functional.discussionboard.boardCategories.create(connection, {
    body: {
      name: RandomGenerator.paragraph()(),
      code: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(),
      position: typia.random<number & tags.Type<"int32">>(),
    }
  });
  typia.assert(category);

  // 2. Create a section (using a random channel UUID due to missing channel API)
  const section = await api.functional.discussionboard.sections.create(connection, {
    body: {
      discussionboard_channel_id: typia.random<string & tags.Format<"uuid">>(),
      code: RandomGenerator.alphabets(8),
      name: RandomGenerator.name(),
      description: RandomGenerator.paragraph()(),
      position: typia.random<number & tags.Type<"int32">>(),
      active: true,
    },
  });
  typia.assert(section);

  // 3. Create the board under this category and section
  const board = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: category.id,
      discussionboard_section_id: section.id,
      name: RandomGenerator.paragraph()(),
      code: RandomGenerator.alphabets(10),
      description: RandomGenerator.paragraph()(),
      is_active: true,
      is_visible: true,
    },
  });
  typia.assert(board);

  // 4. Delete the board by its id
  await api.functional.discussionboard.boards.erase(connection, { id: board.id });

  // 5. Attempt to delete the same id again, expect error (already deleted)
  await TestValidator.error("deleting already deleted board should fail")(
    async () => {
      await api.functional.discussionboard.boards.erase(connection, { id: board.id });
    }
  );

  // 6. Attempt to delete a non-existent (random) uuid, expect error
  await TestValidator.error("deleting non-existent board id should fail")(
    async () => {
      await api.functional.discussionboard.boards.erase(connection, { id: typia.random<string & tags.Format<"uuid">>() });
    }
  );

  // 7. Attempt to delete with an invalid UUID (not uuid format), expect error
  await TestValidator.error("deleting invalid uuid should fail")(
    async () => {
      await api.functional.discussionboard.boards.erase(connection, { id: "not-a-uuid-format" as any });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
