 *
 * This test ensures the end-to-end flow for a member posting to a thread within a board works as expected.
 * To satisfy all foreign key constraints, the test performs the following sequence:
 * 1. Create a new discussion board member (author).
 * 2. Create a new discussion board.
 * 3. Create a new thread authored by the member in the created board.
 * 4. Create a post in that thread using the member and board references, filling all required fields from IDiscussionboardPost.ICreate.
 * 5. Assert the response contains the expected post data and correct associations (thread, member, board). Validate type, value, and basic integrity constraints.
 */
export async function test_api_discussionboard_test_create_post_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create discussion board member
  const memberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(12),
    role: "member",
    is_active: true,
  };
  const member = await api.functional.discussionboard.members.create(connection, { body: memberInput });
  typia.assert(member);

  // 2. Create discussion board (requires existing category/section UUIDs—use random for test)
  const boardInput: Idiscussionboard_boards.ICreate = {
    discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
    name: RandomGenerator.alphabets(10),
    code: RandomGenerator.alphaNumeric(10),
    description: RandomGenerator.paragraph()(),
    is_active: true,
    is_visible: true,
  };
  const board = await api.functional.discussionboard.boards.create(connection, { body: boardInput });
  typia.assert(board);

  // 3. Create thread in the board, authored by member
  const threadInput: IDiscussionboardThreads.ICreate = {
    board_id: board.id,
    author_member_id: member.id,
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
  };
  const thread = await api.functional.discussionboard.threads.create(connection, { body: threadInput });
  typia.assert(thread);

  // 4. Create post in the thread (all required fields)
  const now = new Date().toISOString();
  const postInput: IDiscussionboardPost.ICreate = {
    discussionboard_thread_id: thread.id,
    discussionboard_member_id: member.id,
    discussionboard_board_id: board.id,
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
    is_deleted: false,
    created_at: now,
    updated_at: now,
