/**
 * E2E validation for searching an authenticated user's own discussionboard member profiles
 * via multiple filter combinations in IDiscussionboardMemberProfile.IRequest.
 *
 * 1. Register a new member and authenticate the connection for isolation.
 * 2. Pre-populate at least 3 profiles for the user, each with unique display_name, bio, avatar_url, location, and website_url.
 * 3. Search/filter by each property; for each, verify that only the matching user-owned profiles are returned.
 * 4. Test multi-property filter (e.g., display_name+location), confirming only records satisfying all are returned.
 * 5. Perform a search with non-existent property-values to confirm empty result returns.
 * 6. Test result pagination: set limit to 2 and verify splitting of results, page2 vs page1 contents.
 * 7. Send a filter including a non-schema field to confirm it is rejected (error thrown).
 * 8. In all steps, verify no other users' profiles are returned and the returned structure matches IPageIDiscussionboardMemberProfile.
 */
export async function test_api_my_discussionboard_member_profiles_test_search_own_member_profiles_with_various_filters(
  connection: api.IConnection,
) {
  // 1. Register a new member and authenticate the context for test isolation
  const username: string = RandomGenerator.alphaNumeric(10);
  const email: string = typia.random<string & tags.Format<"email">>();
  const password: string = RandomGenerator.alphaNumeric(10);
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username,
      email,
      hashed_password: password,
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. Pre-populate at least 3 profiles for this user
  const baseProfiles = [
    {
      display_name: "AlphaUser",
      bio: "Alpha bio line.",
      avatar_url: "https://example.com/avatars/alpha.png",
      location: "Seoul, South Korea",
      website_url: "https://alpha.example.com",
    },
    {
      display_name: "BetaUser",
      bio: "Beta tester.",
      avatar_url: "https://example.com/avatars/beta.png",
      location: "Busan, South Korea",
      website_url: "https://beta.example.com",
    },
    {
      display_name: "GammaUser",
      bio: "Gamma biography",
      avatar_url: "https://example.com/avatars/gamma.png",
      location: "Incheon, South Korea",
      website_url: "https://gamma.example.com",
    },
  ];

  // Create profiles for this authenticated member
  for (const profileData of baseProfiles) {
    await api.functional.my.discussionboard.member.profiles.index(connection, {
      body: profileData satisfies IDiscussionboardMemberProfile.IRequest,
    });
  }

  // Helper: Fetch all profiles for this user
  const fetchProfiles = async (filter: Partial<IDiscussionboardMemberProfile.IRequest>) => {
    const response = await api.functional.my.discussionboard.member.profiles.index(connection, {
      body: filter as IDiscussionboardMemberProfile.IRequest,
    });
    typia.assert(response);
    // All returned profiles should belong to this user
    for (const p of response.data) {
      TestValidator.equals("belongs to member")(p.member_id)(member.id);
    }
    return response;
  };

  // 3. Filter by each property
  for (const prop of ["display_name", "bio", "avatar_url", "location", "website_url"] as const) {
    for (const prof of baseProfiles) {
      const filter = { [prop]: prof[prop] };
      const response = await fetchProfiles(filter);
      // Should return at least one result with exact match
      TestValidator.predicate(`match on ${prop}`)(
        response.data.some(x => x[prop] === prof[prop])
      );
      // Should not include any unmatched records
      for (const x of response.data) {
        TestValidator.equals(`result exact for ${prop}`)(x[prop])(prof[prop]);
      }
    }
  }

  // 4. Multi-property filter (display_name + location)
  const combo = baseProfiles[0];
  const responseCombo = await fetchProfiles({
    display_name: combo.display_name,
    location: combo.location,
  });
  TestValidator.predicate("combo match only")(
    responseCombo.data.length === 1 &&
    responseCombo.data[0].display_name === combo.display_name &&
    responseCombo.data[0].location === combo.location
  );

  // 5. Search with non-existent property-values (should be empty)
  const responseNone = await fetchProfiles({
    display_name: "_NO_SUCH_USER_DISPLAYNAME_",
  });
  TestValidator.equals("empty for non-matching")(responseNone.data.length)(0);

  // 6. Pagination: limit 2, verify results and distinctness
  const page1 = await fetchProfiles({ pagination: { limit: 2, page: 1 } });
  TestValidator.equals("page1 limit")(page1.data.length)(2);
  const page2 = await fetchProfiles({ pagination: { limit: 2, page: 2 } });
  // Should not overlap
  TestValidator.notEquals("page1 != page2")(page1.data[0]?.id)(page2.data[0]?.id);
  // Together should contain only created profiles
  const allIds = new Set([
    ...page1.data.map(x => x.id),
    ...page2.data.map(x => x.id),
  ]);
  TestValidator.equals("all created covered")(allIds.size)(baseProfiles.length);

  // 7. Filter query including a non-schema field (should error)
  await TestValidator.error("reject unknown field")(() =>
    api.functional.my.discussionboard.member.profiles.index(connection, {
      body: {
        display_name: baseProfiles[0].display_name,
        not_in_schema: "shouldFail",
      } as any, // breach for negative test
    })
  );

  // 8. All responses must match the correct structure
  // Already asserted in typia.assert above for each response
}

