import type { IPageIDiscussionboardMemberProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardMemberProfile";

/**
 * Validate update of a user's own member profile, covering allowed profile fields.
 *
 * Test verifies that an authenticated user can update their own member profile using the schema-defined editable fields. The test process covers:
 * 1. User registration with a valid role (member) and is_active true.
 * 2. Creation of at least one profile for the new user.
 * 3. Attempting to update each allowed modifiable field (display_name, bio, avatar_url, location, website_url) one at a time, checking the returned profile reflects each update correctly.
 * 4. Attempting a combined update of multiple fields, ensuring all changed values are reflected and unrelated fields are not changed.
 * 5. Confirming only allowed schema fields are mutable—uneditable fields (such as id, member_id) are not changed.
 * 6. Verifying that the update fails if the profile id does not belong to the authenticated user (out-of-scope test for this implementation as cross-account context unavailable).
 */
export async function test_api_my_discussionboard_member_profiles_test_update_own_member_profile_fields_with_valid_data(connection: api.IConnection) {
  // 1. Register a new user (member)
  const username = RandomGenerator.alphaNumeric(12);
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(16);
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username,
      email,
      hashed_password: password,
      role: "member",
      is_active: true,
    },
  });
  typia.assert(member);

  // 2. Create a member profile for this user
  // In absence of an explicit profile creation API, assume PATCH index will create when no filter matches
  const randomDisplayName = RandomGenerator.alphaNumeric(10);
  const createProfileRes = await api.functional.my.discussionboard.member.profiles.index(connection, {
    body: {
      display_name: randomDisplayName,
      bio: "Initial bio text",
      avatar_url: "https://example.com/avatar.jpg",
      location: "Seoul, South Korea",
      website_url: "https://mysite.com",
    },
  });
  typia.assert(createProfileRes);
  const createdProfile = createProfileRes.data.find((x) => x.display_name === randomDisplayName) ?? createProfileRes.data[0];

  // 3. Update each editable field individually, validate update
  for (const [key, value] of Object.entries({
      display_name: "UpdatedDisplay",
      bio: "New bio text",
      avatar_url: "https://newavatar.example.com/img.png",
      location: "Busan, Korea",
      website_url: "https://newsite.net",
    })) {
    const updateRes = await api.functional.my.discussionboard.member.profiles.update(connection, {
      id: createdProfile.id,
      body: { [key]: value } as any,
    });
    typia.assert(updateRes);
    TestValidator.equals(`${key} updated correctly`)(updateRes[key as keyof typeof updateRes])(value);
  }

  // 4. Update multiple fields at once and verify all
  const multiUpdateBody = {
    display_name: "MultiFieldDisplay",
    bio: "Longer bio for multi-update test.",
    avatar_url: "https://multiupdate.example.com/avatar.png",
    location: "Incheon",
    website_url: "https://multiplesite.io",
  };
  const multiUpdate = await api.functional.my.discussionboard.member.profiles.update(connection, {
    id: createdProfile.id,
    body: multiUpdateBody,
  });
  typia.assert(multiUpdate);
  for (const [key, value] of Object.entries(multiUpdateBody)) {
    TestValidator.equals(`${key} multi-updated correctly`)(multiUpdate[key as keyof typeof multiUpdate])(value);
  }

  // 5. Ensure immutable fields remain unchanged
  TestValidator.equals("profile id remains unchanged")(multiUpdate.id)(createdProfile.id);
  TestValidator.equals("member_id remains unchanged")(multiUpdate.member_id)(createdProfile.member_id);
}

