 * This test verifies that when an authenticated user attempts to update a member profile using a UUID that does NOT exist (i.e., not associated with themselves or anyone),
 * the API responds with a not found error and does NOT leak or modify other users' profile information.
 *
 * Steps:
 * 1. Authenticate as a new user (register a member).
 * 2. Attempt to update a profile using a random (invalid) UUID.
 * 3. Confirm an error is thrown (as the profile should not exist or be inaccessible).
 * 4. Ensure there is no data leakage or unauthorized access in error path.
 */
export async function test_api_my_discussionboard_member_profiles_test_update_own_member_profile_with_nonexistent_id(
  connection: api.IConnection,
) {
  // 1. Register a new member (authentication context, single user scope)
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
