/**
 * Test searching and filtering the authenticated user's own notification and UI preferences.
 *
 * This scenario validates that the preferences search/filter API only honors valid schema fields, returns paginated data, ignores (or rejects) non-schema fields, and processes filters as expected. We cover all valid fields (receive_email_notifications, receive_push_notifications, preferred_language, dark_mode_enabled) in various combinations, using different search parameters, and test pagination edge cases.
 *
 * 1. Register a new discussionboard member (and implicitly become authenticated)
 * 2. Use /my/discussionboard/member/preferences search API to fetch with each valid field (individually and in combination)
 * 3. Assert results only include schema fields, never extra fields
 * 4. Assert correct filtering and pagination works for the current user
 */
export async function test_api_my_discussionboard_member_preferences_test_search_own_notification_preferences_by_valid_fields(connection: api.IConnection) {
  // 1. Register a new discussionboard member (register and implicitly login)
  const memberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    role: "member",
    is_active: true,
  };
  const member = await api.functional.discussionboard.members.create(connection, {
    body: memberInput,
  });
  typia.assert(member);

  // 2. Search without filters (return all)
  let output = await api.functional.my.discussionboard.member.preferences.index(connection, { body: {} });
  typia.assert(output);
  TestValidator.predicate("pagination meta present")(!!output.pagination);
  TestValidator.predicate("data array present")(Array.isArray(output.data));
  for (const pref of output.data)
    typia.assert(pref);

  // 3. Search with each valid field (confirmed do not error)
  output = await api.functional.my.discussionboard.member.preferences.index(connection, { body: { receive_email_notifications: true } });
  typia.assert(output);
  for (const pref of output.data)
    typia.assert(pref);

  output = await api.functional.my.discussionboard.member.preferences.index(connection, { body: { receive_push_notifications: false } });
  typia.assert(output);
  for (const pref of output.data)
    typia.assert(pref);

  output = await api.functional.my.discussionboard.member.preferences.index(connection, { body: { preferred_language: "en" } });
  typia.assert(output);
  for (const pref of output.data)
    typia.assert(pref);

  output = await api.functional.my.discussionboard.member.preferences.index(connection, { body: { dark_mode_enabled: true } });
  typia.assert(output);
  for (const pref of output.data)
    typia.assert(pref);

  // 4. Combinatorial valid field search
  output = await api.functional.my.discussionboard.member.preferences.index(connection, { body: { receive_email_notifications: false, preferred_language: "ko" } });
  typia.assert(output);
  for (const pref of output.data)
    typia.assert(pref);

  // 5. Pagination edge test: limit 1, page 1 (should return at most one record)
  output = await api.functional.my.discussionboard.member.preferences.index(connection, { body: { pagination: { page: 1, limit: 1 } } });
  typia.assert(output);
  TestValidator.predicate("at most one record on page 1")(output.data.length <= 1);

  // 6. Ensure no properties outside schema
  for (const pref of output.data) {
    const allowed = [
      "id",
      "member_id",
      "receive_email_notifications",
      "receive_push_notifications",
      "preferred_language",
      "dark_mode_enabled"
    ];
    for (const key of Object.keys(pref)) {
      TestValidator.predicate(`property ${key} allowed`)(allowed.includes(key));
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
