import type { IPageIDiscussionboardMemberPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardMemberPreference";

/**
 * 자신의 알림/환경설정 프리퍼런스에서 유효하지 않은(스키마 미정의) 필드로 검색 요청 시 validation 에러가 발생하는지 검증한다.
 *
 * - 허용되지 않은 필터(스키마 미정의 필드)로 검색 요청 시 API가 검증 오류를 반환해야 한다.
 * - 실제 회원 가입 및 인증 처리 선행 후 테스트 진행.
 *
 * 절차:
 * 1. 회원 등록 (필수)
 * 2. 정상 필터: 허용 필드(receive_email_notifications) 포함 검색 → 성공 검증
 * 3. 비정상 필터: 스키마에 없는 invalid_field 포함 → validation error 발생 확인
 */
export async function test_api_my_discussionboard_member_preferences_test_search_own_notification_preferences_with_invalid_field(
  connection: api.IConnection,
) {
  // 1. 회원 등록 (선행조건)
  const memberInput = {
    username: RandomGenerator.alphaNumeric(10),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(12),
    role: "member",
    is_active: true,
  } satisfies IDiscussionboardMember.ICreate;
  const member = await api.functional.discussionboard.members.create(connection, { body: memberInput });
  typia.assert(member);

  // 2. 정상 필터: 허용 필드로 검색 요청 → 성공해야 함
  const normalFilters = { receive_email_notifications: true } satisfies IDiscussionboardMemberPreference.IRequest;
  const normalResult = await api.functional.my.discussionboard.member.preferences.index(connection, { body: normalFilters });
  typia.assert(normalResult);

  // 3. 비정상 필터: 스키마에 없는 필드 추가 → 반드시 validation 에러 발생해야 함
  const invalidFilters = {
    receive_email_notifications: true,
    invalid_field: "should_fail_validation",
  } as unknown as IDiscussionboardMemberPreference.IRequest;

  await TestValidator.error("validation error - 스키마 미정의 필드 포함")(
    async () => {
      await api.functional.my.discussionboard.member.preferences.index(connection, { body: invalidFilters });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardMemberPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMemberPreference";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionboardMemberPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardMemberPreference";

/**
 * 인증된 사용자가 자신의 알림/환경설정 preference 레코드를 id로 수정할 수 있음을 검증한다.
 *
 * - 필드별(receive_email_notifications, receive_push_notifications, preferred_language, dark_mode_enabled) 값을 단독/동시로 변경하는 PUT이 허용됨을 검증한다.
 * - 모든 경우 응답에 반드시 변경된 항목이 반영되는지 확인한다.
 * - 본인 소유가 아닌(혹은 존재하지 않는) preference id에 대해 수정 시도시 실패 처리됨을 검증한다.
 *
 * 테스트 시나리오
 * 1. 테스트 회원을 신규 등록하여 authenticaion context을 만든다.
 * 2. 자신의 환경설정 preference를 1개 새로 만들어/확보한다.
 * 3. 개별 필드(receive_email_notifications, receive_push_notifications, preferred_language, dark_mode_enabled) 및 모두 동시 수정에 대해 PUT 호출, 응답값과 변경사항 일치 여부 검증
 * 4. 존재하지 않거나 자신의 소유가 아닌 preference id에 대해 PUT 호출 시도 시 실패(에러) 반응 검증
 */
export async function test_api_my_discussionboard_member_preferences_test_update_own_notification_preferences_with_valid_data(connection: api.IConnection) {
  // 1. 테스트 회원 등록
  const testMemberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphabets(16),
    role: 'member',
    is_active: true,
  };
  const member = await api.functional.discussionboard.members.create(connection, { body: testMemberInput });
  typia.assert(member);

  // 2. 환경설정 레코드를 하나 확보
  const prefSet = await api.functional.my.discussionboard.member.preferences.index(connection, { body: {} });
  typia.assert(prefSet);
  const preference = prefSet.data[0];

  // 3. 필드별/동시 수정에 대한 업데이트 및 검증
  const cases: IDiscussionboardMemberPreference.IUpdate[] = [
    { receive_email_notifications: true },
    { receive_push_notifications: false },
    { preferred_language: 'ko' },
    { dark_mode_enabled: true },
    {
      receive_email_notifications: false,
      receive_push_notifications: true,
      preferred_language: 'en',
      dark_mode_enabled: false,
    },
  ];
  let workingPref = preference;
  for (const patch of cases) {
    const updated = await api.functional.my.discussionboard.member.preferences.update(connection, { id: preference.id, body: patch });
