 *
 * This test covers:
 * 1. Bootstrap creation of a regular member who will become moderator.
 * 2. Bootstrap creation of a second member who will be assigned as admin (including self-assignment to grant appropriate privilege).
 * 3. Use the admin's assignment to assign the first member as moderator (valid IDs, current time for assigned_at, explicitly null for optional fields).
 * 4. Assert that all fields including required (member_id, assigned_by_admin_id, assigned_at) and optional (expires_at, revoked_at) work per schema, and are correct in the persisted moderator assignment.
 * 5. Validate that only one active moderator assignment is allowed per member (uniqueness constraint): attempt a duplicate assignment and assert it is rejected.
 */
export async function test_api_discussionboard_test_assign_moderator_with_valid_member_and_admin(
  connection: api.IConnection,
) {
  // 1. Create the member to be assigned as moderator
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(member);

  // 2. Create a second member who will become admin
  const adminMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(adminMember);

  // 3. Assign the newly created adminMember as admin (using self-assignment for bootstrap)
  const assigned_at_admin = new Date().toISOString();
  const adminAssignment = await api.functional.discussionboard.admins.create(connection, {
    body: {
      member_id: adminMember.id,
      assigned_by_admin_id: adminMember.id,
      assigned_at: assigned_at_admin,
      revoked_at: null,
    },
  });
  typia.assert(adminAssignment);
  TestValidator.equals("admin member id matches")(adminAssignment.member_id)(adminMember.id);

  // 4. Assign the first member as moderator using admin's assignment id
  const assigned_at_moderator = new Date().toISOString();
  const moderatorAssignment = await api.functional.discussionboard.moderators.create(connection, {
    body: {
      member_id: member.id,
      assigned_by_admin_id: adminAssignment.id,
      assigned_at: assigned_at_moderator,
      expires_at: null,
      revoked_at: null,
