  TestValidator.equals("assigned by admin")(moderatorAssignment.assigned_by_admin_id)(adminAssignment.id);
  TestValidator.equals("assigned at")(moderatorAssignment.assigned_at)(assigned_at_moderator);
  TestValidator.equals("expires at is null")(moderatorAssignment.expires_at)(null);
  TestValidator.equals("revoked at is null")(moderatorAssignment.revoked_at)(null);

  // 5. Attempt to assign same member as moderator again, expect uniqueness error
  await TestValidator.error("reject duplicate moderator assignment")(() =>
    api.functional.discussionboard.moderators.create(connection, {
      body: {
        member_id: member.id,
        assigned_by_admin_id: adminAssignment.id,
        assigned_at: new Date().toISOString(),
        expires_at: null,
        revoked_at: null,
      },
    })
  );
}

