  // 5-d. Filter by revoked_at present/null
  const activeRes = await api.functional.discussionboard.admins.index(connection, {
    body: { revoked_at: null },
  });
  typia.assert(activeRes);
  TestValidator.predicate("only active assignments returned")(
    activeRes.data.every(a => a.revoked_at === null),
  );

  const revokedRes = await api.functional.discussionboard.admins.index(connection, {
    body: { revoked_at: revokedAt },
  });
  typia.assert(revokedRes);
  TestValidator.predicate("revoked_at filter matches")(
    revokedRes.data.every(a => a.revoked_at === revokedAt),
  );

  // 6. Pagination test (limit=1): Not implemented,
  // as no limit/page key in IRequest per schema. If supported, code would test correct paging below.
}

