    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphabets(12),
      role: "admin",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(adminMember);

  // 2. Register a target member
  const normalMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphabets(12),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(normalMember);

  // 3. Assign admin privileges
  const now = new Date().toISOString();
  const adminAssignment = await api.functional.discussionboard.admins.create(connection, {
    body: {
      member_id: normalMember.id,
      assigned_by_admin_id: adminMember.id, // bootstrapped admin
      assigned_at: now,
      revoked_at: null,
    } satisfies IDiscussionboardAdmin.ICreate,
  });
  typia.assert(adminAssignment);
  TestValidator.equals("member is admin-assigned")(adminAssignment.revoked_at)(null);
  TestValidator.equals("correct member id")(adminAssignment.member_id)(normalMember.id);
  TestValidator.equals("correct assigned_by_admin_id")(adminAssignment.assigned_by_admin_id)(adminMember.id);

  // 4. Soft-revoke (delete) admin assignment
  const revoked = await api.functional.discussionboard.admins.erase(connection, {
    id: adminAssignment.id,
  });
  typia.assert(revoked);
  TestValidator.predicate("revoked_at is set")(!!revoked.revoked_at);
  TestValidator.equals("revoked id matches")(revoked.id)(adminAssignment.id);

  // 5. Idempotency: re-delete (erase) the already revoked assignment
  const revokedAgain = await api.functional.discussionboard.admins.erase(connection, {
    id: adminAssignment.id,
  });
  typia.assert(revokedAgain);
  TestValidator.equals("idempotency: revoked_at unchanged")(revokedAgain.revoked_at)(revoked.revoked_at);
  TestValidator.equals("idempotency: id matches")(revokedAgain.id)(revoked.id);

  // 6. Negative test: non-existent ID revocation
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("not found error on non-existent admin assignment id")(async () => {
    await api.functional.discussionboard.admins.erase(connection, { id: nonExistentId });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAdmin";
import type { IDiscussionboardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardChannel";

/**
 * Validates channel creation and uniqueness constraints in the discussion board system.
 *
 * Test ensures:
 * 1. An admin can create a channel with all required fields (success case).
 * 2. Creating a channel with a duplicate code and/or name fails due to unique constraint.
 * 3. Missing or invalid required fields trigger validation errors.
 *
 * Business steps:
 * 1. Register member -> assign self as admin.
 * 2. Create valid channel as admin. Assert properties.
 * 3. Duplicate code/name creation attempt fails.
 * 4. Omitting required/invalid field(s) each triggers appropriate error (code, name, position, active).
 */
export async function test_api_discussionboard_test_create_channel_success_and_duplicate_code_name_failure(
  connection: api.IConnection,
) {
  // 1. Create a member to be admin
  const adminMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "admin",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(adminMember);

  // 2. Assign admin privileges (self-assignment for bootstrap)
  const adminAssignment = await api.functional.discussionboard.admins.create(connection, {
    body: {
      member_id: adminMember.id,
      assigned_by_admin_id: adminMember.id,
      assigned_at: new Date().toISOString(),
      revoked_at: null,
    } satisfies IDiscussionboardAdmin.ICreate,
  });
  typia.assert(adminAssignment);

  // 3. Create a valid channel as admin
  const uniqueChannelInput: IDiscussionboardChannel.ICreate = {
    code: RandomGenerator.alphaNumeric(5),
    name: "TestChan_" + RandomGenerator.alphaNumeric(4),
    description: "Channel for E2E uniqueness test.",
    position: typia.random<number & tags.Type<"int32">>(),
    active: true,
  };
  const createdChannel = await api.functional.discussionboard.channels.create(connection, {
    body: uniqueChannelInput,
  });
  typia.assert(createdChannel);
  TestValidator.equals("channel.code matches")(createdChannel.code)(uniqueChannelInput.code);
  TestValidator.equals("channel.name matches")(createdChannel.name)(uniqueChannelInput.name);

  // 4. Attempt to create duplicate channel (same code/name)
  TestValidator.error("duplicate code-name rejected")(() =>
    api.functional.discussionboard.channels.create(connection, {
      body: {
        ...uniqueChannelInput,
        code: createdChannel.code, // duplicate
        name: createdChannel.name, // duplicate
      } satisfies IDiscussionboardChannel.ICreate,
    })
  );

  // 5. Required field validation error — omit 'code'
  TestValidator.error("missing code triggers validation error")(() =>
    api.functional.discussionboard.channels.create(connection, {
      body: {
        // code omitted
        name: RandomGenerator.alphaNumeric(8),
        description: "desc",
        position: typia.random<number & tags.Type<"int32">>(),
        active: true,
      } as any, // Intentional: missing required field, per E2E negative case
    })
  );

  // 6. Required field validation error — omit 'name'
  TestValidator.error("missing name triggers validation error")(() =>
    api.functional.discussionboard.channels.create(connection, {
      body: {
        code: RandomGenerator.alphaNumeric(6),
        // name omitted
        description: "desc",
        position: typia.random<number & tags.Type<"int32">>(),
        active: true,
      } as any, // Intentional: missing required field
    })
  );

  // 7. Invalid 'position' (should be number, but null passed)
  TestValidator.error("invalid position triggers validation error")(() =>
    api.functional.discussionboard.channels.create(connection, {
      body: {
        code: RandomGenerator.alphaNumeric(6),
        name: RandomGenerator.alphaNumeric(8),
        description: "desc",
        position: null as any, // Intentionally invalid
        active: true,
      } as any,
    })
  );

  // 8. Invalid 'active' (should be boolean, but null passed)
  TestValidator.error("invalid active triggers validation error")(() =>
    api.functional.discussionboard.channels.create(connection, {
      body: {
        code: RandomGenerator.alphaNumeric(6),
        name: RandomGenerator.alphaNumeric(8),
        description: "desc",
        position: typia.random<number & tags.Type<"int32">>(),
        active: null as any, // Intentionally invalid
      } as any,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardReportType } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardReportType";
import type { IPageIDiscussionboardReportType } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardReportType";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test searching and paginating the list of moderation report types using various filter combinations.
 *
 * This test ensures that admin/moderator users can filter and search the moderation report type list endpoint using multiple fields:
 * - code (partial and full)
 * - display_name (partial)
 * - description
 * - active status
 * - created_at
 *
 * It covers both typical and edge cases:
 *   - No results
 *   - Single result
 *   - Multiple matches (full page)
 *   - Various filter combinations
 *   - Error handling for invalid filter parameters (only at runtime, not TypeScript compile-time)
 *
 * Steps:
 * 1. Create multiple report types with distinct values (codes, names, actives, created_ats)
 * 2. Filter by active/inactive status
 * 3. Filter by partial code string
 * 4. Filter by display_name
 * 5. Filter by exact created_at
 * 6. Edge test: Query for a code that returns nothing
 * 7. Edge test: Query for a code that returns exactly one item
 * 8. Multi-hit/pagination simulation
 */
export async function test_api_discussionboard_test_list_report_types_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create sample report types with diverse values
  const sampleTypes = [
    {
      code: "spam",
      display_name: "Spam",
      description: "Unwanted advertisement",
      active: true,
      created_at: "2024-07-01T10:00:00Z",
    },
    {
      code: "abuse",
      display_name: "Abuse",
      description: "Offensive language",
      active: true,
      created_at: "2024-04-01T12:00:00Z",
    },
    {
      code: "test-old",
      display_name: "Old Report",
      description: "Report created far in the past",
      active: false,
      created_at: "2022-01-01T00:00:00Z",
    },
    {
      code: "inactive-type",
      display_name: "Inactive",
      description: "Inactive type",
      active: false,
      created_at: "2024-07-01T08:00:00Z",
    },
    {
      code: "duplicate",
      display_name: "Duplicate",
      description: "Repeated report",
      active: true,
      created_at: "2024-07-01T07:00:00Z",
    },
  ];

  const createdTypes: IDiscussionboardReportType[] = [];
  for (const t of sampleTypes) {
    const created = await api.functional.discussionboard.reportTypes.create(connection, { body: t });
    typia.assert(created);
    createdTypes.push(created);
  }

  // 2. Filter by active true
  let result = await api.functional.discussionboard.reportTypes.index(connection, { body: { active: true } });
  typia.assert(result);
  TestValidator.predicate("Only active types")(result.data.every(r => r.active));

  // 3. Filter by active false
  result = await api.functional.discussionboard.reportTypes.index(connection, { body: { active: false } });
  typia.assert(result);
  TestValidator.predicate("Only inactive types")(result.data.every(r => !r.active));

  // 4. Partial code match
  result = await api.functional.discussionboard.reportTypes.index(connection, { body: { code: "sp" } });
  typia.assert(result);
  TestValidator.predicate("Partial code match")(result.data.every(r => r.code.includes("sp")));

  // 5. Filter by display_name (exact match, substring)
  result = await api.functional.discussionboard.reportTypes.index(connection, { body: { display_name: "Inactive" } });
  typia.assert(result);
  TestValidator.predicate("Display name match")(result.data.every(r => r.display_name.includes("Inactive")));

  // 6. Filter by created_at (exact match)
  result = await api.functional.discussionboard.reportTypes.index(connection, { body: { created_at: "2024-07-01T10:00:00Z" } });
  typia.assert(result);
  TestValidator.predicate("Created date match")(result.data.every(r => r.created_at === "2024-07-01T10:00:00Z"));

  // 7. Edge: query matches none
  result = await api.functional.discussionboard.reportTypes.index(connection, { body: { code: "nonexistent" } });
  typia.assert(result);
  TestValidator.equals("Empty result count")(result.data.length)(0);

  // 8. Edge: query matches one
  result = await api.functional.discussionboard.reportTypes.index(connection, { body: { code: "duplicate" } });
  typia.assert(result);
  TestValidator.equals("Single hit count")(result.data.length)(1);
  TestValidator.equals("Code matches duplicate")(result.data[0].code)("duplicate");

  // 9. Simulate pagination (assert pagination object is present)
  result = await api.functional.discussionboard.reportTypes.index(connection, { body: { active: true } });
  typia.assert(result.pagination);
  TestValidator.predicate("Pagination meta present")(typeof result.pagination.current === "number");

  // Note: Invalid property-type scenarios can't be tested due to TypeScript typing.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardReportType } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardReportType";

/**
 * 신고 유형 단일 상세 조회 API의 성공/실패 및 권한 검증 시나리오
 *
 * - 신규 신고 유형(report type) 등록 후 반환 받은 id로 상세 조회해 모든 필드 값 일치 검증
 * - 임의의 랜덤 UUID로 조회 시 not found(404) 에러를 반드시 발생시켜야 함
 * - 관리자 권한이 아닌 일반 사용자, 혹은 미인증 상태에서는 401/403 권한 에러가 발생해야 정상
 *
 * 단계별 진행
 * 1. (어드민) 신고 유형 등록 후 id 확보
 * 2. (어드민) 등록된 id로 상세조회. 생성시 입력 데이터와 반환데이터 완전 일치 검증
 * 3. (어드민) 임의 uuid로 상세조회 시 NotFound(404) 오류 확인
 * 4. (일반회원/비인증자) 권한 없이 접근 시 401/403(권한에러) 확인
 */
export async function test_api_discussionboard_reportTypes_test_get_report_type_success_and_not_found(
  connection: api.IConnection,
) {
  // 1. (어드민) 신고 유형 신규 등록
  const createInput = {
    code: `test-${Date.now()}`,
    display_name: `테스트 신고유형 - ${Date.now()}`,
    description: "E2E 테스트용 신고 유형 설명",
    active: true,
    created_at: new Date().toISOString(),
  } satisfies IDiscussionboardReportType.ICreate;
  const created = await api.functional.discussionboard.reportTypes.create(connection, { body: createInput });
  typia.assert(created);

  // 2. (어드민) 등록된 id로 상세조회 - 생성시 입력 데이터와 반환값 동등 비교
  const read = await api.functional.discussionboard.reportTypes.at(connection, { id: created.id });
  typia.assert(read);
  // 입력과 반환(특히 code/display_name/description/active)는 완전히 일치해야 함
  TestValidator.equals("id 일치")(read.id)(created.id);
  TestValidator.equals("code 일치")(read.code)(createInput.code);
  TestValidator.equals("display_name 일치")(read.display_name)(createInput.display_name);
  TestValidator.equals("description 일치")(read.description ?? null)(createInput.description ?? null);
  TestValidator.equals("active 일치")(read.active)(createInput.active);
  // 생성시 서버 할당된 created_at은 ms까지 동일해야만 함(형식 일치)
  TestValidator.equals("created_at 일치")(read.created_at)(created.created_at);

  // 3. (어드민) 임의 uuid로 not found 에러 확인
  await TestValidator.error("존재하지 않는 id는 not found 에러")(() =>
    api.functional.discussionboard.reportTypes.at(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    }),
  );

  // 4. (권한 없는 일반회원/비로그인 상태 등) 권한 에러 확인
  // 미인증 토큰으로 동작
  const anonConn = { ...connection, headers: { ...connection.headers } };
  delete anonConn.headers.Authorization;
  await TestValidator.error("비인증 상태에서 권한 거부 에러")(() =>
    api.functional.discussionboard.reportTypes.at(anonConn, { id: created.id }),
  );
  // 권한 없는 더미 계정 시나리오(토큰 방식 추후 환경에 맞게 보강 필요)
  // 예시: const userConn = await loginAsRegularUser(...)
  // await TestValidator.error("일반회원 권한이 없는 경우 권한 거부 에러")(() =>
  //   api.functional.discussionboard.reportTypes.at(userConn, { id: created.id }),
  // );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardReportType } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardReportType";

/**
 * Validate updating of moderation report type fields and related error conditions.
 *
 * Business purpose:
 *   - Allows admins to modify the code, display_name, description, and active state of moderation report type records.
 *   - Ensures data integrity via code uniqueness, correct field validation, and proper persistence.
 *   - Confirms that only schema-permitted fields can be modified, improper mutations are prevented, and error states are surfaced per API contract.
 *
 * Test Scenario:
 * 1. Create two report types with different unique codes/display_names.
 * 2. Update type A's fields (code, display_name, description, active), verify all changes persisted.
 * 3. Attempt to update type A's code to match type B's code (should fail due to uniqueness constraint).
 * 4. Attempt invalid updates:
 *    - Use non-existent (random) id (should fail)
 *    - Use empty string for code or display_name (should fail)
 * 5. Toggle type A's active flag (deactivate/activate), verify state after each update.
 */
export async function test_api_discussionboard_test_update_report_type_fields_and_uniqueness_rule(
  connection: api.IConnection,
) {
  // 1. Create two report types A and B
  const now = new Date();
  const typeA = await api.functional.discussionboard.reportTypes.create(connection, {
    body: {
      code: `testcodeA_${RandomGenerator.alphaNumeric(7)}`,
      display_name: `신고유형A_${RandomGenerator.alphabets(5)}`,
      description: "테스트 생성 A",
      active: true,
      created_at: now.toISOString() as string & tags.Format<"date-time">,
    },
  });
  typia.assert(typeA);
  const typeB = await api.functional.discussionboard.reportTypes.create(connection, {
    body: {
      code: `testcodeB_${RandomGenerator.alphaNumeric(7)}`,
      display_name: `신고유형B_${RandomGenerator.alphabets(6)}`,
      description: "테스트 생성 B",
      active: false,
      created_at: now.toISOString() as string & tags.Format<"date-time">,
    },
  });
  typia.assert(typeB);

  // 2. Update type A's fields, check persist
  const updateInput: IDiscussionboardReportType.IUpdate = {
    code: `${typeA.code}_fix`,
    display_name: `${typeA.display_name} (수정됨)`,
    description: "관리자에 의해 설명이 수정됨.",
    active: false,
  };
  const updated = await api.functional.discussionboard.reportTypes.update(connection, {
    id: typeA.id,
    body: updateInput,
  });
  typia.assert(updated);
  TestValidator.equals("updated code")(updated.code)(updateInput.code);
  TestValidator.equals("updated display_name")(updated.display_name)(updateInput.display_name);
  TestValidator.equals("updated description")(updated.description)(updateInput.description);
  TestValidator.equals("updated active")(updated.active)(updateInput.active);

  // 3. Code uniqueness error: change typeA code to typeB code
  await TestValidator.error("duplicate code error")(() =>
    api.functional.discussionboard.reportTypes.update(connection, {
      id: typeA.id,
      body: { code: typeB.code } satisfies IDiscussionboardReportType.IUpdate,
    })
  );

  // 4.1: Non-existent id (should fail)
  await TestValidator.error("non-existent id error")(() =>
    api.functional.discussionboard.reportTypes.update(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { code: "nonexisttest" },
    })
  );

  // 4.2: Empty string code (should fail)
  await TestValidator.error("empty code error")(() =>
    api.functional.discussionboard.reportTypes.update(connection, {
      id: typeA.id,
      body: { code: "" },
    })
  );
  // 4.3: Empty string display_name (should fail)
  await TestValidator.error("empty display_name error")(() =>
    api.functional.discussionboard.reportTypes.update(connection, {
      id: typeA.id,
      body: { display_name: "" },
    })
  );

  // 5. Deactivate, then re-activate and verify
  const deactivated = await api.functional.discussionboard.reportTypes.update(connection, {
    id: typeA.id,
    body: { active: false },
  });
  typia.assert(deactivated);
  TestValidator.equals("deactivated")(deactivated.active)(false);

  const reactivated = await api.functional.discussionboard.reportTypes.update(connection, {
    id: typeA.id,
    body: { active: true },
  });
  typia.assert(reactivated);
  TestValidator.equals("reactivated")(reactivated.active)(true);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardReport";
import type { IDiscussionboardReportType } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardReportType";

/**
 * Test deleting a discussion board report type by id, including error cases and FK logic.
 *
 * Business context:
 * Moderation report types (e.g. 'spam', 'abuse') categorize user/content reports. Their deletion must be admin-restricted, respect referential integrity, and handle logic if types are in use.
 *
 * This E2E test ensures:
 * 1. A newly created report type can be deleted by id using the admin API, and is actually removed (repeat delete results in error).
 * 2. Deleting a random non-existent id gives a not found error.
 * 3. Attempting to delete a report type that is referenced by a report gives a FK constraint/cascading error as per DB policy.
 * 4. Only API-exposed admin context is used, as no user switching/auth APIs are provided.
 *
 * Steps:
 * 1. Create a report type for successful deletion scenario.
 * 2. Delete the report type; confirm it's deleted via repeated delete (get error).
 * 3. Try deleting a random UUID; expect not found error.
 * 4. Create another report type, create a report referencing it, then try to delete the in-use type; expect FK/cascading error.
 */
export async function test_api_discussionboard_test_delete_report_type_valid_not_found_and_foreign_key(
  connection: api.IConnection
) {
  // 1. Create a report type (for deletion)
  const reportTypeToRemove = await api.functional.discussionboard.reportTypes.create(connection, {
    body: {
      code: RandomGenerator.alphabets(8),
      display_name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.content()()(),
      active: true,
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(reportTypeToRemove);

  // 2. Delete the report type (should succeed)
  await api.functional.discussionboard.reportTypes.erase(connection, { id: reportTypeToRemove.id });
  // Try deleting again: Should fail (not found)
  await TestValidator.error("Delete already deleted report type should fail")(() =>
    api.functional.discussionboard.reportTypes.erase(connection, { id: reportTypeToRemove.id }),
  );

  // 3. Attempt to delete a random/non-existent id (should fail)
  await TestValidator.error("Delete with non-existent UUID should fail")(() =>
    api.functional.discussionboard.reportTypes.erase(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    }),
  );

  // 4. Create a second report type (to be referenced)
  const reportTypeWithFK = await api.functional.discussionboard.reportTypes.create(connection, {
    body: {
      code: RandomGenerator.alphabets(8),
      display_name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.content()()(),
      active: true,
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(reportTypeWithFK);

  // Create a report that references the created type
  const report = await api.functional.discussionboard.reports.create(connection, {
    body: {
      discussionboard_report_type_id: reportTypeWithFK.id,
      reporting_member_id: typia.random<string & tags.Format<"uuid">>(),
      target_object_id: typia.random<string & tags.Format<"uuid">>(),
      target_object_type: RandomGenerator.pick(["post", "comment", "member"]),
      report_description: RandomGenerator.paragraph()(1),
      reported_at: new Date().toISOString(),
    },
  });
  typia.assert(report);

  // 5. Attempt to delete referenced type (should fail by FK error/cascading rule)
  await TestValidator.error("FK-referenced report type delete should fail or error as per schema")(() =>
    api.functional.discussionboard.reportTypes.erase(connection, { id: reportTypeWithFK.id }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
