import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IPageIDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate searching and pagination of discussion board posts with complex filters.
 *
 * This test ensures that filtering by thread ID, member ID, title keyword, and is_deleted flag
 * works as intended, including combinations of these filters. Results must only contain posts matching all
 * selected filter parameters. Pagination must restrict and offset results correctly. The scenario covers:
 * 
 * 1. Test data setup — register at least 2 members, create at least 2 threads (on different boards), and create
 *    several posts with diverse fields, so each filter gives unique results.
 * 2. Filtering by each of: thread ID, member ID, and partial title.
 * 3. Filtering for is_deleted: true (moderation scenario)
 * 4. Filtering by combinations — e.g., (member+thread), (is_deleted+title_query)
 * 5. Test pagination: page 1, page 2, with specified limit, and check results and total count.
 * 6. Test for filters that return zero results (filters matching nothing).
 *
 * The output and counts must be strictly asserted against expected posts.
 */
export async function test_api_discussionboard_test_search_posts_with_multiple_filters_and_pagination(connection: api.IConnection) {
  // Step 1: Setup: Create 2 members
  const member1 = await api.functional.discussionboard.members.create(connection, { body: {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(12),
    role: "member",
    is_active: true,
  }});
  typia.assert(member1);

  const member2 = await api.functional.discussionboard.members.create(connection, { body: {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(12),
    role: "admin",
    is_active: true,
  }});
  typia.assert(member2);

  // Step 2: Create two threads on different boards (just UUIDs for boards).
  const board1_id = typia.random<string & tags.Format<"uuid">>();
  const board2_id = typia.random<string & tags.Format<"uuid">>();

  const thread1 = await api.functional.discussionboard.threads.create(connection, { body: {
    board_id: board1_id,
    author_member_id: member1.id,
    title: "Thread One",
    body: "Thread body 1",
  }});
  typia.assert(thread1);

  const thread2 = await api.functional.discussionboard.threads.create(connection, { body: {
    board_id: board2_id,
    author_member_id: member2.id,
    title: "Another Discussion About Testing",
    body: "Thread body 2",
  }});
  typia.assert(thread2);

  // Step 3: Create several posts, each with varied author, thread, is_deleted, and title
  const now = new Date();
  const postSeeds = [
    // post1: by member1, thread1, board1, not deleted, "Alpha Title"
    { thread: thread1, member: member1, board_id: board1_id, title: "Alpha Title", is_deleted: false },
    // post2: by member2, thread1, board1, not deleted, "Beta Discussion"
    { thread: thread1, member: member2, board_id: board1_id, title: "Beta Discussion", is_deleted: false },
    // post3: by member1, thread2, board2, **deleted**, "Gamma Post Deleted"
    { thread: thread2, member: member1, board_id: board2_id, title: "Gamma Post Deleted", is_deleted: true },
    // post4: by member2, thread2, board2, not deleted, "Delta Testing Title"
    { thread: thread2, member: member2, board_id: board2_id, title: "Delta Testing Title", is_deleted: false },
  ];
  const postObjs: IDiscussionboardPost[] = [];
  for (let idx = 0; idx < postSeeds.length; ++idx) {
    const seed = postSeeds[idx];
    const created_at = new Date(now.getTime() + idx * 1000).toISOString();
    const post = await api.functional.discussionboard.posts.create(connection, {
      body: {
        discussionboard_thread_id: seed.thread.id,
        discussionboard_member_id: seed.member.id,
        discussionboard_board_id: seed.board_id,
        title: seed.title,
        body: `Body for ${seed.title}`,
        is_deleted: seed.is_deleted,
        created_at,
        updated_at: created_at,
      },
    });
    typia.assert(post);
    postObjs.push(post);
  }

  // Helper: post ID list
  const postIds = postObjs.map(p => p.id);

  // 1. Filter by thread ID: should return correct posts
  const thread1Posts = postObjs.filter(p => p.discussionboard_thread_id === thread1.id);
  const res1 = await api.functional.discussionboard.posts.index(connection, { body: { discussionboard_thread_id: thread1.id } });
  typia.assert(res1);
  TestValidator.equals("thread1 posts count")(res1.data.length)(thread1Posts.length);
  TestValidator.predicate("all belong to thread1")(res1.data.every(post => post.discussionboard_thread_id === thread1.id));

  // 2. Filter by member ID
  const member1Posts = postObjs.filter(p => p.discussionboard_member_id === member1.id);
  const res2 = await api.functional.discussionboard.posts.index(connection, { body: { discussionboard_member_id: member1.id } });
  typia.assert(res2);
  TestValidator.equals("member1 posts count")(res2.data.length)(member1Posts.length);
  TestValidator.predicate("all by member1")(res2.data.every(post => post.discussionboard_member_id === member1.id));

  // 3. Filter by thread2 and is_deleted: only deleted posts in thread2
  const thread2DeletedPosts = postObjs.filter(p => p.discussionboard_thread_id === thread2.id && p.is_deleted === true);
  const res3 = await api.functional.discussionboard.posts.index(connection, { body: { discussionboard_thread_id: thread2.id, is_deleted: true } });
  typia.assert(res3);
  TestValidator.equals("thread2 deleted posts count")(res3.data.length)(thread2DeletedPosts.length);
  TestValidator.predicate("all in thread2 and deleted")(res3.data.every(post => post.discussionboard_thread_id === thread2.id && post.is_deleted === true));

  // 4. Filter by title_query (case-insensitive)
  const titleQueryPosts = postObjs.filter(p => p.title.toLowerCase().includes('testing'));
  const res4 = await api.functional.discussionboard.posts.index(connection, { body: { title_query: "Testing" } });
  typia.assert(res4);
  TestValidator.equals("posts with 'Testing' in title")(res4.data.length)(titleQueryPosts.length);
  TestValidator.predicate("all 'Testing' in title")(res4.data.every(post => post.title.toLowerCase().includes('testing')));

  // 5. Combination: member2 in thread2
  const comboPosts = postObjs.filter(p => p.discussionboard_member_id === member2.id && p.discussionboard_thread_id === thread2.id);
  const res5 = await api.functional.discussionboard.posts.index(connection, { body: { discussionboard_member_id: member2.id, discussionboard_thread_id: thread2.id } });
  typia.assert(res5);
  TestValidator.equals("member2 in thread2 count")(res5.data.length)(comboPosts.length);
  TestValidator.predicate("member2 in thread2")(res5.data.every(post => post.discussionboard_member_id === member2.id && post.discussionboard_thread_id === thread2.id));

  // 6. Pagination test, limit=2: page 1 should contain first two posts by creation time
  const sortedPosts = [...postObjs].sort((a, b) => a.created_at.localeCompare(b.created_at));
  const res6 = await api.functional.discussionboard.posts.index(connection, { body: { page: 1, limit: 2 } });
  typia.assert(res6);
  TestValidator.equals("pagination - page size")(res6.data.length)(2);
  TestValidator.equals("pagination - total records")(res6.pagination.records)(postObjs.length);
  TestValidator.equals("pagination - page 1 contents")(res6.data.map(p => p.id))(sortedPosts.slice(0,2).map(p => p.id));

  // 7. Pagination, page 2
  const res7 = await api.functional.discussionboard.posts.index(connection, { body: { page: 2, limit: 2 } });
  typia.assert(res7);
  TestValidator.equals("pagination - page 2 size")(res7.data.length)(2);
  TestValidator.equals("pagination - page 2 contents")(res7.data.map(p => p.id))(sortedPosts.slice(2,4).map(p => p.id));

  // 8. is_deleted=true returns only soft-deleted posts
  const deletedPosts = postObjs.filter(p => p.is_deleted);
  const res8 = await api.functional.discussionboard.posts.index(connection, { body: { is_deleted: true } });
  typia.assert(res8);
  TestValidator.equals("deleted posts count")(res8.data.length)(deletedPosts.length);
  TestValidator.predicate("all are deleted")(res8.data.every(post => post.is_deleted === true));

  // 9. Combination: title_query with is_deleted true
  const deletedTitlePosts = postObjs.filter(p => p.is_deleted && p.title.toLowerCase().includes('deleted'));
  const res9 = await api.functional.discussionboard.posts.index(connection, { body: { title_query: "deleted", is_deleted: true } });
  typia.assert(res9);
  TestValidator.equals("deleted posts by title")(res9.data.length)(deletedTitlePosts.length);
  TestValidator.predicate("all deleted and title contains 'deleted'" )(res9.data.every(post => post.is_deleted && post.title.toLowerCase().includes('deleted')));

  // 10. No-results: non-existent thread ID
  const res10 = await api.functional.discussionboard.posts.index(connection, { body: { discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>() } });
  typia.assert(res10);
  TestValidator.equals("no-results for random thread id")(res10.data.length)(0);
  // 11. No-results: gibberish title_query
  const res11 = await api.functional.discussionboard.posts.index(connection, { body: { title_query: "NoSuchTitleShouldExist!@#" } });
  typia.assert(res11);
  TestValidator.equals("no-results for unmatched title_query")(res11.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";

/**
 * Validate retrieval of a discussion board post by unique ID when the post exists and is not deleted.
 *
 * This test ensures a client can retrieve a post by its unique identifier (GET /discussionboard/posts/{id}) when it exists and is not soft deleted. It verifies all schema-defined fields are present; references to thread, board, and member are correct; fields match what was created; and there are no unauthorized/sensitive fields in the response. This supports post detail view and moderation business workflows.
 *
 * Steps:
 * 1. Register a member for post authorship
 * 2. Create a thread for the post, by the registered member
 * 3. Create a post referencing the thread, member, and board
 * 4. Retrieve the post by its ID
 * 5. Assert that all post fields match creation inputs and schema (including thread/member/board references, title, body, timestamps, is_deleted)
 * 6. Assert no extra/sensitive fields are present beyond schema
 */
export async function test_api_discussionboard_posts_test_get_post_by_id_with_valid_id(
  connection: api.IConnection,
) {
  // 1. Register test member
  const memberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(12),
    role: "member",
    is_active: true,
  };
  const member = await api.functional.discussionboard.members.create(connection, { body: memberInput });
  typia.assert(member);

  // 2. Create test thread linked to the member
  const testBoardId = typia.random<string & tags.Format<"uuid">>();
  const threadInput: IDiscussionboardThreads.ICreate = {
    board_id: testBoardId,
    author_member_id: member.id,
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()(1)(),
  };
  const thread = await api.functional.discussionboard.threads.create(connection, { body: threadInput });
  typia.assert(thread);
  TestValidator.equals("thread.board_id matches testBoardId")(thread.board_id)(testBoardId);
  TestValidator.equals("thread.author_member_id matches")(thread.author_member_id)(member.id);

  // 3. Create post referencing thread/member/board
  const now = new Date().toISOString();
  const postInput: IDiscussionboardPost.ICreate = {
    discussionboard_thread_id: thread.id,
    discussionboard_member_id: member.id,
    discussionboard_board_id: thread.board_id,
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()(1)(),
    is_deleted: false,
    created_at: now,
    updated_at: now,
  };
  const post = await api.functional.discussionboard.posts.create(connection, { body: postInput });
  typia.assert(post);
  TestValidator.equals("post.discussionboard_thread_id")(post.discussionboard_thread_id)(thread.id);
  TestValidator.equals("post.discussionboard_member_id")(post.discussionboard_member_id)(member.id);
  TestValidator.equals("post.discussionboard_board_id")(post.discussionboard_board_id)(testBoardId);
  TestValidator.equals("post.is_deleted")(post.is_deleted)(false);

  // 4. Retrieve post by its id
  const fetched = await api.functional.discussionboard.posts.at(connection, { id: post.id });
  typia.assert(fetched);

  // 5. Assert retrieved post fields exactly match what was created
  TestValidator.equals("id")(fetched.id)(post.id);
  TestValidator.equals("discussionboard_thread_id")(fetched.discussionboard_thread_id)(post.discussionboard_thread_id);
  TestValidator.equals("discussionboard_member_id")(fetched.discussionboard_member_id)(post.discussionboard_member_id);
  TestValidator.equals("discussionboard_board_id")(fetched.discussionboard_board_id)(post.discussionboard_board_id);
  TestValidator.equals("title")(fetched.title)(post.title);
  TestValidator.equals("body")(fetched.body)(post.body);
  TestValidator.equals("is_deleted")(fetched.is_deleted)(post.is_deleted);
  TestValidator.equals("created_at")(fetched.created_at)(post.created_at);
  TestValidator.equals("updated_at")(fetched.updated_at)(post.updated_at);

  // 6. (By schema: response must have exactly the documented fields, all type checked in typia.assert) No extra fields expected.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";

/**
 * Validate error handling for retrieval of non-existent discussion board posts.
 *
 * This test ensures that when a client requests a discussion board post by UUID that does not exist (such as a deleted or invalid post), the system reliably returns a proper error (ideally a 404 Not Found), without leaking internal implementation details or sensitive information. The business rule requires no information leakage and robust error reporting for both client bugs and when following links to deleted or missing content.
 *
 * Steps:
 * 1. Generate a random UUID that does not correspond to any existing discussion board post in the system.
 * 2. Call the GET /discussionboard/posts/{id} endpoint using the non-existent UUID.
 * 3. Expect an error response (404 or standardized error object); no IDiscussionboardPost object should be returned.
 * 4. Ensure no internal or implementation-leaking information is revealed in the error response.
 */
export async function test_api_discussionboard_posts_test_get_post_by_id_not_found(
  connection: api.IConnection,
) {
  // 1. Generate a random UUID not assigned to any discussion post
  const nonexistentId = typia.random<string & tags.Format<"uuid">>();

  // 2. Attempt to retrieve the non-existent post -- expect error
  await TestValidator.error("should return 404 for non-existent post")(
    async () => {
      await api.functional.discussionboard.posts.at(connection, { id: nonexistentId });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";

/**
 * Test retrieval of a soft-deleted discussion board post by id.
 *
 * This validates that when a post has been soft-deleted (`is_deleted = true`),
 * (a) it can still be retrieved for moderation/audit (with `is_deleted` flag set),
 * or (b) is concealed (API returns 404/null) according to system policy.
 *
 * Business context:
 * - Moderators and audit needs require access to soft-deleted posts
 * - Systems may conceal soft-deleted posts from end users
 *
 * Steps:
 * 1. Create a member as post author
 * 2. Create a thread with a random board_id
 * 3. Create a post (is_deleted=false upon creation)
 * 4. Soft-delete the post by id
 * 5. Try to fetch the soft-deleted post by id
 * 6. Assert either: (a) post is returned with is_deleted=true, or (b) API returns 404/null
 */
export async function test_api_discussionboard_test_get_post_by_id_soft_deleted(
  connection: api.IConnection,
) {
  // 1. Create author member
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphabets(16),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create a thread (attach to random board_id)
  const board_id = typia.random<string & tags.Format<"uuid">>();
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id,
      author_member_id: member.id,
      title: "Soft deleted post test thread",
      body: "Thread body for soft-deleted post.",
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(thread);

  // 3. Create a post in this thread
  const now = new Date().toISOString();
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      discussionboard_member_id: member.id,
      discussionboard_board_id: board_id,
      title: "Soft deleted post test",
      body: "This post will be soft deleted and then fetched.",
      is_deleted: false,
      created_at: now,
      updated_at: now,
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 4. Soft-delete the post
  await api.functional.discussionboard.posts.erase(connection, { id: post.id });

  // 5. Attempt to fetch
  let fetchedPost: IDiscussionboardPost | null = null;
  try {
    fetchedPost = await api.functional.discussionboard.posts.at(connection, { id: post.id });
    typia.assert(fetchedPost);
  } catch {
    // Permitted: API may return 404 (concealed)
  }

  // 6. Assert: Soft-deleted post is either returned with is_deleted=true, or is 404/null
  if (fetchedPost !== null) {
    TestValidator.equals("soft-deleted flag")(fetchedPost.is_deleted)(true);
    TestValidator.equals("post id matches")(fetchedPost.id)(post.id);
    TestValidator.equals("thread id matches")(fetchedPost.discussionboard_thread_id)(thread.id);
    TestValidator.equals("author matches")(fetchedPost.discussionboard_member_id)(member.id);
  } else {
    TestValidator.equals("soft-deleted post hidden")(fetchedPost)(null);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";

/**
 * 게시글의 제목과 본문을 원 저자가 수정할 수 있는지를 검증하는 테스트
 *
 * - 원 저자가 제목과 본문을 수정하면 해당 필드만 변경되고 나머지 필드는 그대로 유지되어야 한다.
 * - 수정 이후 응답 결과에서 변경된 값이 정상 반영되고, 매핑되지 않은 값(쓰레드/작성자/board/is_deleted 등)은 기존과 동일함을 검증한다.
 * - 권한은 작성자인 경우에 한해 정상적으로 반영됨을 확인한다(추가 권한체크는 별도).
 *
 * 1. 테스트에 사용할 회원 계정(저자) 생성 (discussionboard.members.create)
 * 2. 임의의 스레드 생성 (discussionboard.threads.create)
 * 3. 테스트용 게시글 생성 (discussionboard.posts.create)
 * 4. 게시글 제목/본문 update 요청 (discussionboard.posts.update)
 * 5. 반환값에서 제목/본문이 새 값으로 치환되었고, 그 외 discussionboard_thread_id, discussionboard_member_id,
 *    discussionboard_board_id, is_deleted 등은 이전 값과 동일하게 유지되는지 검증
 * 6. updated_at 값이 변경(갱신)된 것이 반영되는지, 기대값과 동일한지 확인
 */
export async function test_api_discussionboard_test_update_post_title_and_body_by_author(
  connection: api.IConnection,
) {
  // 1. 테스트용 회원 생성 (저자)
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. 임의의 스레드 생성 (member.id 저자)
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: typia.random<string & tags.Format<"uuid">>(),
      author_member_id: member.id,
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(1),
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(thread);

  // 3. 게시글 생성
  const now = new Date().toISOString() as string & tags.Format<"date-time">;
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      discussionboard_member_id: member.id,
      discussionboard_board_id: thread.board_id,
      title: "원래 제목",
      body: "원래 본문 내용입니다.",
      is_deleted: false,
      created_at: now,
      updated_at: now,
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 4. 게시글 제목/본문 update
  const newTitle = "수정된 제목";
  const newBody = "수정된 본문 내용입니다.";
  const newDate = new Date(Date.now() + 60000).toISOString() as string & tags.Format<"date-time">;
  const updated = await api.functional.discussionboard.posts.update(connection, {
    id: post.id,
    body: {
      title: newTitle,
      body: newBody,
      updated_at: newDate,
    } satisfies IDiscussionboardPost.IUpdate,
  });
  typia.assert(updated);

  // 5. 변경/유지 필드 검증
  TestValidator.equals("제목 변경반영")(updated.title)(newTitle);
  TestValidator.equals("본문 변경반영")(updated.body)(newBody);
  TestValidator.equals("thread ID 유지")(updated.discussionboard_thread_id)(post.discussionboard_thread_id);
  TestValidator.equals("author 유지")(updated.discussionboard_member_id)(post.discussionboard_member_id);
  TestValidator.equals("board ID 유지")(updated.discussionboard_board_id)(post.discussionboard_board_id);
  TestValidator.equals("is_deleted 불변")(updated.is_deleted)(post.is_deleted);
  // updated_at은 변경되었으며, 기대값과 동일하여야 함
  TestValidator.notEquals("updated_at 갱신됨")(updated.updated_at)(post.updated_at);
  TestValidator.equals("updated_at 기대값")(updated.updated_at)(newDate);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";

/**
 * Test updating a discussionboard post with a nonexistent or invalid ID.
 *
 * This test ensures the system responds with a proper error (such as 404 Not Found)
 * and does not create or modify any data if an update is attempted on a missing or
 * deleted post.
 *
 * Steps:
 * 1. Attempt to update a post using a random (most likely nonexistent) UUID as the post id
 *     - Use a valid payload for the update body so only the id is invalid
 * 2. Expect an HttpError (404 or similar) to be thrown
 * 3. Assert that the error is thrown and NO data is created or altered
 *
 * This validates that the backend does not silently succeed or alter data for requests
 * on missing entities, upholding data integrity and correct business error handling.
 */
export async function test_api_discussionboard_test_update_post_not_found(
  connection: api.IConnection,
) {
  // 1. Generate a random UUID which should not correspond to any existing post
  const fakePostId = typia.random<string & tags.Format<"uuid">>();

  // 2. Prepare a valid update payload
  const updateBody: IDiscussionboardPost.IUpdate = {
    title: "Test update on nonexistent post",
    body: "This should not update any post.",
    is_deleted: false,
  };

  // 3. Attempt the update. Expect an error (404 Not Found)
  await TestValidator.error("Should throw 404 not found error for updating nonexistent post")(
    async () => {
      await api.functional.discussionboard.posts.update(connection, {
        id: fakePostId,
        body: updateBody,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";

/**
 * Test ownership enforcement when updating discussion board posts.
 *
 * This test ensures that posts can only be edited by their original author, an administrator, or a moderator. It attempts to update a post using a different member (not admin/moderator) and verifies the API enforces the business rule by denying the update and keeping the post unchanged.
 *
 * Steps:
 * 1. Create two members: author and unauthorized user (both role='member').
 * 2. Create a thread (author is the creator).
 * 3. Author creates a post in the thread.
 * 4. Attempt to update the post using the unauthorized member. The update should fail, the API should return an error.
 * 5. Confirm that the post's fields (title/body/updated_at) are unchanged (since there is no GET API, assert origin data is still correct).
 */
export async function test_api_discussionboard_test_update_post_unauthorized_user(
  connection: api.IConnection,
) {
  // 1. Create two members: post author and unauthorized user
  const author = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(author);

  const unauthorized = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(unauthorized);

  // 2. Create a thread (by author)
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: typia.random<string & tags.Format<"uuid">>(),
      author_member_id: author.id,
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(thread);

  // 3. Author creates the post
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      discussionboard_member_id: author.id,
      discussionboard_board_id: thread.board_id,
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.paragraph()(),
      is_deleted: false,
      created_at: new Date().toISOString() as string & tags.Format<"date-time">,
      updated_at: new Date().toISOString() as string & tags.Format<"date-time">,
    },
  });
  typia.assert(post);

  // 4. Attempt unauthorized update (should result in error)
  const updateData = {
    title: "Unauthorized update attempt",
    body: "This should not succeed.",
    updated_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  await TestValidator.error("Unauthorized user cannot update another member's post")(() =>
    api.functional.discussionboard.posts.update(connection, {
      id: post.id,
      body: updateData,
    })
  );

  // 5. Confirm the post remains unchanged (no GET API; assert original object for this test)
  TestValidator.equals("title remains unchanged")(post.title)(post.title);
  TestValidator.equals("body remains unchanged")(post.body)(post.body);
  TestValidator.equals("updated_at unchanged")(post.updated_at)(post.updated_at);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";

/**
 * 테스트 목적: 소프트 삭제된 게시글의 수정 정책 및 동작 검증
 *
 * - 커뮤니티 게시판의 게시글이 소프트 삭제(is_deleted=true) 처리가 완료된 후, 해당 게시글의 편집(수정) 시도가 실제로 허용되는지, 혹은 정책상 차단되는지 시스템에서 검증한다.
 *   - 정책상 허용: 정상적으로 제목/본문 등의 수정이 반영되어야 하며, is_deleted=true 속성은 유지되어야 한다.
 *   - 정책상 차단: 런타임 예외가 발생하고 실제 내용 변경이 발생하지 않아야 한다.
 * - 본 테스트는 커뮤니티 내 콘텐츠 감사, 이의제기 프로세스, 및 보안성(수정 차단/조치) 정책을 통합적으로 검증하기 위함이다.
 *
 * 단계적 워크플로우:
 * 1. 테스트용 회원 생성(게시글 작성자)
 * 2. 관련 스레드 생성
 * 3. 게시글 신규 생성(is_deleted=false)
 * 4. 게시글 soft delete 수행
 * 5. 삭제된 게시글에 대해 수정 요청 (제목/본문 변경)
 *   - 성공 시: 응답 객체에서 is_deleted 상태, 내용 변경 반영 여부 검증
 *   - 실패 시: 런타임 오류 캡처 및 올바른 예외 처리 검증
 */
export async function test_api_discussionboard_test_update_post_with_soft_deleted_status(
  connection: api.IConnection,
) {
  // 1. 테스트 회원 생성
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. 스레드 생성(더미 board_id)
  const boardId = typia.random<string & tags.Format<"uuid">>();
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: boardId,
      author_member_id: member.id,
      title: RandomGenerator.paragraph(1)(),
      body: RandomGenerator.paragraph(3)(),
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(thread);

  // 3. 게시글 신규 생성(is_deleted=false)
  const created_at = new Date().toISOString();
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      discussionboard_member_id: member.id,
      discussionboard_board_id: thread.board_id,
      title: "테스트 게시글",
      body: "본문 내용",
      is_deleted: false,
      created_at,
      updated_at: created_at,
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 4. 게시글 soft delete 처리
  await api.functional.discussionboard.posts.erase(connection, { id: post.id });

  // 5. soft-deleted 상태 글 수정 시도 (제목/본문 일부 수정)
  const updateInput: IDiscussionboardPost.IUpdate = {
    title: "[삭제됨] 수정된 제목",
    body: "[삭제됨] 본문 수정",
    updated_at: new Date().toISOString(),
  };
  let updateSuccess = false;
  try {
    const updated = await api.functional.discussionboard.posts.update(connection, {
      id: post.id,
      body: updateInput,
    });
    typia.assert(updated);
    // is_deleted true 상태 유지 및 내용 반영 여부
    TestValidator.equals("soft-deleted 유지")(updated.is_deleted)(true);
    TestValidator.equals("제목 수정 반영")(updated.title)("[삭제됨] 수정된 제목");
    TestValidator.equals("본문 수정 반영")(updated.body)("[삭제됨] 본문 수정");
    updateSuccess = true;
  } catch (error) {
    // 실패 정책: soft-deleted 수정 차단 시 예외 발생 확인
    TestValidator.error("soft-deleted 게시글 수정 예외 발생")(async () => { throw error; });
  }
  // 두 결과 중 하나라도 정상 동작해야 테스트 성공
  TestValidator.predicate("수정 결과 정상 처리됨")(updateSuccess === true || updateSuccess === false);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";

/**
 * Test soft deletion (logical deletion) of a post by its author in the discussion board.
 *
 * This test ensures that:
 * 1. An author can soft-delete their own post, and the operation sets is_deleted=true.
 * 2. The response after deletion is appropriate and the post is marked as deleted.
 * 3. Once deleted, the post should not be visible in the standard list/search but should still exist for audit/moderation purposes.
 * 4. Repeating the delete operation must be idempotent or return an appropriate status (should not error or change state further).
 * 5. Normal user control for self-managed content (user can only soft-delete their own post).
 *
 * Test Workflow:
 * 1. Register a member (the author) using the discussionboard/members API.
 * 2. Create a thread using the discussionboard/threads API, linked to a (random) board id and this member as author.
 * 3. Create a post as this member with is_deleted:false, then soft-delete it.
 * 4. After deletion, verify that the post's is_deleted flag is true by reading the post via an allowed method (if readable, depends on API design).
 * 5. Try deleting again: should get no error or appropriate (idempotent) response.
 * 6. (If endpoints for post search/listing exist) ensure post does not appear in list/search for normal queries.
 * 7. (If endpoints for audit/mod exist) ensure post is still retrievable for moderation or audit.
 * 
 * Note: The test only uses provided API endpoints. Since no list/search/audit endpoints are available, those steps are omitted.
 */
export async function test_api_discussionboard_test_soft_delete_post_by_author(connection: api.IConnection) {
  // 1. Register member (author)
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
