/**
 * Validate creation of a post snapshot when a post is edited.
 *
 * Ensures that editing a post correctly triggers creation of a snapshot capturing
 * the state immediately before modification. Validates audit fields, roll-back
 * support, and compliance for content history.
 *
 * Steps:
 * 1. Register a discussion board member who will be the editing user
 * 2. Create a thread by this member (random board_id)
 * 3. Create a post (to be snapshotted before editing)
 * 4. Call the snapshot API with correct references, title/body/editor_member_id, and taken_at
 * 5. Assert snapshot contents and audit invariants (ids, taken_at, field match).
 */
export async function test_api_discussionboard_test_create_post_snapshot_on_post_edit(
  connection: api.IConnection,
) {
  // 1. Create a discussion board member (editor)
  const memberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(12),
    role: "member",
    is_active: true,
  };
  const member = await api.functional.discussionboard.members.create(connection, {
    body: memberInput,
  });
  typia.assert(member);

  // 2. Create a thread authored by the member
  const threadInput: IDiscussionboardThreads.ICreate = {
    board_id: typia.random<string & tags.Format<"uuid">>(),
    author_member_id: member.id,
    title: RandomGenerator.paragraph()(10),
    body: RandomGenerator.content()()(24),
  };
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: threadInput,
  });
  typia.assert(thread);

  // 3. Create a post under the thread
  const nowIso = new Date().toISOString();
  const postInput: IDiscussionboardPost.ICreate = {
    discussionboard_thread_id: thread.id,
    discussionboard_member_id: member.id,
    discussionboard_board_id: thread.board_id,
    title: RandomGenerator.paragraph()(8),
    body: RandomGenerator.content()()(36),
    is_deleted: false,
    created_at: nowIso,
    updated_at: nowIso,
  };
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: postInput,
  });
  typia.assert(post);

  // 4. Create a snapshot (pre-edit state)
  const snapshotInput: IPostSnapshot.ICreate = {
    discussionboard_post_id: post.id,
    editor_member_id: member.id,
    title: post.title,
    body: post.body,
    taken_at: new Date().toISOString(),
  };
