  TestValidator.equals("editor_member_id")(snapshot.editor_member_id)(member.id);
  TestValidator.equals("title")(snapshot.title)(post.title);
  TestValidator.equals("body")(snapshot.body)(post.body);
  TestValidator.equals("taken_at year-month-day")(
    snapshot.taken_at.slice(0, 10)
  )(snapshotInput.taken_at.slice(0, 10));
  TestValidator.predicate("snapshot id is uuid")(
    typeof snapshot.id === "string" && snapshot.id.length > 24
  );
}

