 * 3. Attempt to update A's key to B's value (duplicate) via update API.
 * 4. Confirm unique constraint violation is raised and update fails.
 *
 * This validates that the backend correctly rejects attempts to assign a key already present in another settings row.
 */
export async function test_api_discussionboard_settings_test_update_setting_key_to_duplicate_value(
