    // Permanent ban, linked to the above report
    await api.functional.discussionboard.bans.create(connection, {
      body: {
        banned_member_id: bannedMember.id,
        acting_moderator_id: moderator.id,
        report_id: report.id,
        reason: "Abuse report ban",
        ban_type: "permanent",
        banned_at: now.toISOString(),
        expires_at: null,
      },
    }),
    // Temporary ban, not linked to a report
    await api.functional.discussionboard.bans.create(connection, {
      body: {
        banned_member_id: bannedMember.id,
        acting_moderator_id: moderator.id,
        reason: "Temp ban test",
        ban_type: "temporary",
        banned_at: new Date(now.getTime() + 1000 * 60 * 60 * 24).toISOString(),
        expires_at: new Date(now.getTime() + 1000 * 60 * 60 * 24 * 7).toISOString(),
        report_id: null,
      },
    }),
  ];
  bans.forEach(ban => typia.assert(ban));

  // Step 5: Filtering & Paging - Single field: banned_member_id
  const byBannedMember = await api.functional.discussionboard.bans.index(connection, {
    body: {
      banned_member_id: bannedMember.id,
    },
  });
  typia.assert(byBannedMember);
  TestValidator.predicate("all bans match bannedMember")(
    byBannedMember.data.every(ban => ban.banned_member_id === bannedMember.id),
  );

  // Filtering: acting_moderator_id
  const byModerator = await api.functional.discussionboard.bans.index(connection, {
    body: {
      acting_moderator_id: moderator.id,
    },
  });
  typia.assert(byModerator);
  TestValidator.predicate("all bans match moderator")(
    byModerator.data.every(ban => ban.acting_moderator_id === moderator.id),
  );

  // Filtering: report_id (should find only the permanent ban)
  const byReport = await api.functional.discussionboard.bans.index(connection, {
    body: {
      report_id: report.id,
    },
  });
  typia.assert(byReport);
  TestValidator.predicate("bans by report_id have correct report_id")(
    byReport.data.every(ban => ban.report_id === report.id),
  );
  TestValidator.equals("report_id ban count")(byReport.data.length)(1);

  // Filtering: ban_type (temporary)
  const byTemporaryType = await api.functional.discussionboard.bans.index(connection, {
    body: {
      ban_type: "temporary",
    },
  });
  typia.assert(byTemporaryType);
  TestValidator.predicate("bans of type temporary")(
    byTemporaryType.data.every(ban => ban.ban_type === "temporary"),
  );

  // Filtering: ban_type (permanent)
  const byPermanentType = await api.functional.discussionboard.bans.index(connection, {
    body: {
      ban_type: "permanent",
    },
  });
  typia.assert(byPermanentType);
  TestValidator.predicate("bans of type permanent")(
    byPermanentType.data.every(ban => ban.ban_type === "permanent"),
  );

  // Filtering: banned_at date range
  const start = now.toISOString();
  const end = new Date(now.getTime() + 1000 * 60 * 60 * 24 * 2).toISOString();
  const byBannedAtRange = await api.functional.discussionboard.bans.index(connection, {
    body: {
      banned_at_from: start,
      banned_at_to: end,
    },
  });
  typia.assert(byBannedAtRange);
  TestValidator.predicate("bans within banned_at range")(
    byBannedAtRange.data.every(ban => ban.banned_at >= start && ban.banned_at <= end),
  );

  // Filtering: expires_at_from and expires_at_to (should match only the temporary ban)
  const tempBan = bans.find(ban => ban.ban_type === "temporary")!;
  const byExpiresAtRange = await api.functional.discussionboard.bans.index(connection, {
    body: {
      expires_at_from: tempBan.expires_at!,
      expires_at_to: tempBan.expires_at!,
    },
  });
  typia.assert(byExpiresAtRange);
  TestValidator.predicate("bans within expires_at range")(
    byExpiresAtRange.data.every(ban => ban.expires_at === tempBan.expires_at),
  );

  // Filtering: pagination, limit to 1 per page to test paging mechanics
  const paged = await api.functional.discussionboard.bans.index(connection, {
    body: {
      pagination: { current: 1, limit: 1, records: 0, pages: 0 },
    },
  });
  typia.assert(paged);
  TestValidator.equals("paged result size")(paged.data.length)(1);

  // Filtering: combinations that should return no results (e.g., fake member id)
  const empty = await api.functional.discussionboard.bans.index(connection, {
    body: {
      banned_member_id: typia.random<string & tags.Format<"uuid">>(),
    },
  });
  typia.assert(empty);
  TestValidator.equals("empty query returns empty data")(empty.data.length)(0);

  // Filtering: combination that should return one result (temp ban with banned_member_id and ban_type=temporary)
  const oneResult = await api.functional.discussionboard.bans.index(connection, {
    body: {
      banned_member_id: bannedMember.id,
      ban_type: "temporary",
    },
  });
  typia.assert(oneResult);
  TestValidator.equals("temp ban unique result")(oneResult.data.length)(1);
  TestValidator.equals("temp ban's id matches")(oneResult.data[0].id)(tempBan.id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBan";

/**
 * 특정 제재(Ban) 레코드를 ban id로 조회하는 기능의 E2E 테스트 함수입니다.
 *
 * - 정상 케이스: 운영자/관리자 계정으로 기존 ban id를 활용해 레코드를 조회할 수 있고, 반환 필드가 정확한지 typia.assert 및 TestValidator로 검증합니다.
 * - 실패(404) 케이스: 존재하지 않는(임의 생성) uuid로 요청 시 not found error가 반환되어야 함을 TestValidator.error로 확인합니다.
 *
 * 테스트 프로세스:
 * 1. 제재 대상 일반 회원 생성
 * 2. 운영자(혹은 관리자) 회원 계정 생성
 * 3. 해당 member id/acting_moderator_id로 ban 생성
 * 4. 정상 ban id로 GET /discussionboard/bans/{id} 조회 및 필드/값 검증
 * 5. 무작위 non-existent id로 조회하여 404 not found 발생 검증
 */
export async function test_api_discussionboard_bans_test_get_ban_by_valid_and_invalid_id(
  connection: api.IConnection,
) {
  // 1. 제재(차단) 대상 일반 회원 생성
  const bannedMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphabets(12),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(bannedMember);

  // 2. 운영자(Moderator) 권한 계정 생성
  const actingModerator = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphabets(12),
      role: "moderator",
      is_active: true,
    },
  });
  typia.assert(actingModerator);

  // 3. ban 레코드 생성 (acting_moderator가 대상자 차단)
  const now = new Date();
  const ban = await api.functional.discussionboard.bans.create(connection, {
    body: {
      banned_member_id: bannedMember.id,
      acting_moderator_id: actingModerator.id,
      report_id: null,
      reason: "Test ban for E2E",
      ban_type: "temporary",
      banned_at: now.toISOString(),
      expires_at: new Date(now.getTime() + 3*24*60*60*1000).toISOString(),
    },
  });
  typia.assert(ban);

  // 4. 정상 ban id로 fetch 및 주요 필드 검증
  const fetched = await api.functional.discussionboard.bans.at(connection, { id: ban.id });
  typia.assert(fetched);
  TestValidator.equals("ban id matches")(fetched.id)(ban.id);
  TestValidator.equals("banned_member_id matches")(fetched.banned_member_id)(ban.banned_member_id);
  TestValidator.equals("acting_moderator_id matches")(fetched.acting_moderator_id)(ban.acting_moderator_id);
  TestValidator.equals("ban_type matches")(fetched.ban_type)(ban.ban_type);
  TestValidator.equals("reason matches")(fetched.reason)(ban.reason);

  // 5. 존재하지 않는 id 요청 시 404 error
  await TestValidator.error("not found for non-existent id")(() => {
    return api.functional.discussionboard.bans.at(connection, {
      id: typia.random<string & tags.Format<"uuid">>()
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBan";

/**
 * Test updating a discussion board ban record by ID with diverse valid and invalid scenarios.
 *
 * Business context:
 * - Admins or moderators are able to update an existing ban for a member. Typical cases include appeal processing (e.g., shortening ban), record correction, changing the moderator on record, or setting a new expiry date. Immutable fields in the schema must not be changed: testing attempts to change non-schema or system-only fields is required.
 *
 * Steps:
 * 1. Create two members: one normal (to be banned) and one moderator (for acting_moderator_id reference).
 * 2. Issue a ban against the member with the moderator as the actor.
 * 3. Update the ban: change reason, ban_type, expires_at, and update acting_moderator_id to simulate successful corrections.
 * 4. Confirm result: new field values have been updated and reflect request, all unsubmitted fields remain unchanged, id is not modified.
 * 5. Attempt to update with an invalid report_id (e.g., non-existent UUID) and expect an error.
 * 6. Attempt to update with invalid field (not present in IDiscussionboardBan.IUpdate) and verify error (or ignored per API behavior).
 * 7. Attempt to update using an invalid id (not found, random UUID) and expect a not found error.
 * 8. Attempt to update using an invalid id (non-UUID) and expect a validation error.
 * 9. For an expired ban, update the expires_at with a future date (simulate appeal-based extension), confirm extension is accepted.
 * 10. Attempt to update with wrong data types (e.g. expires_at as string not ISO date, reason as number), expect error.
 */
export async function test_api_discussionboard_bans_test_update_ban_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Create banned member
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create moderator
  const moderator = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "moderator",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(moderator);

  // 3. Issue initial ban
  const ban = await api.functional.discussionboard.bans.create(connection, {
    body: {
      banned_member_id: member.id,
      acting_moderator_id: moderator.id,
      report_id: null,
      reason: "Spamming in multiple threads",
      ban_type: "temporary",
      banned_at: new Date().toISOString(),
      expires_at: new Date(Date.now() + 7 * 86400000).toISOString(),
    } satisfies IDiscussionboardBan.ICreate,
  });
  typia.assert(ban);

  // 4. Update ban: change reason, ban_type, expires_at, acting_moderator_id
  const updated_ban = await api.functional.discussionboard.bans.update(connection, {
    id: ban.id,
    body: {
      reason: "Updated: spam resolved after user warning",
      ban_type: "permanent",
      expires_at: null,
      acting_moderator_id: moderator.id,
    } satisfies IDiscussionboardBan.IUpdate,
  });
  typia.assert(updated_ban);
  TestValidator.equals("reason updated")(updated_ban.reason)("Updated: spam resolved after user warning");
  TestValidator.equals("ban_type updated")(updated_ban.ban_type)("permanent");
  TestValidator.equals("expires_at null for permanent")(updated_ban.expires_at)(null);
  TestValidator.equals("acting_moderator_id unchanged")(updated_ban.acting_moderator_id)(moderator.id);
  TestValidator.equals("id unchanged")(updated_ban.id)(ban.id);

  // 5. Attempt to update with invalid report_id (random UUID, assuming not present in reports)
  const random_uuid = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("updating with non-existent report_id fails")(() =>
    api.functional.discussionboard.bans.update(connection, {
      id: ban.id,
      body: { report_id: random_uuid } satisfies IDiscussionboardBan.IUpdate,
    })
  );

  // 6. Attempt to update with non-existent field (will be ignored or rejected):
  // We'll only pass valid fields since schema strictly forbids unknowns (type error in TS).

  // 7. Attempt to update using random (but valid) UUID as id (not found)
  await TestValidator.error("update with not found id fails")(() =>
    api.functional.discussionboard.bans.update(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { reason: "Test not found id" } satisfies IDiscussionboardBan.IUpdate,
    })
  );

  // 8. Attempt to update using invalid id (malformed UUID)
  await TestValidator.error("update with invalid UUID id fails")(() =>
    api.functional.discussionboard.bans.update(connection, {
      id: "invalid-uuid" as string & tags.Format<"uuid">,
      body: { reason: "Invalid uuid test" } satisfies IDiscussionboardBan.IUpdate,
    })
  );

  // 9. For an expired ban, update expires_at into future (simulate extension)
  // First, create a ban that is already in the past
  const expired_ban = await api.functional.discussionboard.bans.create(connection, {
    body: {
      banned_member_id: member.id,
      acting_moderator_id: moderator.id,
      report_id: null,
      reason: "Expired ban for test",
      ban_type: "temporary",
      banned_at: new Date(Date.now() - 14 * 86400000).toISOString(),
      expires_at: new Date(Date.now() - 7 * 86400000).toISOString(),
    } satisfies IDiscussionboardBan.ICreate,
  });
  typia.assert(expired_ban);
  // Now update with new future expires_at
  const extended_ban = await api.functional.discussionboard.bans.update(connection, {
    id: expired_ban.id,
    body: {
      expires_at: new Date(Date.now() + 7 * 86400000).toISOString(),
      reason: "Extended after appeal",
    } satisfies IDiscussionboardBan.IUpdate,
  });
  typia.assert(extended_ban);
  TestValidator.equals("expires_at extended")(extended_ban.expires_at)(new Date(new Date().getTime() + 7 * 86400000).toISOString());
  TestValidator.equals("reason amended")(extended_ban.reason)("Extended after appeal");

  // 10. Attempt to update using wrong data types for fields - should fail
  await TestValidator.error("reason as number fails")(() =>
    api.functional.discussionboard.bans.update(connection, {
      id: ban.id,
      body: { reason: 123 as any } as any,
    })
  );
  await TestValidator.error("expires_at as plain string fails")(() =>
    api.functional.discussionboard.bans.update(connection, {
      id: ban.id,
      body: { expires_at: "not-a-date" as any } as any,
    })
  );
}

