/**
 * 테스트: 신고 유형(reportTypes) 생성, 중복 및 유효성·권한 검사
 *
 * 이 테스트는 다음 시나리오를 검증합니다:
 * 1. 올바른 필드로 신규 신고유형을 생성할 수 있다.
 * 2. code/display_name 값이 중복되면 생성이 거부된다.
 * 3. 필수 입력 필드가 누락되면 유효성 검사에 실패한다.
 * 4. (부분) 관리자 권한이 아닌 경우 요청 실패(단, 실제 role test는 별도 인증 흐름 필요하므로 스킵)
 *
 * 상세 단계:
 * 1. 정상 생성: 모든 필드를 채워 신규 신고유형 record를 생성한다. DB의 반환값이 입력값과 일치하는지 검증한다.
 * 2. 중복 code: 같은 code, 다른 display_name으로 생성시 에러를 기대한다.
 * 3. 중복 display_name: 다른 code, 같은 display_name으로 생성시 에러를 기대한다.
 * 4. 누락 필드: 필수필드(code, display_name, active) 누락시 각각 데이터 유효성 검사 실패를 기대한다. (주의: TS type 에러로 인해 as any hack 사용, 실제 실행환경에 따라 예외처리 가능성 다름)
 * 5. (권한) 관리자 권한없이 접근시 실패(별도 인증 API 미제공으로 여기선 문서화만 함)
 */
export async function test_api_discussionboard_reportTypes_create(
  connection: api.IConnection,
) {
  // 1. 정상 생성
  const now = new Date().toISOString();
  const createRequest = {
    code: `test_code_${RandomGenerator.alphaNumeric(6)}`,
    display_name: `테스트 신고유형 ${RandomGenerator.alphabets(4)}`,
    description: "자동 신고유형 테스트 설명입니다.",
    active: true,
    created_at: now,
  } satisfies IDiscussionboardReportType.ICreate;
  const created = await api.functional.discussionboard.reportTypes.create(connection, { body: createRequest });
  typia.assert(created);
  TestValidator.equals("code 생성값 일치")(created.code)(createRequest.code);
  TestValidator.equals("display_name 생성값 일치")(created.display_name)(createRequest.display_name);
  TestValidator.equals("description 생성값 일치")(created.description)(createRequest.description);
  TestValidator.equals("active 생성값 일치")(created.active)(createRequest.active);

  // 2. 중복 code로 생성 시도 (display_name만 다름)
  await TestValidator.error("중복 code는 에러 처리되어야 한다")(() =>
    api.functional.discussionboard.reportTypes.create(connection, {
      body: {
        ...createRequest,
        display_name: `다른이름${RandomGenerator.alphabets(5)}`,
      },
    })
  );

  // 3. 중복 display_name로 생성 시도 (code만 다름)
  await TestValidator.error("중복 display_name은 에러 처리되어야 한다")(() =>
    api.functional.discussionboard.reportTypes.create(connection, {
      body: {
        ...createRequest,
        code: `unique_code_${RandomGenerator.alphaNumeric(7)}`,
      },
    })
  );

  // 4. 필수 입력 필드 누락 케이스 → 각 필수값 미포함 시 에러 확인
  await TestValidator.error("code 누락 시 유효성 검사 실패")(() =>
    api.functional.discussionboard.reportTypes.create(connection, {
      body: {
        // code 미포함
        display_name: `Missing Code Name ${RandomGenerator.alphabets(6)}`,
        active: true,
        created_at: new Date().toISOString(),
      } as any, // 타입 위반 intentional
    })
  );
  await TestValidator.error("display_name 누락 시 유효성 검사 실패")(() =>
    api.functional.discussionboard.reportTypes.create(connection, {
      body: {
        code: `missing_dn_${RandomGenerator.alphaNumeric(6)}`,
        // display_name 미포함
        active: true,
        created_at: new Date().toISOString(),
      } as any,
    })
  );
  await TestValidator.error("active 누락 시 유효성 검사 실패")(() =>
    api.functional.discussionboard.reportTypes.create(connection, {
      body: {
        code: `missing_active_${RandomGenerator.alphaNumeric(6)}`,
        display_name: `No Active Name ${RandomGenerator.alphabets(8)}`,
        // active 미포함
        created_at: new Date().toISOString(),
      } as any,
    })
  );
  // created_at 누락 케이스는 생성 시 자동 입력 정책 가능성 상 실제 API 관점에서 옵션일 수 있으므로 별도 테스트 제외.

  // 5. 관리자 권한 없는 호출은 skip (별도 인증 API 미제공됨)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IPageIComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Verify searching and paginating comments with schema-allowed filters, including by post, member, content substring, and proper pagination.
 *
 * This test ensures the /discussionboard/comments PATCH endpoint correctly applies allowed filters and returns paginated results, enforcing schema-only request and response properties.
 *
 * Steps:
 * 1. Prepare mock member UUIDs and relationship IDs for associating comments and posts.
 * 2. Create two posts by different members.
 * 3. Add several comments (from different members; on different posts).
 * 4. Test comment listing (index) with no filters – verify all created comments present, pagination metadata is correct.
 * 5. Test filtering by post: only comments for that post are returned.
 * 6. Test filtering by member: only comments by that member are returned.
 * 7. Test comment body substring search: filter by substring and ensure all results match.
 * 8. Confirm that only schema-defined filter fields are used in the request (and API enforces this).
 * 9. Ensure all responses conform to IPageIComment schema.
 */
export async function test_api_discussionboard_test_search_comments_with_valid_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Prepare two mock members and relationship IDs (in real-use, members would be created; here use random uuids)
  const memberA: string = typia.random<string & tags.Format<"uuid">>();
  const memberB: string = typia.random<string & tags.Format<"uuid">>();
  const boardId: string = typia.random<string & tags.Format<"uuid">>();
  const threadAId: string = typia.random<string & tags.Format<"uuid">>();
  const threadBId: string = typia.random<string & tags.Format<"uuid">>();

  // 2. Create two posts by different members
  const postA = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: threadAId,
      discussionboard_member_id: memberA,
      discussionboard_board_id: boardId,
      title: "First post title",
      body: "Hello World. Post A.",
      is_deleted: false,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(postA);
  const postB = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: threadBId,
      discussionboard_member_id: memberB,
      discussionboard_board_id: boardId,
      title: "Second post title",
      body: "Greetings from Post B.",
      is_deleted: false,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(postB);

  // 3. Add comments to posts: some overlap in members and posts for filter coverage
  const comments: IComment[] = [];
  const commentEntities = [
    // Post A
    { post: postA, member: memberA, body: "Nice article!" },
    { post: postA, member: memberB, body: "Thanks for sharing" },
    { post: postA, member: memberA, body: "+1 Great" },
    // Post B
    { post: postB, member: memberB, body: "Interesting thoughts." },
    { post: postB, member: memberA, body: "Useful information!" },
  ];
  for (const entry of commentEntities) {
    const comment = await api.functional.discussionboard.comments.create(connection, {
      body: {
        discussionboard_post_id: entry.post.id,
        discussionboard_member_id: entry.member,
        body: entry.body,
      } satisfies IComment.ICreate,
    });
    typia.assert(comment);
    comments.push(comment);
  }

  // 4. List all comments, no filters; result contains all our created comments
  let pageAll = await api.functional.discussionboard.comments.index(connection, {
    body: {}, // no filters
  });
  typia.assert(pageAll);
  for (const c of comments) {
    TestValidator.predicate("comment should be present in all-list")(pageAll.data.some((v) => v.id === c.id));
  }
  TestValidator.predicate("pagination structure present")(!!pageAll.pagination && typeof pageAll.pagination.current === "number");

  // 5. Filter by post: only comments for that post
  let pagePostA = await api.functional.discussionboard.comments.index(connection, {
    body: { discussionboard_post_id: postA.id },
  });
  typia.assert(pagePostA);
  TestValidator.equals("only postA comments returned")(pagePostA.data.map((x) => x.id).sort())(comments.filter((c) => c.discussionboard_post_id === postA.id).map((x) => x.id).sort());

  // 6. Filter by member: only comments by that member
  let pageMemberA = await api.functional.discussionboard.comments.index(connection, {
    body: { discussionboard_member_id: memberA },
  });
  typia.assert(pageMemberA);
  TestValidator.equals("only memberA comments returned")(pageMemberA.data.map((x) => x.id).sort())(comments.filter((c) => c.discussionboard_member_id === memberA).map((x) => x.id).sort());

  // 7. Filter by substring in body; restrict to those with substring
  let pageSubstring = await api.functional.discussionboard.comments.index(connection, {
    body: { body: "+1" },
  });
  typia.assert(pageSubstring);
  TestValidator.predicate("body substring matched")(pageSubstring.data.every((x) => x.body.includes("+1")));

  // 8. Confirm only schema-defined (no non-schema) fields accepted in request
  //    - Not possible to test directly, type safety and doc review ensure this; the schema physically bars non-schema fields.

  // 9. Confirm all responses conform to IPageIComment schema (already covered by typia.assert above)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
