  TestValidator.equals("Fetched comment post id matches")(fetched.discussionboard_post_id)(comment.discussionboard_post_id);
  TestValidator.equals("Fetched comment member matches")(fetched.discussionboard_member_id)(comment.discussionboard_member_id);
  TestValidator.equals("Fetched comment deleted_at null")(fetched.deleted_at == null)(true);
}

