import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";

/**
 * Test updating the content of a discussion board comment by its author.
 *
 * This test ensures that a comment's text can be updated by its creator, and all updates are correctly reflected in the returned object. The workflow follows:
 *
 * 1. Create a discussion board post required as the parent for a comment.
 * 2. Create a comment under the post.
 * 3. Update the body (text) of the comment as the author.
 * 4. Verify the updated comment reflects the new content and that only schema fields are changed.
 */
export async function test_api_discussionboard_test_update_comment_content_by_author(
  connection: api.IConnection,
) {
  // 1. Create a discussion board post to serve as parent for the comment.
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const memberId = typia.random<string & tags.Format<"uuid">>();
  const boardId = typia.random<string & tags.Format<"uuid">>();
  const postCreateInput: IDiscussionboardPost.ICreate = {
    discussionboard_thread_id: threadId,
    discussionboard_member_id: memberId,
    discussionboard_board_id: boardId,
    title: "Original Post Title",
    body: "Initial post content.",
    is_deleted: false,
    created_at: new Date().toISOString() as string & tags.Format<"date-time">,
    updated_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const post = await api.functional.discussionboard.posts.create(connection, { body: postCreateInput });
  typia.assert(post);

  // 2. Create a comment under this post.
  const commentCreateInput: IComment.ICreate = {
    discussionboard_post_id: post.id,
    discussionboard_member_id: memberId,
    body: "First comment body.",
  };
  const comment = await api.functional.discussionboard.comments.create(connection, { body: commentCreateInput });
  typia.assert(comment);

  // 3. Update the comment body text as the author.
  const updatedBody = "Updated comment content.";
  const updatedComment = await api.functional.discussionboard.comments.update(connection, {
    id: comment.id,
    body: {
      body: updatedBody,
    } satisfies IComment.IUpdate,
  });
  typia.assert(updatedComment);

  // 4. Verify the updated comment reflects only the changed schema fields.
  // Body should be updated, id/member_id/post_id/created_at should remain the same, updated_at should update if supported by API.
  TestValidator.equals("comment.id unchanged")(updatedComment.id)(comment.id);
  TestValidator.equals("comment.member unchanged")(updatedComment.discussionboard_member_id)(comment.discussionboard_member_id);
  TestValidator.equals("comment.post unchanged")(updatedComment.discussionboard_post_id)(comment.discussionboard_post_id);
  TestValidator.equals("comment body updated")(updatedComment.body)(updatedBody);
  TestValidator.equals("created_at unchanged")(updatedComment.created_at)(comment.created_at);
  // If updated_at is present, updated_at should be different and a valid date-time.
  if (updatedComment.updated_at && comment.updated_at) {
    TestValidator.notEquals("updated_at changed")(updatedComment.updated_at)(comment.updated_at);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";

/**
 * Test changing a comment’s parent_id to convert it into a reply to another comment.
 *
 * This test case verifies the functionality of updating a comment so that it becomes a reply (child) of another comment. It confirms that the parent_id update is properly reflected in the database, and that the updated comment object strictly follows schema changes.
 *
 * Test steps:
 * 1. Create a discussion board post (and its initial thread/board/member IDs).
 * 2. Create two root-level comments under this post (commentA and commentB).
 * 3. Update commentB's parent_id so it becomes a reply to commentA.
 * 4. Fetch the updated comment and validate that:
 *    - parent_id === commentA.id
 *    - All other fields remain as expected, unless updated by schema (e.g., updated_at).
 *    - The comment object schema matches expectations.
 */
export async function test_api_discussionboard_test_update_comment_parent_for_nested_reply(
  connection: api.IConnection,
) {
  // 1. Create post prerequisites (thread/member/board IDs random for isolation).
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const boardId = typia.random<string & tags.Format<"uuid">>();
  const memberId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date().toISOString();
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: threadId,
      discussionboard_member_id: memberId,
      discussionboard_board_id: boardId,
      title: "Nested Reply Test Post",
      body: "Initial post body for nested reply parent_id update scenario.",
      is_deleted: false,
      created_at: now,
      updated_at: now,
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 2. Create two comments (A and B) under the same post.
  const commentA = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: memberId,
      body: "This is comment A.",
      parent_id: null,
    } satisfies IComment.ICreate,
  });
  typia.assert(commentA);

  const commentB = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: memberId,
      body: "This is comment B.",
      parent_id: null,
    } satisfies IComment.ICreate,
  });
  typia.assert(commentB);

  // 3. Update commentB: set its parent_id = commentA.id (making B a reply to A).
  const updatedB = await api.functional.discussionboard.comments.update(connection, {
    id: commentB.id,
    body: {
      parent_id: commentA.id,
    } satisfies IComment.IUpdate,
  });
  typia.assert(updatedB);

  // 4. Validate that the reply hierarchy is established as expected.
  TestValidator.equals("commentB is now a reply to commentA")(updatedB.parent_id)(commentA.id);
  TestValidator.equals("commentB.id unchanged")(updatedB.id)(commentB.id);
  TestValidator.equals("discussionboard_post_id unchanged")(updatedB.discussionboard_post_id)(post.id);
  TestValidator.equals("member unchanged")(updatedB.discussionboard_member_id)(memberId);
  // The body content should not have changed.
  TestValidator.equals("body unchanged")(updatedB.body)(commentB.body);
  // updated_at should be present and after created_at
  if (updatedB.updated_at !== null && updatedB.updated_at !== undefined && updatedB.created_at !== null) {
    TestValidator.predicate("updated_at > created_at")(updatedB.updated_at > updatedB.created_at);
  }
  // No deletion flag set
  TestValidator.equals("no delete")(updatedB.deleted_at)(null);
}

