import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";

/**
 * 회원 단건 조회 성공: 생성 → 조회 → 모든 필드/스키마 일치 검증
 *
 * - 신규 회원 등록 후 id로 단건 회원 API(/discussionboard/members/{id})를 호출한다.
 * - 반환 객체가 모든 필수 필드를 정확히 포함하며, 민감 정보(특히 'hashed_password') 노출이 없는지 확인한다.
 * - soft/hard delete(탈퇴/삭제) 처리가 없는 정상 회원임을 검증한다(deleted_at이 null/undefined).
 * - 응답 내 스키마 외 속성이 추가로 포함되지 않는지도 체크해 API 반환이 깨끗함을 보장한다.
 *
 * **검증 세부:**
 * 1. 신규 회원 가입 후 반환값(id 등) 확보
 * 2. 해당 id로 단건 회원 조회(/discussionboard/members/{id})
 * 3. 반환값에서 username, email, role, is_active 등 주요 정보 일치 확인
 * 4. hashed_password 등 민감 정보가 응답에 존재하지 않음 확인
 * 5. 탈퇴/삭제 처리되지 않은 회원임(null/undefined)
 * 6. 오직 스키마 내 필드만 응답에 존재함(불필요 정보 제거)
 */
export async function test_api_discussionboard_test_get_member_by_id_success(
  connection: api.IConnection,
) {
  // 1. 신규 회원 정보 준비 및 가입
  const memberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(10),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(20),
    role: RandomGenerator.pick(["member", "moderator", "admin"]),
    is_active: true,
  };
  const created: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, { body: memberInput });
  typia.assert(created);

  // 2. 해당 id로 회원 단건 조회
  const got: IDiscussionboardMember = await api.functional.discussionboard.members.at(connection, { id: created.id });
  typia.assert(got);

  // 3. 필드별 값/자료형 및 주요 정보 일치 검증
  TestValidator.equals("username")(got.username)(created.username);
  TestValidator.equals("email")(got.email)(created.email);
  TestValidator.equals("role")(got.role)(created.role);
  TestValidator.equals("is_active 일치")(got.is_active)(created.is_active);

  // 4. hashed_password(민감정보)가 응답에 존재하지 않음 보장
  TestValidator.predicate("hashed_password 필드 미포함")(!('hashed_password' in got));

  // 5. soft/hard delete 상태 아님 확인
  TestValidator.predicate("deleted_at null/undefined")(got.deleted_at === null || got.deleted_at === undefined);

  // 6. 스키마 필드 이외 부가 정보 미존재
  const allowedKeys = [
    "id",
    "username",
    "email",
    "role",
    "is_active",
    "created_at",
    "updated_at",
    "deleted_at",
  ];
  TestValidator.equals("스키마 필드만 존재")(Object.keys(got).sort())(allowedKeys.sort());
}

