import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";

/**
 * Test successful update of member fields (username, email, role, is_active).
 *
 * This test verifies that the API can update one or more editable fields of an existing member. It first creates a member with unique username and email, then performs an update of at least two of the updatable properties using valid values. After the update, it confirms that the changes are properly reflected in the returned record, while unchanged fields remain correct. It also validates that the update does not violate uniqueness constraints (i.e., changing email/username to a value that would cause duplication is not permitted—in the success scenario, only new unique values are chosen). Step-by-step:
 *
 * 1. Create an initial member, save the id and original field values
 * 2. Prepare valid, distinct new values for at least two of username, email, role, is_active
 * 3. Perform update with the new values
 * 4. Assert that the update response reflects the changed fields and unchanged fields are intact
 * 5. Optionally, query another update using a previously used (duplicate) value and expect error (error test handled elsewhere)
 */
export async function test_api_discussionboard_test_update_member_fields_successfully(
  connection: api.IConnection,
) {
  // 1. Create a new member for update
  const createInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    role: "member",
    is_active: true,
  };
  const original: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, { body: createInput });
  typia.assert(original);

  // 2. Prepare new valid values for updatable fields (distinct from original)
  const updateInput: IDiscussionboardMember.IUpdate = {
    username: RandomGenerator.alphabets(10), // new random username
    email: typia.random<string & tags.Format<"email">>(), // new random email
    role: "moderator", // different role
    is_active: false, // flip active flag
  };

  // 3. Update the member with valid new values
  const updated: IDiscussionboardMember = await api.functional.discussionboard.members.update(connection, {
    id: original.id,
    body: updateInput,
  });
  typia.assert(updated);

  // 4. Assert updated fields changed as expected
  TestValidator.equals("id unchanged")(updated.id)(original.id);
  TestValidator.equals("username updated")(updated.username)(updateInput.username);
  TestValidator.equals("email updated")(updated.email)(updateInput.email);
  TestValidator.equals("role updated")(updated.role)(updateInput.role);
  TestValidator.equals("is_active updated")(updated.is_active)(updateInput.is_active);
  // Assert the created_at timestamp remains unchanged
  TestValidator.equals("created_at unchanged")(updated.created_at)(original.created_at);
  // Optionally verify deleted_at still null or unchanged
  TestValidator.equals("deleted_at unchanged")(updated.deleted_at ?? null)(original.deleted_at ?? null);
  // updated_at should be equal or after original
  TestValidator.predicate("updated_at is newer or equal")(
    new Date(updated.updated_at) >= new Date(original.updated_at),
  );
  // Assert password/hash is never present in response (field not exposed)
  if ((updated as any).hashed_password !== undefined)
    throw new Error("hashed_password should not be present in the update response");
}

