export async function test_api_discussionboard_test_update_member_with_duplicate_username(connection: api.IConnection) {
  // 1. Create the first member (memberA)
  const usernameA = RandomGenerator.alphabets(8);
  const emailA = typia.random<string & tags.Format<"email">>();
