import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardChannel";

/**
 * Validate that a discussion board channel can be updated with valid data fields.
 *
 * This test verifies that updating an existing channel with a valid ID and valid payload reflecting schema-constrained changes (such as name, description, position, active) is successful and that the response matches the expected updates.
 *
 * Business context:
 * - Channels represent major sections of the discussion board (e.g., Politics, Economics).
 * - Updating a channel might rename, reposition, deactivate, or clarify the label.
 *
 * Process:
 * 1. Create a new channel (ensures a known, valid starting state and prevents uniqueness collisions during test runs).
 * 2. Update one or more mutable fields (name, description, position, active) using the update endpoint by channel ID.
 * 3. Assert that the API returns an updated channel reflecting all requested changes and that immutable or non-updated fields remain correct.
 * 4. Check audit fields: ensure created_at isn't changed and updated_at is updated accordingly.
 *
 * This validates the core update mechanics, schema handling, and adherence to field rules and uniqueness.
 */
export async function test_api_discussionboard_channels_test_update_channel_success_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create a new channel for testing (ensures valid ID and avoids uniqueness conflicts)
  const createInput = {
    code: `code_${RandomGenerator.alphaNumeric(8)}`,
    name: `Channel ${RandomGenerator.alphaNumeric(5)}`,
    description: "Initial description.",
    position: typia.random<number & tags.Type<"int32">>(),
    active: true,
  } satisfies IDiscussionboardChannel.ICreate;
  const created = await api.functional.discussionboard.channels.create(connection, { body: createInput });
  typia.assert(created);

  // 2. Prepare an update payload changing name, description, position, active
  const updatePayload = {
    name: `${createInput.name} - Updated`,
    description: "Modified channel description.",
    position: createInput.position + 10,
    active: false,
  } satisfies IDiscussionboardChannel.IUpdate;
  const updated = await api.functional.discussionboard.channels.update(connection, {
    id: created.id,
    body: updatePayload,
  });
  typia.assert(updated);

  // 3. Validate changed and unchanged fields
  TestValidator.equals("id remains")(updated.id)(created.id);
  TestValidator.equals("code unchanged")(updated.code)(created.code);
  TestValidator.equals("name updated")(updated.name)(updatePayload.name);
  TestValidator.equals("description updated")(updated.description)(updatePayload.description);
  TestValidator.equals("position updated")(updated.position)(updatePayload.position);
  TestValidator.equals("active updated")(updated.active)(updatePayload.active);
  TestValidator.equals("created_at static")(updated.created_at)(created.created_at);
  TestValidator.predicate("updated_at updated")(Date.parse(updated.updated_at) >= Date.parse(created.updated_at));
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardChannel";

/**
 * Validate that updating a discussion board channel to use a code or name that already exists for another channel fails with a uniqueness validation error.
 *
 * Business context:
 * - Each channel in the forum must have unique values for 'code' and 'name'.
 * - Attempting to update any channel's code or name to a value already used by another channel should trigger a validation error, preventing database uniqueness violation.
 *
 * Test Steps:
 * 1. Create two channels with distinct unique 'code' and 'name' values (e.g., channelA: code="alpha", name="Alpha"; channelB: code="beta", name="Beta").
 * 2. Attempt to update channelA: (a) to use channelB's code (while leaving name unchanged), (b) to use channelB's name (while leaving code unchanged).
 * 3. For each update attempt, verify that the API rejects the operation with an error indicating violation of the unique constraint.
 */
export async function test_api_discussionboard_test_update_channel_with_duplicate_code_or_name_return_error(
  connection: api.IConnection,
) {
  // 1. Create first channel (channelA)
  const channelACreate = {
    code: "alpha",
    name: "Alpha",
    description: "First channel for uniqueness test",
    position: 1,
    active: true,
  } satisfies IDiscussionboardChannel.ICreate;
  const channelA = await api.functional.discussionboard.channels.create(connection, { body: channelACreate });
  typia.assert(channelA);

  // 2. Create second channel (channelB) with different code and name
  const channelBCreate = {
    code: "beta",
    name: "Beta",
    description: "Second channel for uniqueness test",
    position: 2,
    active: true,
  } satisfies IDiscussionboardChannel.ICreate;
  const channelB = await api.functional.discussionboard.channels.create(connection, { body: channelBCreate });
  typia.assert(channelB);

  // 3a. Attempt to update channelA's code to channelB's code ("beta")
  await TestValidator.error("duplicate code should be rejected")(() =>
    api.functional.discussionboard.channels.update(connection, {
      id: channelA.id,
      body: { code: channelB.code } satisfies IDiscussionboardChannel.IUpdate,
    })
  );

  // 3b. Attempt to update channelA's name to channelB's name ("Beta")
  await TestValidator.error("duplicate name should be rejected")(() =>
    api.functional.discussionboard.channels.update(connection, {
      id: channelA.id,
      body: { name: channelB.name } satisfies IDiscussionboardChannel.IUpdate,
    })
  );
}

