import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IDiscussionboardCommentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentReport";

/**
 * Validate retrieval of a comment report by its unique id.
 *
 * Business context:
 * Moderators/admins need to fetch the full details of a comment report for moderation. The report must exist, and all cross-references (comment, member, type) should be correctly linked. The details must match exactly the persisted record used for reporting.
 * Proper access control is critical: Only moderators/admins may access; regular members should be rejected (access control logic cannot be implemented/tested directly here as no auth API is exposed).
 *
 * Test process:
 * 1. Create a comment to serve as the report target.
 * 2. File a comment report against the comment with all required fields and references.
 * 3. Retrieve the comment report by its unique id.
 * 4. Validate that all properties in the retrieved report exactly match the created record.
 */
export async function test_api_discussionboard_test_get_comment_report_by_valid_id(
  connection: api.IConnection,
) {
  // 1. Create a comment as the report target
  const commentBody = RandomGenerator.paragraph()();
  const postId = typia.random<string & tags.Format<"uuid">>();
  const authorMemberId = typia.random<string & tags.Format<"uuid">>();
  const comment = await api.functional.discussionboard.comments.create(
    connection,
    {
      body: {
        discussionboard_post_id: postId,
        discussionboard_member_id: authorMemberId,
        body: commentBody,
      },
    },
  );
  typia.assert(comment);

  // 2. File a comment report referencing the comment
  const reporterMemberId = typia.random<string & tags.Format<"uuid">>();
  const reportTypeId = typia.random<string & tags.Format<"uuid">>();
  const created_at = new Date().toISOString();
  const reason = RandomGenerator.paragraph()();
  const report = await api.functional.discussionboard.commentReports.create(
    connection,
    {
      body: {
        discussionboard_comment_id: comment.id,
        discussionboard_member_id: reporterMemberId,
        discussionboard_report_type_id: reportTypeId,
        reason,
        created_at,
      },
    },
  );
  typia.assert(report);

  // 3. Retrieve the comment report by id
  const fetched = await api.functional.discussionboard.commentReports.at(
    connection,
    { id: report.id },
  );
  typia.assert(fetched);

  // 4. Validate that all properties match exactly
  TestValidator.equals("report id")(fetched.id)(report.id);
  TestValidator.equals("comment ref")(fetched.discussionboard_comment_id)(report.discussionboard_comment_id);
  TestValidator.equals("member ref")(fetched.discussionboard_member_id)(report.discussionboard_member_id);
  TestValidator.equals("report type ref")(fetched.discussionboard_report_type_id)(report.discussionboard_report_type_id);
  TestValidator.equals("reason")(fetched.reason)(report.reason);
  TestValidator.equals("created_at")(fetched.created_at)(report.created_at);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
