  await TestValidator.error("should throw not found error for nonexistent comment report")(
    async () => {
      await api.functional.discussionboard.commentReports.at(connection, {
        id: nonExistentId,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IDiscussionboardCommentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentReport";

/**
 * 이미 하드 삭제(완전 삭제)된 댓글 신고 레코드 조회 시 동작 검증
 *
 * 본 테스트는 실제 운영 환경에서 삭제(eraseById)된 댓글 신고(comment report) 레코드에 대해
 * REST API(GET /discussionboard/commentReports/:id) 조회를 시도할 때,
 * API가 null 또는 Not Found(존재하지 않음) 예외를 정확히 반환하는지 검증합니다.
 *
 * **테스트 흐름 요약:**
 * 1. 테스트용 댓글(comment)을 하나 생성
 * 2. 해당 댓글에 대한 신고(comment report) 생성
 * 3. 생성된 신고 레코드를 하드 삭제(erase)
 * 4. 삭제된 신고 id로 GET 조회 시도 → 반드시 예외 또는 빈 결과 발생해야 함 확인
 *
