  TestValidator.equals("acting_moderator_id 유지됨")(updated.acting_moderator_id)(moderationAction.acting_moderator_id);
  TestValidator.equals("target_object_id 유지됨")(updated.target_object_id)(moderationAction.target_object_id);
  TestValidator.equals("target_object_type 유지됨")(updated.target_object_type)(moderationAction.target_object_type);
  TestValidator.equals("actioned_at 유지됨")(updated.actioned_at)(moderationAction.actioned_at);
  TestValidator.equals("report_id 유지됨")(updated.report_id)(moderationAction.report_id);
}

