 * 테스트 목적: 특정 댓글의 ID로 댓글 스냅샷 목록을 검색하는 기능의 정상 동작을 검증합니다.
 *
 * 비즈니스 시나리오 및 필요성:
 * - 댓글은 수정/편집 이력을 스냅샷 형태로 별도 관리하며, 이 스냅샷들은 감사, 롤백, 편집 히스토리 UI 등에 활용됩니다.
 * - 스냅샷 검색 기능이 잘 동작하는지(특히 comment_id 기준으로 여러 버전이 정확히 할당·조회되는지) 검증해야 서비스 신뢰성과 감사 추적이 확보됩니다.
 *
 * 구현 과정 및 단계:
 * 1. 회원(member) 1명을 생성합니다.
 * 2. 해당 회원이 작성자로 지정된 게시글(post)을 생성합니다.
 * 3. 방금 생성한 post의 id, member의 id로 댓글(comment) 1개를 생성합니다.
 * 4. 위 댓글의 id 기준으로 comment snapshot을 1개 등록합니다.
 * 5. 댓글 id를 기준으로 PATCH /discussionboard/commentSnapshots API를 호출하여 검색합니다.
 * 6. 검색결과 data 배열에서 방금 만든 snapshot이 id, version, 외래키 등 정확하게 일치하여 반환되는지 검증합니다.
 *
 * 검증 포인트:
 * - 검색 결과가 페이징 객체 및 배열 구조로 올바르게 반환됨(typia.assert)
 * - 데이터 배열 내에 우리가 생성한 snapshot 고유 id가 반드시 포함됨(TestValidator.predicate)
 * - 포함된 경우, version/외래키/본문 등 주요정보가 모두 일치하는지 추가 확인(TestValidator.equals)
 */
export async function test_api_discussionboard_test_search_comment_snapshots_by_comment_id(
  connection: api.IConnection,
) {
  // 1. 회원(member) 1명 생성
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. 게시글(post) 생성 (member.id를 작성자로)
  const now = new Date().toISOString();
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: member.id,
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(8),
      body: RandomGenerator.content()(2)(),
      is_deleted: false,
      created_at: now,
      updated_at: now,
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 3. post/회원 ID 기반 댓글(comment) 작성
  const comment = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member.id,
      body: RandomGenerator.paragraph()(3),
    } satisfies IComment.ICreate,
  });
  typia.assert(comment);

  // 4. 해당 댓글의 첫번째 snapshot 등록
  const snapshot = await api.functional.discussionboard.commentSnapshots.create(connection, {
    body: {
      discussionboard_comment_id: comment.id,
      discussionboard_member_id: member.id,
      discussionboard_post_id: post.id,
      body: comment.body,
      version: 1,
      snapshot_created_at: new Date().toISOString(),
    } satisfies IDiscussionboardCommentSnapshot.ICreate,
  });
  typia.assert(snapshot);

  // 5. 댓글 id(disussionboard_comment_id)로 snapshot들 검색
  const page = await api.functional.discussionboard.commentSnapshots.index(connection, {
    body: {
      discussionboard_comment_id: comment.id,
    },
  });
  typia.assert(page);

  // 6. 검색결과 data 중 우리가 방금 등록한 snapshot이 포함되어있는지, id 등 일치 체크
  const found = page.data.find((snap) => snap.id === snapshot.id);
  TestValidator.predicate("스냅샷 id가 검색 결과에 포함되어야 함")(!!found);
  if (found) {
    TestValidator.equals("comment id 일치")(found.discussionboard_comment_id)(comment.id);
    TestValidator.equals("version 일치")(found.version)(snapshot.version);
    TestValidator.equals("member id 일치")(found.discussionboard_member_id)(member.id);
    TestValidator.equals("post id 일치")(found.discussionboard_post_id)(post.id);
    TestValidator.equals("내용 일치")(found.body)(comment.body);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IDiscussionboardCommentSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentSnapshot";
import type { IPageIDiscussionboardCommentSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardCommentSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 테스트: 댓글 스냅샷의 페이지네이션(페이징) 검색 동작 검증
 *
 * 이 테스트는 /discussionboard/commentSnapshots API에 대해 실제 댓글이 여럿 버전으로
 * 스냅샷이 쌓인 상황에서 페이징 검색 시 메타데이터(pagination)와 데이터 슬라이스가
 * 정확하게 동작하는지 검증합니다.
 *
 * 단계:
 * 1. 댓글 작성자를 위한 멤버 생성
 * 2. 댓글이 달릴 게시글 생성 (post, thread/board UUID 필요)
 * 3. 해당 게시글에 댓글 생성
 * 4. 댓글에 대해 여러 번(버전) 스냅샷 생성 (댓글의 수정 이력 시뮬레이트)
 * 5. PATCH /discussionboard/commentSnapshots를 통해 페이징 기반으로 검색
 * 6. 페이징 메타데이터(전체 개수/limit 등)와 데이터 결과가 기대와 일치하는지 검증
 *
 * 중점 검증 사항:
 * - 특정 댓글에 대한 스냅샷들이 올바르게 리스트업됨
 * - 페이지네이션 메타(pagination)에 전체 개수, limit 등이 정확히 표시됨
 * - 요청 limit에 맞춘 데이터 slice(슬라이스) 정합성
 * - 각 요소가 올바른 comment id/버전/시각 정보 보유
 */
export async function test_api_discussionboard_test_search_comment_snapshots_with_pagination(
  connection: api.IConnection,
) {
  // 1. 댓글 작성자 멤버 생성
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. 게시글 생성 (스레드/보드 UUID 임의 생성)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const boardId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date().toISOString();

  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: threadId,
      discussionboard_board_id: boardId,
      discussionboard_member_id: member.id,
      title: RandomGenerator.paragraph()(8),
      body: RandomGenerator.content()(30)(),
      is_deleted: false,
      created_at: now,
      updated_at: now,
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 3. 게시글에 댓글 작성
  const comment = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member.id,
      body: RandomGenerator.content()(15)(),
      // parent_id 없음 (최상위 덧글)
    } satisfies IComment.ICreate,
  });
  typia.assert(comment);

  // 4. 댓글에 대한 여러 스냅샷(수정이력) 생성
  const SNAPSHOT_COUNT = 7;
  const snapshots: IDiscussionboardCommentSnapshot[] = [];
  let baseTime = Date.now();
  for (let i = 1; i <= SNAPSHOT_COUNT; ++i) {
    // 1회 수정마다 1분씩 증가 (시계열 순서 보장)
    const createdAt = new Date(baseTime + i * 60000).toISOString();
    const snapshot = await api.functional.discussionboard.commentSnapshots.create(connection, {
      body: {
        discussionboard_comment_id: comment.id,
        discussionboard_member_id: member.id,
        discussionboard_post_id: post.id,
        body: `Edit body ${i}`,
        version: i,
        snapshot_created_at: createdAt,
      } satisfies IDiscussionboardCommentSnapshot.ICreate,
    });
    typia.assert(snapshot);
    snapshots.push(snapshot);
  }

  // 5. 페이징 검색: limit=3 기준으로 한번 요청
  const PAGE_LIMIT = 3;
  // 첫 페이지(초기 limit 내 데이터)
  const firstPage = await api.functional.discussionboard.commentSnapshots.index(connection, {
    body: {
      discussionboard_comment_id: comment.id,
      // limit/offset 파라미터는 search DTO에 없지만, 통상 결과는 limit=100(default) 기준으로 슬라이스됨
    } satisfies IDiscussionboardCommentSnapshot.IRequest,
  });
  typia.assert(firstPage);

  // 6. 페이지네이션/데이터 결과 검증
  TestValidator.equals("pagination: total count")(firstPage.pagination.records)(SNAPSHOT_COUNT);
  // limit=100(default)임을 전제로, 결과 slicing은 직접 체크
  TestValidator.equals("snapshots: count on first page")(firstPage.data.length)(Math.min(100, SNAPSHOT_COUNT));

  // 각 결과가 올바른 comment id인지, 버전 증가 순서 여부(버전 필드가 1~7 순인지) 검증
  let version = 1;
  for (const snapshot of firstPage.data) {
    TestValidator.equals("snapshot: comment id 매칭")(snapshot.discussionboard_comment_id)(comment.id);
    TestValidator.equals("snapshot: version 번호")(snapshot.version)(version++);
  }
}

