import type { IDiscussionboardCommentSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentSnapshot";

/**
 * Test updating a comment snapshot with valid data.
 *
 * This test ensures that updating a comment snapshot's modifiable fields
 * (body and/or version) works as expected through the API.
 *
 * The test proceeds with the following workflow:
 * 1. Create a member who will author comments and snapshots
 * 2. Create a post to attach the comment
 * 3. Create a comment on the post by the member
 * 4. Create a comment snapshot from that comment
 * 5. Update the snapshot's body and version using the update endpoint
 * 6. Validate that the returned object reflects the new body/content and version as expected, and still matches the original snapshot's id
 */
export async function test_api_discussionboard_test_update_comment_snapshot_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create member who will author the comment snapshot
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create a new post on the discussion board
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: member.id,
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(),
      is_deleted: false,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 3. Create a comment on the post
  const comment = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member.id,
      body: RandomGenerator.content()()(),
    } satisfies IComment.ICreate,
  });
  typia.assert(comment);

  // 4. Create a comment snapshot based on the comment
  const snapshot = await api.functional.discussionboard.commentSnapshots.create(connection, {
    body: {
      discussionboard_comment_id: comment.id,
      discussionboard_member_id: member.id,
      discussionboard_post_id: post.id,
      body: comment.body,
      version: 1,
      snapshot_created_at: new Date().toISOString(),
    } satisfies IDiscussionboardCommentSnapshot.ICreate,
  });
  typia.assert(snapshot);

  // 5. Update the snapshot: change body and version
  const updatedBody = "[UPDATED] " + snapshot.body;
  const updatedVersion = snapshot.version + 1;
  const updatedSnapshot = await api.functional.discussionboard.commentSnapshots.update(connection, {
    id: snapshot.id,
    body: {
      body: updatedBody,
      version: updatedVersion,
    } satisfies IDiscussionboardCommentSnapshot.IUpdate,
  });
  typia.assert(updatedSnapshot);

  // 6. Validate the updated snapshot fields
  TestValidator.equals("snapshot id matches")(updatedSnapshot.id)(snapshot.id);
  TestValidator.equals("body updated")(updatedSnapshot.body)(updatedBody);
  TestValidator.equals("version updated")(updatedSnapshot.version)(updatedVersion);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardCommentSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentSnapshot";

/**
 * 존재하지 않거나 삭제된 ID로 댓글 스냅샷 업데이트 시 에러 처리 검증
 *
 * ⚡️ 테스트 목적:
 *   - discussionboard_comment_snapshots 테이블에 실제로 존재하지 않는(무작위 uuid) ID로 업데이트를 시도했을 때,
 *     비즈니스 규칙상 오류 발생 및 적절한 실패 처리(에러 반환)를 검증한다.
 *
 * ⚡️ 테스트 플로우:
 *   1. 존재하지 않는(임의의) UUID를 준비한다(실제 db에 없는 값).
 *   2. 업데이트 요청 바디(body, version)를 일부 지정한다.
 *   3. update API 호출을 시도하고, 실패(에러) 여부를 TestValidator.error로 검증한다.
 */
export async function test_api_discussionboard_test_update_comment_snapshot_with_invalid_id(
  connection: api.IConnection,
) {
  // 1. 존재하지 않는/삭제된 댓글 스냅샷 ID 준비 (랜덤 uuid)
  const invalidId: string = typia.random<string & tags.Format<"uuid">>();

  // 2. 업데이트 바디(내용+버전 번호 임의 입력)
  const updateBody: IDiscussionboardCommentSnapshot.IUpdate = {
