import type { IDiscussionboardCommentSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentSnapshot";

/**
 * Validate the hard deletion of a comment snapshot by ID.
 *
 * This test ensures that deleting a comment snapshot using a valid ID truly removes it from the system.
 *
 * Test Workflow:
 * 1. Create a discussionboard member for authorship
 * 2. Create a discussionboard post
 * 3. Create a comment on the post as the member
 * 4. Create a comment snapshot for the comment
 * 5. Perform a hard delete by ID
 * 6. Attempt to delete again and expect an error (verify non-existence)
 *
 * Business context:
 * - Members may generate comment snapshots for audit/history. Permanent deletion is supported only via this endpoint.
 * - Success here means the snapshot is no longer available for removal or access.
 */
export async function test_api_discussionboard_test_delete_comment_snapshot_success(
  connection: api.IConnection,
) {
  // 1. Create a discussionboard member (author)
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create a post for the member
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: member.id,
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(),
      is_deleted: false,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 3. Create a comment on the post
  const comment = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member.id,
      body: RandomGenerator.content()()(),
    } satisfies IComment.ICreate,
  });
  typia.assert(comment);

  // 4. Create a comment snapshot
  const snapshot = await api.functional.discussionboard.commentSnapshots.create(connection, {
    body: {
      discussionboard_comment_id: comment.id,
      discussionboard_member_id: member.id,
      discussionboard_post_id: post.id,
      body: comment.body,
      version: 1,
      snapshot_created_at: new Date().toISOString(),
    } satisfies IDiscussionboardCommentSnapshot.ICreate,
  });
  typia.assert(snapshot);

  // 5. Perform a hard delete by ID
  await api.functional.discussionboard.commentSnapshots.erase(connection, {
    id: snapshot.id,
  });

  // 6. Attempt to delete again (should fail)
  await TestValidator.error("deleting already-deleted snapshot should fail")(
    async () => {
      await api.functional.discussionboard.commentSnapshots.erase(connection, { id: snapshot.id });
    },
  );
}

