import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPrivacyPolicy } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPrivacyPolicy";
import type { IPageDiscussionboardPrivacyPolicy } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardPrivacyPolicy";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 개인정보처리방침(Privacy Policy) 페이지네이션/검색 기능의 필터 적용에 대한 E2E 테스트입니다.
 *
 * 이 테스트는 관리자 권한 회원 계정을 생성 후, 여러 건의 개인정보처리방침(상이한 버전/effective_date) 데이터를 준비해,
 * 다양한 필터링(버전 단일/없는 값, 제목 부분검색, 효력일 범위/일치)과 pagination/응답구조 적합성까지 일관되게 검증합니다.
 *
 * 주요 검증 포인트:
 * 1. 관리자 회원 등록 및 정상 응답 구조
 * 2. 다건 개인정보처리방침 등록 후 각각 고유 버전/날짜 세팅(유니크)
 * 3. version(정확매칭), title(포함/부분검색), effective_date(범위 및 단일 equality)별 필터 적용 시 정확한 결과 반환
 * 4. 없는 version 검색 시 0건 반환 확인
 * 5. pagination 메타데이터(페이지, limit, 총개수, 총페이지) 및 각 정책 데이터 필드 타입 검증
 * 6. 모든 응답에 schema 외 필드나 미정의 데이터 존재하지 않음(스키마 안전/감사 적합)
 *
 * ※ 불필요한 schema 외 필터/field 사용하지 않으며, 오로지 정책 schema 정의 내 쿼리 필드로만 검증합니다.
 */
export async function test_api_discussionboard_test_search_privacy_policies_with_valid_filters(
  connection: api.IConnection,
) {
  // 1. 관리자 계정 생성
  const admin = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(20),
      role: "admin",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(admin);

  // 2. 서로 다른 Privacy Policy 데이터 3건 등록 (version/날짜/타이틀 모두 유니크)
  const policies = await ArrayUtil.asyncRepeat(3)(async (idx) => {
    const policy = await api.functional.discussionboard.privacyPolicies.create(connection, {
      body: {
        version: `v2024.0${idx + 1}`,
        effective_date: new Date(2024, 6, 1 + idx).toISOString(),
        title: `개인정보보호정책 ${idx + 1}`,
        content: `테스트용 개인정보 처리방침 본문 ${idx + 1}`,
      } satisfies IDiscussionboardPrivacyPolicy.ICreate,
    });
    typia.assert(policy);
    return policy;
  });

  // 3. version(정확매칭)별 단일 검색 및 미존재 값 0건 검색
  for (const policy of policies) {
    const search = await api.functional.discussionboard.privacyPolicies.index(connection, {
      body: { version: policy.version } satisfies IDiscussionboardPrivacyPolicy.IRequest,
    });
    typia.assert(search);
    TestValidator.predicate("version별 고유 단건 반환")(
      search.data.length === 1 && search.data[0].version === policy.version
    );
  }
  const invalidVersionRes = await api.functional.discussionboard.privacyPolicies.index(connection, {
    body: { version: "v9999.99" } satisfies IDiscussionboardPrivacyPolicy.IRequest,
  });
  typia.assert(invalidVersionRes);
  TestValidator.equals("존재하지 않는 version 0건 반환")(invalidVersionRes.data.length)(0);

  // 4. title 부분검색: "개인정보", "정책", 숫자 포함 여부로 필터링
  for (const keyword of ["개인정보", "정책", "1"]) {
    const search = await api.functional.discussionboard.privacyPolicies.index(connection, {
      body: { title: keyword } satisfies IDiscussionboardPrivacyPolicy.IRequest,
    });
    typia.assert(search);
    TestValidator.predicate(`title 키워드('${keyword}') 포함 데이터만 반환`)(
      search.data.every(row => row.title.includes(keyword))
    );
  }

  // 5. effective_date 범위/정확일치
  const baseDate = policies[1].effective_date;
  // 이상 (baseDate 이후 또는 일치)
  const afterRes = await api.functional.discussionboard.privacyPolicies.index(connection, {
    body: { effective_date: baseDate } satisfies IDiscussionboardPrivacyPolicy.IRequest,
  });
  typia.assert(afterRes);
  TestValidator.predicate("effective_date >= baseDate 데이터 반환")(
    afterRes.data.every(row => row.effective_date >= baseDate)
  );

  // 정확히 일치하는 날짜만 필터
  const exactDate = policies[0].effective_date;
  const exactRes = await api.functional.discussionboard.privacyPolicies.index(connection, {
    body: { effective_date: exactDate } satisfies IDiscussionboardPrivacyPolicy.IRequest,
  });
  typia.assert(exactRes);
  TestValidator.predicate("정확히 해당 effective_date만 반환")(
    exactRes.data.every(row => row.effective_date === exactDate)
  );

  // 6. pagination 메타데이터/응답 필드 구조 검증
  const pageRes = await api.functional.discussionboard.privacyPolicies.index(connection, {
    body: {} satisfies IDiscussionboardPrivacyPolicy.IRequest,
  });
  typia.assert(pageRes);
  TestValidator.predicate("pagination 필드 있음 & 타입 확인")(
    typeof pageRes.pagination.current === "number" &&
    typeof pageRes.pagination.limit === "number" &&
    typeof pageRes.pagination.records === "number" &&
    typeof pageRes.pagination.pages === "number"
  );

  TestValidator.predicate("data 필드 내 타입 유효성")(
    pageRes.data.every(row =>
      typeof row.id === "string" &&
      typeof row.version === "string" &&
      typeof row.title === "string"
    )
  );
}

