  typia.assert(admin);
  TestValidator.equals("admin role check")(admin.role)("admin");

  // 2. 개인정보 처리방침 신규 등록
  const initialPolicyInput: IDiscussionboardPrivacyPolicy.ICreate = {
    version: `v${new Date().getFullYear()}.${String(new Date().getMonth()+1).padStart(2,"0")}`,
