import type { IDiscussionboardCommentVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentVote";

/**
 * 댓글 투표(vote_type) 변경 및 권한 검증 E2E 테스트.
 *
 * 본 테스트는 실제로 투표의 소유자만 투표 타입을 변경할 수 있고,
 * 변경 시 updated_at이 갱신됨을 보장하며, 비소유자 및 비회원 접근 시
 * 권한 오류가 발생하는지, 존재하지 않는 투표에 대한 update 시도시 에러 응답이 있는지 검증합니다.
 *
 * 테스트 단계:
 * 1. 회원A(소유자) 생성 및 로그인 연결 유지
 * 2. 게시글/댓글 작성 (회원A 소유)
 * 3. 회원A가 해당 댓글에 투표(vote_type: "up") 생성
 * 4. 회원A로 해당 투표 vote_type을 "down" 등으로 변경, updated_at 갱신
 * 5. 실제 객체에서 vote_type 및 updated_at 값이 반영됐는지 검증
 * 6. 별도 회원B로 동일 투표 업데이트 시도 -> 권한 에러 발생 확인
 * 7. 비로그인 상태(Authorization 헤더 없는 연결)에서 업데이트 시도 -> 접근 차단/에러 검증
 * 8. 마지막으로, 존재하지 않는 id로 업데이트 시도시 오류 발생 확인
 */
export async function test_api_discussionboard_commentVotes_test_update_comment_vote_type_and_check_permissions(
  connection: api.IConnection,
) {
  // 1. 회원A(소유자) 생성
  const memberA = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(memberA);

  // 2. 게시글/댓글 작성 (회원A 소유)
  const threadId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const boardId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: threadId,
      discussionboard_member_id: memberA.id,
      discussionboard_board_id: boardId,
      title: RandomGenerator.paragraph(1)(),
      body: RandomGenerator.paragraph(2)(),
      is_deleted: false,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    },
  });
  typia.assert(post);

  const comment = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: memberA.id,
      body: RandomGenerator.paragraph(1)(),
    },
  });
  typia.assert(comment);

  // 3. 투표 최초 생성 (회원A, vote_type: "up")
  const voteCreated = await api.functional.discussionboard.commentVotes.create(connection, {
    body: {
      discussionboard_comment_id: comment.id,
      discussionboard_member_id: memberA.id,
      vote_type: "up",
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(voteCreated);

  // 4. 회원A로 vote_type을 "down"으로 변경, updated_at 갱신
  const updated_at_new = new Date(new Date().getTime() + 1000).toISOString();
  const voteUpdated = await api.functional.discussionboard.commentVotes.update(connection, {
    id: voteCreated.id,
    body: {
      vote_type: "down",
      updated_at: updated_at_new,
    },
  });
  typia.assert(voteUpdated);
  TestValidator.equals("vote_type update")(voteUpdated.vote_type)("down");
  // updated_at 실제 반영 여부
  TestValidator.equals("updated_at changed")(voteUpdated.updated_at)(updated_at_new);

  // 5. 회원B(비소유자) 생성 및 해당 투표 접근 시도(업데이트)
  const memberB = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(memberB);

  // 6. 회원B가 투표 수정 시도 - 권한 에러 발생 기대
  TestValidator.error("비소유자 투표수정은 실패해야함")(async () => {
    await api.functional.discussionboard.commentVotes.update(connection, {
      id: voteCreated.id,
      body: {
        vote_type: "up", // 기존과 다른 값
        updated_at: new Date().toISOString(),
      },
    });
  });

  // 7. 인증 없는 연결로 업데이트 시도 (권한/인증 에러 기대)
  const connectionWithoutAuth = { ...connection, headers: {} };
  TestValidator.error("비회원(비인증)으로 투표수정 불가")(async () => {
    await api.functional.discussionboard.commentVotes.update(connectionWithoutAuth, {
      id: voteCreated.id,
      body: {
        vote_type: "down",
        updated_at: new Date().toISOString(),
      },
    });
  });

  // 8. 존재하지 않는 id로 update 시도시 오류 발생 기대
  TestValidator.error("존재하지 않는 id 업데이트 에러")(async () => {
    await api.functional.discussionboard.commentVotes.update(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        vote_type: "up",
        updated_at: new Date().toISOString(),
      },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IDiscussionboardCommentVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentVote";

/**
 * Validate permanent deletion (hard delete) of a comment vote via its id.
 *
 * This test covers the business flow of a member creating a vote on a comment, deleting it, and ensuring the vote is permanently erased:
 *
 * 1. Create a member who will cast votes.
 * 2. Create a post and a comment (to vote on).
 * 3. The member creates a vote (upvote or downvote) on the comment.
 * 4. Delete the comment vote by its id using the DELETE endpoint.
 * 5. Validate that the vote can no longer be fetched or found in future queries.
 * 6. Attempt deletion of the same id again — expect error or no-op (test for idempotency/404 behavior depending on API behavior).
 * 7. Try deleting a clearly non-existent id — expect appropriate error or null response.
 * 8. Ensure that another user (non-owner) cannot delete someone else's vote.
 * 9. Re-cast a vote from the same member for the same comment, proving that the vote was really erased (no unique constraint error, etc.).
 *
 * Edge cases: deletion is permanent, the id no longer exists, and vote can be recreated.
 */
export async function test_api_discussionboard_test_delete_comment_vote_by_id_and_handle_not_found_cases(
  connection: api.IConnection,
) {
  // Step 1: Register main member
  const member: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // Step 2: Create a post for the comment
  const post: IDiscussionboardPost = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: member.id,
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
      is_deleted: false,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // Step 3: Create a comment for voting
  const comment: IComment = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member.id,
      body: RandomGenerator.paragraph()(),
    } satisfies IComment.ICreate,
  });
  typia.assert(comment);

  // Step 4: Member votes on the comment
  const vote: IDiscussionboardCommentVote = await api.functional.discussionboard.commentVotes.create(connection, {
    body: {
      discussionboard_comment_id: comment.id,
      discussionboard_member_id: member.id,
      vote_type: "up",
      created_at: new Date().toISOString(),
    } satisfies IDiscussionboardCommentVote.ICreate,
  });
  typia.assert(vote);

  // Step 5: Delete the vote by its id (hard delete)
  await api.functional.discussionboard.commentVotes.erase(connection, {
    id: vote.id,
  });

  // There is no get/query-by-id for comment vote, so we check by trying to re-create
  // Step 6: Recreate a vote by same member for same comment (should succeed, i.e., previous record truly gone)
  const newVote: IDiscussionboardCommentVote = await api.functional.discussionboard.commentVotes.create(connection, {
    body: {
      discussionboard_comment_id: comment.id,
      discussionboard_member_id: member.id,
      vote_type: "down",
      created_at: new Date().toISOString(),
    } satisfies IDiscussionboardCommentVote.ICreate,
  });
  typia.assert(newVote);

  // Step 7: Try deleting with a clearly non-existent UUID (should error or be a no-op)
  await TestValidator.error("delete non-existent vote id")(() =>
    api.functional.discussionboard.commentVotes.erase(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    })
  );

  // Step 8: Deletion is restricted to owner — create a second member and vote, try to delete with first member
  const otherMember: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(otherMember);
  const voteByOther: IDiscussionboardCommentVote = await api.functional.discussionboard.commentVotes.create(connection, {
    body: {
      discussionboard_comment_id: comment.id,
      discussionboard_member_id: otherMember.id,
      vote_type: "up",
      created_at: new Date().toISOString(),
    } satisfies IDiscussionboardCommentVote.ICreate,
  });
  typia.assert(voteByOther);
  await TestValidator.error("non-owner cannot delete another's vote")(() =>
    api.functional.discussionboard.commentVotes.erase(connection, {
      id: voteByOther.id,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
