/**
 * Test reporting a comment and the duplicate report constraint for API endpoint POST /discussionboard/commentReports.
 *
 * This E2E test explicitly validates:
 * 1. That a report on a comment by a member, with all required schema fields (and only allowed fields), can be created successfully.
 * 2. That a duplicate report (same comment, reporter, and reason/type) by the same reporter fails due to uniqueness/business rules, as per API contract.
 *
 * The workflow includes:
 * - Creating two members (one that will author, one that will report)
 * - Creating a post by the author
 * - Creating a comment on the post by the author
 * - The report member files a report on the comment (succession: required fields, type, timestamp)
 * - (Validation) The report creation is successful, matching the schema and containing only allowed properties.
 * - The report member attempts to file the exact same report again (identical comment, member, report type, timestamp etc.)
 * - (Validation) The second report must fail with a unique-constraint error or other API-defined duplicate rejection.
 *
 * Steps:
 * 1. Create member_A (comment author)
 * 2. Create member_B (reporting member)
 * 3. Create a post by member_A
 * 4. Create a comment by member_A on the post
 * 5. Create a report on the comment by member_B with all required schema fields
 * 6. Confirm the report entry matches the schema (assert)
 * 7. Attempt a duplicate report (same payload, same member, comment, reason/type, timestamp)
 * 8. Confirm the API rejects the duplicate (assert error)
 */
export async function test_api_discussionboard_test_create_comment_report_with_required_fields_and_duplicate_handling(
  connection: api.IConnection,
) {
  // 1. Create member_A (author)
  const memberA = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(memberA);

  // 2. Create member_B (reporter)
  const memberB = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(memberB);

  // 3. Create a post by memberA
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const boardId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date().toISOString();
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: threadId,
      discussionboard_member_id: memberA.id,
      discussionboard_board_id: boardId,
      title: RandomGenerator.paragraph()(20),
      body: RandomGenerator.paragraph()(50),
      is_deleted: false,
      created_at: now,
      updated_at: now,
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 4. Create a comment by memberA on the post
  const comment = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: memberA.id,
      body: RandomGenerator.paragraph()(10),
      // parent_id omitted (top-level comment)
    } satisfies IComment.ICreate,
  });
  typia.assert(comment);

  // 5. Prepare report type
  const reportTypeId = typia.random<string & tags.Format<"uuid">>();

  // 6. Create a report on the comment by memberB
  const reportCreatedAt = new Date().toISOString();
  const reportBody: IDiscussionboardCommentReport.ICreate = {
    discussionboard_comment_id: comment.id,
    discussionboard_member_id: memberB.id,
    discussionboard_report_type_id: reportTypeId,
    reason: RandomGenerator.paragraph()(5),
    created_at: reportCreatedAt,
  };
  const report = await api.functional.discussionboard.commentReports.create(connection, {
    body: reportBody,
  });
  typia.assert(report);
  TestValidator.equals("report.comment id")(report.discussionboard_comment_id)(comment.id);
  TestValidator.equals("report.member id")(report.discussionboard_member_id)(memberB.id);
  TestValidator.equals("report.type id")(report.discussionboard_report_type_id)(reportTypeId);
  TestValidator.equals("report.reason")(report.reason)(reportBody.reason);
  TestValidator.equals("report.created_at")(report.created_at)(reportCreatedAt);

  // 7. Attempt a duplicate report (identical data)
  await TestValidator.error("Duplicate report must fail")(
    async () => {
      await api.functional.discussionboard.commentReports.create(connection, {
        body: reportBody,
      });
    },
  );
