import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that the post vote search endpoint returns empty results or appropriate error responses
 * when queried with invalid or non-existent filter values (such as fake post id, member id, or incorrect vote_type).
 *
 * This test ensures that the API:
 *   - Does not leak data with invalid filter combinations
 *   - Properly handles syntactically valid but non-existent ids
 *   - Responds gracefully and in accordance with schema and business logic for out-of-range or enum-restricted parameters
 *   - Returns empty data arrays when there is no match
 *
 * Steps:
 * 1. Create a valid member (for reference, but search will use a non-existent member id)
 * 2. Create a valid post (for reference, but search will use a non-existent post id)
 * 3. Attempt to search post votes with a completely non-existent (random) post id - should return empty results
 * 4. Attempt to search post votes with a completely non-existent (random) member id - should return empty results
 * 5. Attempt to search post votes filtered by an illegal vote_type (should be only -1, 0, or 1) - API should handle robustly (if schema allows passing, returns empty; if not, return error)
 * 6. Attempt to search with both non-existent post id and member id - should return empty results
 * 7. Attempt to search with all invalid values together - should return empty results or appropriate error
 */
export async function test_api_discussionboard_test_list_post_votes_with_invalid_filter_returns_empty_or_error(
  connection: api.IConnection,
) {
  // 1. Create a valid member (for context, but won't use existing id in searches)
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<'email'>>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(member);

  // 2. Create a valid post (for context, but won't use existing id in searches)
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<'uuid'>>(),
      discussionboard_member_id: member.id,
      discussionboard_board_id: typia.random<string & tags.Format<'uuid'>>(),
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()(1)(),
      is_deleted: false,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    },
  });
  typia.assert(post);

  // Generate fake/non-existent ids
  const nonExistentPostId = typia.random<string & tags.Format<'uuid'>>();
  const nonExistentMemberId = typia.random<string & tags.Format<'uuid'>>();
  // Vote type only allows -1, 0, 1
  const illegalVoteType = 99;

  // 3. Search votes with non-existent post id
  const searchByFakePost = await api.functional.discussionboard.postVotes.index(connection, {
    body: {
      discussionboard_post_id: nonExistentPostId,
    },
  });
  typia.assert(searchByFakePost);
  TestValidator.equals("no votes for fake post id")(searchByFakePost.data)([]);

  // 4. Search votes with non-existent member id
  const searchByFakeMember = await api.functional.discussionboard.postVotes.index(connection, {
    body: {
      discussionboard_member_id: nonExistentMemberId,
    },
  });
  typia.assert(searchByFakeMember);
  TestValidator.equals("no votes for fake member id")(searchByFakeMember.data)([]);

  // 5. Search with illegal vote_type (should fail or return empty per schema enforcement)
  await TestValidator.error("illegal vote_type rejected")(async () => {
    await api.functional.discussionboard.postVotes.index(connection, {
      body: {
        vote_type: illegalVoteType as any,
      },
    });
  });

  // 6. Search with both non-existent post & member ids
  const searchByBoth = await api.functional.discussionboard.postVotes.index(connection, {
    body: {
      discussionboard_post_id: nonExistentPostId,
      discussionboard_member_id: nonExistentMemberId,
    },
  });
  typia.assert(searchByBoth);
  TestValidator.equals("no votes for fake post+member")(searchByBoth.data)([]);

  // 7. Search with all invalid values together
  await TestValidator.error("illegal vote_type with fake ids rejected")(async () => {
    await api.functional.discussionboard.postVotes.index(connection, {
      body: {
        discussionboard_post_id: nonExistentPostId,
        discussionboard_member_id: nonExistentMemberId,
        vote_type: illegalVoteType as any,
      },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
