import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IPostVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostVote";

/**
 * post vote 단건 조회가 정상 동작하는지 검증한다.
 *
 * 1. 투표를 위한 member 계정을 생성한다.
 * 2. 해당 멤버로 게시글을 1개 생성한다.
 * 3. 생성된 post에 멤버가 vote 기록을 1건 생성한다 (vote_type은 -1/0/1 랜덤)
 * 4. 생성된 vote의 id로 postVotes.at()을 호출하여 단건 조회
 * 5. 조회 결과와 생성 입력값이 완전히 일치하는지, 필드 값과 schema strictness까지 모두 검증
 */
export async function test_api_discussionboard_test_get_post_vote_by_valid_id_returns_vote(
  connection: api.IConnection,
) {
  // 1. 회원 계정 생성
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member: IDiscussionboardMember = await api.functional.discussionboard.members.create(
    connection,
    {
      body: {
        username: RandomGenerator.alphabets(8),
        email: memberEmail,
        hashed_password: RandomGenerator.alphaNumeric(12),
        role: RandomGenerator.pick(["member", "moderator", "admin"]),
        is_active: true,
      } satisfies IDiscussionboardMember.ICreate,
    }
  );
  typia.assert(member);

  // 2. 게시글 1건 생성
  const post: IDiscussionboardPost = await api.functional.discussionboard.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_member_id: member.id,
        discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
        title: RandomGenerator.paragraph()(1),
        body: RandomGenerator.content()(2)(),
        is_deleted: false,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      } satisfies IDiscussionboardPost.ICreate,
    }
  );
  typia.assert(post);

  // 3. vote 생성
  const voteType = RandomGenerator.pick([-1, 0, 1]) as -1|0|1;
  const voteInput: IPostVote.ICreate = {
    discussionboard_post_id: post.id,
    discussionboard_member_id: member.id,
    vote_type: voteType,
    created_at: new Date().toISOString(),
  };
  const vote: IPostVote = await api.functional.discussionboard.postVotes.create(
    connection,
    { body: voteInput }
  );
  typia.assert(vote);

  // 4. 생성된 vote id로 단건 조회
  const fetched: IPostVote = await api.functional.discussionboard.postVotes.at(
    connection,
    { id: vote.id }
  );
  typia.assert(fetched);

  // 5. 필드 값 정합성 및 스키마 strictness 검증
  TestValidator.equals("vote id")(fetched.id)(vote.id);
  TestValidator.equals("post id")(fetched.discussionboard_post_id)(post.id);
  TestValidator.equals("member id")(fetched.discussionboard_member_id)(member.id);
  TestValidator.equals("vote_type")(fetched.vote_type)(voteType);
  TestValidator.equals("created_at")(fetched.created_at)(vote.created_at);

  const keys = Object.keys(fetched).sort();
  const expectedKeys = [
    "id",
    "discussionboard_post_id",
    "discussionboard_member_id",
    "vote_type",
    "created_at"
  ].sort();
  TestValidator.equals("응답 스키마 strictness")(keys)(expectedKeys);
}

