 *
 * Steps:
 * 1. Register a new member for the discussion board.
 * 2. Have the member submit a data erasure request with status 'pending'.
 * 3. Attempt to submit a second "pending" erasure request for the same member.
 * 4. Confirm that the second request is rejected due to the business rule.
 *
 * The test ensures the backend properly blocks duplicate active requests, maintaining compliance for data management workflows.
 */
export async function test_api_discussionboard_dataerasurerequests_test_create_data_erasure_request_with_existing_pending_request(
  connection: api.IConnection,
) {
