 *
 * This test simulates the admin flow for handling a pending data erasure request.
 * Steps:
 *   1. Create a new member for the discussion board (as the requester)
 *   2. Create a new data erasure request for this member, status 'pending'
 *   3. As admin, update the request:
 *      - Set status to 'approved'
 *      - Set 'reviewed_at' (now)
 *      - Set 'completed_at' (shortly after reviewed_at)
 *      - Add an admin_remark
 *   4. Validate the update:
 *      - Status is now 'approved'
 *      - 'reviewed_at' < 'completed_at' (timestamps)
 *      - admin_remark is present and correct
 *      - All other fields remain correct (no unwanted changes)
 */
export async function test_api_discussionboard_dataErasureRequests_test_update_data_erasure_request_status_to_approved_with_admin_remark(
  connection: api.IConnection,
) {
  // 1. Create a member for data erasure request
  const memberData: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(10),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    role: "member",
    is_active: true,
  };
  const member = await api.functional.discussionboard.members.create(connection, {
    body: memberData,
  });
  typia.assert(member);

  // 2. Create pending data erasure request for the member
  const erasureRequestData: Idiscussionboard_data_erasure_requests.ICreate = {
    discussionboard_member_id: member.id,
    status: "pending",
    requested_at: new Date().toISOString(),
    admin_remark: null,
  };
  const erasure = await api.functional.discussionboard.dataErasureRequests.create(connection, {
    body: erasureRequestData,
  });
  typia.assert(erasure);

  // 3. Prepare and perform admin update (approve, timestamps, remark)
  const reviewedAt = new Date().toISOString();
  const completedAt = new Date(Date.parse(reviewedAt) + 60 * 1000).toISOString(); // +1min
  const adminRemark = "Approved for compliance, user identity confirmed.";
  const updateData: Idiscussionboard_data_erasure_requests.IUpdate = {
    status: "approved",
    reviewed_at: reviewedAt,
    completed_at: completedAt,
    admin_remark: adminRemark,
  };
  const updated = await api.functional.discussionboard.dataErasureRequests.update(
    connection,
    {
      id: erasure.id,
      body: updateData,
    },
  );
  typia.assert(updated);

  // 4. Validate business correctness
  TestValidator.equals("id matches")(updated.id)(erasure.id);
  TestValidator.equals("member id matches")(updated.discussionboard_member_id)(member.id);
  TestValidator.equals("status updated")(updated.status)("approved");
  TestValidator.equals("admin_remark updated")(updated.admin_remark)(adminRemark);
  TestValidator.predicate("reviewed_at < completed_at")(
    !!updated.reviewed_at && !!updated.completed_at && updated.reviewed_at < updated.completed_at
  );
  TestValidator.equals("requested_at unchanged")(updated.requested_at)(erasure.requested_at);
}

