import type { Idiscussionboard_data_erasure_requests } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_data_erasure_requests";

/**
 * 존재하지 않는(잘못된) 데이터 소거 요청 ID로 업데이트 시 에러 반환을 검증합니다.
 *
 * 데이터 소거 요청은 회원이 자신의 데이터 삭제를 요청할 때 생성합니다.
 * 관리자가 이미 존재하지 않는 ID나 잘못된 값을 넘겼을 때 제대로 방어되는지,
 * 시스템이 예외 상황에서 올바른 에러(예: 404 Not Found 등)를 반환함을 보장해야 합니다.
 * 이는 GDPR 등 개인정보 관련 법규 준수에도 중요한 테스트입니다.
 *
 * [테스트 절차]
 * 1. 임의의 UUID(존재하지 않는/잘못된 ID로 가정)를 생성한다.
 * 2. 데이터 소거 요청의 업데이트 request body를 준비한다.
 * 3. 해당 ID로 업데이트 API를 호출하고, 에러가 발생하는지 TestValidator.error로 검증한다.
 */
export async function test_api_discussionboard_dataErasureRequests_test_update_data_erasure_request_invalid_id_returns_error(
  connection: api.IConnection,
) {
  // 1. 무작위 UUID 생성(실제 존재하지 않는 값으로 간주)
  const invalidId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();

  // 2. 업데이트용 request body (최소 필수 필드로 구성)
  const updateBody: Idiscussionboard_data_erasure_requests.IUpdate = {
    status: "denied",
    admin_remark: "존재하지 않는 요청 ID 에러 처리 테스트"
  };

  // 3. 실제 호출하여 에러가 발생하는지 검증
  await TestValidator.error("존재하지 않는 ID로 업데이트 시 에러 반환")(
    async () => {
      await api.functional.discussionboard.dataErasureRequests.update(
        connection,
        {
          id: invalidId,
          body: updateBody,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { Idiscussionboard_data_erasure_requests } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_data_erasure_requests";

/**
 * Validate denial and field-change restrictions in data erasure request workflow.
 *
 * This test ensures that an admin can update a data erasure request's status to 'denied', optionally specifying a reviewed_at timestamp and admin_remark. It confirms business rules that in denied status, completed_at must not be set. The test performs the following:
 *
 * 1. Create a mock member using discussionboard.members.create for reference.
 * 2. Submit a new data erasure request for that member with status 'pending' and a unique requested_at value (discussionboard.dataErasureRequests.create).
 * 3. Attempt to update the request with status 'denied', a reviewed_at timestamp, and an admin_remark. Omit completed_at field.
 * 4. Assert the output has status 'denied', reviewed_at set as expected, admin_remark set as expected, and completed_at unset/null.
 * 5. Attempt to update the same request with status 'denied' but forcibly set completed_at; test that completed_at is either ignored, reset, or null (per business rules: a denied request must not have completed_at).
 * 6. Attempt to update other irrelevant or restricted fields (e.g., discussionboard_member_id, requested_at). Confirm these do not get changed.
 * 7. (Optional/error scenario) Attempt to update the denied request with completed_at only; expect either error or completed_at to not change (remains null).
 */
export async function test_api_discussionboard_data_erasure_requests_test_update_data_erasure_request_denied_and_validation_of_status_change(connection: api.IConnection) {
  // 1. Create a mock member
  const memberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(20),
    role: "member",
    is_active: true,
  };
  const member: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, { body: memberInput });
  typia.assert(member);

  // 2. Submit a new data erasure request (initial status 'pending')
  const requestedAt = new Date().toISOString();
  const erasureInput: Idiscussionboard_data_erasure_requests.ICreate = {
    discussionboard_member_id: member.id,
    status: "pending",
    requested_at: requestedAt,
    admin_remark: null,
  };
  const createdRequest: Idiscussionboard_data_erasure_requests = await api.functional.discussionboard.dataErasureRequests.create(connection, { body: erasureInput });
  typia.assert(createdRequest);

  // 3. Admin updates the request to status 'denied', setting reviewed_at and admin_remark. Omit completed_at.
  const reviewedAt = new Date().toISOString();
  const updateDenied: Idiscussionboard_data_erasure_requests.IUpdate = {
    status: "denied",
    reviewed_at: reviewedAt,
    admin_remark: "Request denied due to insufficient information.",
  };
  const deniedResult: Idiscussionboard_data_erasure_requests = await api.functional.discussionboard.dataErasureRequests.update(connection, {
    id: createdRequest.id,
    body: updateDenied,
  });
  typia.assert(deniedResult);

  // 4. Assert: status is 'denied', reviewed_at & admin_remark updated, completed_at is null, and other fields unchanged
  TestValidator.equals("status updated to denied")(deniedResult.status)("denied");
  TestValidator.equals("reviewed_at matches")(deniedResult.reviewed_at)(reviewedAt);
  TestValidator.equals("admin_remark set")(deniedResult.admin_remark)("Request denied due to insufficient information.");
  TestValidator.equals("completed_at should remain unset if denied")(deniedResult.completed_at)(null);
  TestValidator.equals("member id unchanged")(deniedResult.discussionboard_member_id)(member.id);
  TestValidator.equals("requested_at unchanged")(deniedResult.requested_at)(requestedAt);

  // 5. Attempt to set completed_at while status is still denied -- completed_at must remain null
  const now = new Date().toISOString();
  const updateWithCompletedAt: Idiscussionboard_data_erasure_requests.IUpdate = {
    status: "denied",
    completed_at: now,
    reviewed_at: deniedResult.reviewed_at,
    admin_remark: deniedResult.admin_remark,
  };
  const deniedWithCompletedAt: Idiscussionboard_data_erasure_requests = await api.functional.discussionboard.dataErasureRequests.update(connection, {
    id: createdRequest.id,
    body: updateWithCompletedAt,
  });
  typia.assert(deniedWithCompletedAt);
  TestValidator.equals("status still denied")(deniedWithCompletedAt.status)("denied");
  TestValidator.equals("completed_at must be null if denied")(deniedWithCompletedAt.completed_at)(null);

  // 6. Attempt to update restricted/irrelevant fields (member id / requested_at) - must not change
  const updateRestricted: Idiscussionboard_data_erasure_requests.IUpdate = {
    discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
    requested_at: new Date(Date.now() - 86400000).toISOString(), // a day before
  };
  const afterRestricted: Idiscussionboard_data_erasure_requests = await api.functional.discussionboard.dataErasureRequests.update(connection, {
    id: createdRequest.id,
    body: updateRestricted,
  });
  typia.assert(afterRestricted);
  TestValidator.equals("restricted member id should NOT change")(afterRestricted.discussionboard_member_id)(member.id);
  TestValidator.equals("restricted requested_at should NOT change")(afterRestricted.requested_at)(requestedAt);

  // 7. Optional: Try to update completed_at only, expect it to remain null
  const completedAtOnly: Idiscussionboard_data_erasure_requests.IUpdate = {
    completed_at: now,
  };
  const afterCompletedAtAttempt: Idiscussionboard_data_erasure_requests = await api.functional.discussionboard.dataErasureRequests.update(connection, {
    id: createdRequest.id,
    body: completedAtOnly,
  });
  typia.assert(afterCompletedAtAttempt);
  TestValidator.equals("completed_at remains null if only completed_at set")(afterCompletedAtAttempt.completed_at)(null);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { Idiscussionboard_data_erasure_requests } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_data_erasure_requests";

/**
 * Test permanent deletion (hard delete) of a data erasure request by its ID as performed by an admin.
 *
 * This test verifies:
 *   - Only an admin can permanently delete a data erasure request.
 *   - The deletion is irreversible (hard delete in schema: no deleted_at, no soft delete field).
 *   - After deletion, the record cannot be retrieved and does not exist in future delete attempts.
 *
 * **Test workflow:**
 * 1. Create a test member (to serve as request owner)
 * 2. Create a data erasure request for that member
 * 3. Delete the data erasure request as admin (per schema, admin privilege scope assumed here)
 * 4. Confirm the data erasure request no longer exists by trying to delete again (should error)
 *
 * If the system exposed a get/list for data erasure requests, those could be checked for non-existence, but here we validate only via delete endpoint and error handling.
 */
export async function test_api_discussionboard_test_delete_data_erasure_request_successful_for_admin(
  connection: api.IConnection,
) {
  // 1. Create a test member (the owner of the request)
  const memberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(10),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    role: "member",
    is_active: true,
  };
  const member = await api.functional.discussionboard.members.create(connection, { body: memberInput });
  typia.assert(member);

  // 2. Create a data erasure request for this member
  const now = new Date().toISOString();
  const requestInput: Idiscussionboard_data_erasure_requests.ICreate = {
    discussionboard_member_id: member.id,
    status: "pending",
    requested_at: now,
    admin_remark: null,
  };
  const erasureRequest = await api.functional.discussionboard.dataErasureRequests.create(connection, { body: requestInput });
  typia.assert(erasureRequest);

  // 3. Delete the data erasure request as admin (hard delete)
  await api.functional.discussionboard.dataErasureRequests.erase(connection, { id: erasureRequest.id });

  // 4. Attempt to delete again, expecting an error (confirms it no longer exists)
  await TestValidator.error("deleting already-deleted erasure request should fail")(async () => {
    await api.functional.discussionboard.dataErasureRequests.erase(connection, { id: erasureRequest.id });
  });
}

