/**
 * Test unauthorized post snapshot list access - enforce privacy compliance.
 *
 * This function tests that an unauthenticated user cannot access the snapshot
 * history for a post they do not own on the discussion board.
 * It ensures the API enforces privacy and access control for post version history,
 * as required by business/ACL policy.
 *
 * Steps:
 * 1. Pick a random discussionboard post UUID to simulate another user's post
 * 2. Send PATCH /discussionboard/postSnapshots as a guest (no authorization)
 *    - Expect API to return an authorization/access denied error
 *
 * Note: User authentication API is not available, so only the guest rejection case can be tested.
 */
export async function test_api_discussionboard_test_search_post_snapshots_without_permission(
  connection: api.IConnection,
) {
  // 1. Simulate targetting another user's post with a random UUID
  const targetPostId = typia.random<string & tags.Format<"uuid">>();
  const requestBody: IPostSnapshot.IRequest = {
    discussionboard_post_id: targetPostId,
    page: 1,
    limit: 5,
    editor_member_id: null,
    taken_at_from: null,
    taken_at_to: null,
  };

  // 2. Remove Authorization to simulate unauthenticated access (guest)
  delete connection.headers?.Authorization;

  // 3. Attempt to request post snapshots - expect access/authorization error
  await TestValidator.error("guest should not access another user's post snapshots")(
    async () => {
      await api.functional.discussionboard.postSnapshots.index(connection, {
        body: requestBody,
      });
    },
  );
