  TestValidator.predicate("empty result allowed")(Array.isArray(output.data));

  // 4. 임의의 존재하지 않는 event_type으로 요청하면 0건 반환되는지 확인
  const nonExistingType = "non_existing_type";
  const emptyOutput = await api.functional.discussionboard.activityLogs.index(connection, {
    body: {
      event_type: nonExistingType
    }
  });
  typia.assert(emptyOutput);
