 *
 * Test steps:
 * 1. Retrieve trending topics with default retrieval (default backend order).
 * 2. Retrieve trending topics again and verify sort by trending_score ascending (if API returns in that order).
 * 3. Retrieve trending topics again and verify sort by ranking_period_date descending (if API returns in that order).
 * 4. Confirm all returned topics have non-null trending_score and ranking_period_date.
 *
 * The purpose is to validate analytics users/admins see consistent, sortable, and predictable trending topic data for dashboard/report usage, to the extent possible given schema.
 */
export async function test_api_discussionboard_test_trending_topics_sorting(
  connection: api.IConnection,
) {
  // 1. Retrieve trending topics (default order)
  const defaultResult = await api.functional.discussionboard.trendingTopics.index(connection, {
    body: {},
  });
  typia.assert(defaultResult);

  // 2. Attempt to verify topics are sorted by trending_score ascending
  // (API schema does not expose explicit sort parameter)
  const trendingScoreResult = await api.functional.discussionboard.trendingTopics.index(connection, {
    body: {},
  });
