/**
 * Test retrieving a post reference by an id that does not exist.
 *
 * Ensures that the API correctly handles queries for missing post references
 * and does not expose any data of non-existent records. This is essential
 * for privacy and to prevent user guessing attacks.
 *
 * Steps:
 * 1. Generate a random UUID that does not correspond to any real post reference record.
 * 2. Attempt to get the post reference by this ID via the GET /discussionboard/postReferences/{id} endpoint.
 * 3. Verify that the response is either null or throws an appropriate not found error.
 * 4. Ensure the API never leaks details about non-existent records in its response.
 */
export async function test_api_discussionboard_test_get_post_reference_not_found(
  connection: api.IConnection,
) {
  // 1. Generate a random UUID not assigned to any post reference
  const invalidId = typia.random<string & tags.Format<"uuid">>();

  // 2 & 3. Attempt to fetch with that ID and verify response/null/error
  await TestValidator.error("should throw not found or return null for non-existent post reference")(async () => {
    const result = await api.functional.discussionboard.postReferences.at(connection, {
      id: invalidId,
    });
    // If API returns null, this is allowed. Consider that as a valid result: error is expected, but null may also be correct.
    if (result === null) return; // Acceptable: API returns null for missing record
