    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 4. Create parent comment (top-level, no parent_id)
  const parentComment = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: author_member_id,
      body: RandomGenerator.content()()(),
    } satisfies IComment.ICreate,
  });
  typia.assert(parentComment);

  // 5. Create reply comment (nested under parent), set parent_id
  const replyComment = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: author_member_id,
      parent_id: parentComment.id,
      body: RandomGenerator.content()()(),
    } satisfies IComment.ICreate,
  });
  typia.assert(replyComment);

  // Validate reply's parent_id, post, and member
  TestValidator.equals("reply parent_id")(replyComment.parent_id)(parentComment.id);
  TestValidator.equals("reply post id")(replyComment.discussionboard_post_id)(post.id);
  TestValidator.equals("reply member id")(replyComment.discussionboard_member_id)(author_member_id);
}

